def ensure_colbert_hybrid_dense_proxies(
    conn: psycopg.Connection[Any],
    args: argparse.Namespace,
) -> dict[str, Any]:
    started = time.perf_counter()
    ensure_colbert_hybrid_proxy_tables(conn)
    encoder = str(getattr(args, "colbert_hybrid_dense_proxy_encoder", "normalized_mean"))
    centroid_count = str(getattr(args, "multivector_centroid_count", "auto"))
    batch_size = max(1, int(getattr(args, "colbert_hybrid_proxy_batch_size", 1024) or 1024))
    if bool(getattr(args, "colbert_hybrid_rebuild_dense_proxy", False)):
        exec_sql(conn, "TRUNCATE dbpedia_colbert_hybrid_proxy_docs")
        exec_sql(conn, "TRUNCATE dbpedia_colbert_hybrid_proxy_queries")
    before = fetch_one(
        conn,
        """
        SELECT
          (SELECT count(*) FILTER (WHERE colbert IS NOT NULL) FROM dbpedia_colbert_docs),
          (SELECT count(*) FROM dbpedia_colbert_hybrid_proxy_docs),
          (SELECT count(*) FILTER (WHERE colbert IS NOT NULL) FROM dbpedia_colbert_queries),
          (SELECT count(*) FROM dbpedia_colbert_hybrid_proxy_queries)
        """,
    )
    docs_total = int(before[0] or 0) if before else 0
    docs_ready = int(before[1] or 0) if before else 0
    queries_total = int(before[2] or 0) if before else 0
    queries_ready = int(before[3] or 0) if before else 0
    doc_seen = doc_updated = query_seen = query_updated = 0
    if docs_ready < docs_total:
        doc_seen, doc_updated = materialize_colbert_hybrid_doc_proxy_batch(
            conn,
            encoder=encoder,
            centroid_count=centroid_count,
            batch_size=batch_size,
        )
    if queries_ready < queries_total:
        query_seen, query_updated = materialize_colbert_hybrid_query_proxy_batch(
            conn,
            encoder=encoder,
            centroid_count=centroid_count,
            batch_size=batch_size,
        )
    after = fetch_one(
        conn,
        """
        SELECT
          (SELECT count(*) FILTER (WHERE colbert IS NOT NULL) FROM dbpedia_colbert_docs),
          (SELECT count(*) FROM dbpedia_colbert_hybrid_proxy_docs),
          (SELECT count(*) FILTER (WHERE colbert IS NOT NULL) FROM dbpedia_colbert_queries),
          (SELECT count(*) FROM dbpedia_colbert_hybrid_proxy_queries)
        """,
    )
    return {
        "encoder": encoder,
        "centroid_count": centroid_count,
        "document_proxy_table": "dbpedia_colbert_hybrid_proxy_docs",
        "query_proxy_table": "dbpedia_colbert_hybrid_proxy_queries",
        "batch_size": batch_size,
        "elapsed_ms": elapsed_ms_since(started),
        "documents_total": int(after[0] or 0) if after else docs_total,
        "documents_ready": int(after[1] or 0) if after else docs_ready,
        "queries_total": int(after[2] or 0) if after else queries_total,
        "queries_ready": int(after[3] or 0) if after else queries_ready,
        "document_rows_scanned": doc_seen,
        "document_rows_updated": doc_updated,
        "query_rows_scanned": query_seen,
        "query_rows_updated": query_updated,
        "reused": (
            docs_ready == docs_total
            and queries_ready == queries_total
            and not bool(getattr(args, "colbert_hybrid_rebuild_dense_proxy", False))
        ),
    }


def proxy_exact_scan_doc_proxy(
    doc: ProxyExactScanDoc,
    encoder: str,
    centroid_count: str,
) -> list[float]:
    key = (encoder, str(centroid_count))
    proxy = doc.proxies.get(key)
    if proxy is None:
        proxy = build_proxy_exact_scan_vector(doc.vectors, encoder, str(centroid_count))
        doc.proxies[key] = proxy
    return proxy


def exact_maxsim_score(query_vectors: list[list[float]], doc_vectors: list[list[float]]) -> float:
    if not query_vectors or not doc_vectors:
        return 0.0
    total = 0.0
    for query_vector in query_vectors:
        total += max(vector_dot(query_vector, doc_vector) for doc_vector in doc_vectors)
    return total


def load_proxy_exact_scan_oracle(conn: psycopg.Connection[Any]) -> ProxyExactScanOracle:
    doc_rows = fetch_all(
        conn,
        """
        SELECT d.doc_id,
               d.ctid::text,
               ARRAY(
                 SELECT v::text
                 FROM unnest(turbohybrid_multivector_to_vector_array(d.colbert)) AS v
               ) AS vectors
        FROM dbpedia_colbert_docs d
        WHERE d.colbert IS NOT NULL
        ORDER BY d.doc_id
        """,
    )
    query_rows = fetch_all(
        conn,
        """
        SELECT q.query_id,
               ARRAY(
                 SELECT v::text
                 FROM unnest(turbohybrid_multivector_to_vector_array(q.colbert)) AS v
               ) AS vectors
        FROM dbpedia_colbert_queries q
        WHERE q.colbert IS NOT NULL
        ORDER BY q.query_id
        """,
    )
    docs: list[ProxyExactScanDoc] = []
    dimension = 0
    for doc_id, tid_text, vectors_value in doc_rows:
        vectors = parse_vector_text_array(vectors_value)
        if vectors and dimension == 0:
            dimension = len(vectors[0])
        block, offset = tid_parts(str(tid_text))
        docs.append(
            ProxyExactScanDoc(
                doc_id=str(doc_id),
                heap_block=block,
                heap_offset=offset,
                vectors=vectors,
            )
        )
    queries = {
        str(query_id): parse_vector_text_array(vectors_value)
        for query_id, vectors_value in query_rows
    }
    if not docs:
        raise RuntimeError("proxy_exact_scan diagnostic found no loaded document multivectors")
    if not queries:
        raise RuntimeError("proxy_exact_scan diagnostic found no loaded query multivectors")
    return ProxyExactScanOracle(docs=docs, queries=queries, dimension=dimension)


def proxy_exact_rank_summary(exact_top_with_admission: list[dict[str, Any]]) -> dict[str, Any]:
    ranks = [
        int(item["candidate_rank_before_rerank"])
        for item in exact_top_with_admission[:10]
        if item.get("candidate_rank_before_rerank") is not None
    ]
    return {
        "proxy_exact_rank_of_exact_top1": (
            int(exact_top_with_admission[0]["candidate_rank_before_rerank"])
            if exact_top_with_admission
            and exact_top_with_admission[0].get("candidate_rank_before_rerank") is not None
            else None
        ),
        "proxy_exact_rank_of_exact_top10_p50": (
            round(percentile([float(rank) for rank in ranks], 50), 3) if ranks else None
        ),
        "proxy_exact_rank_of_exact_top10_p95": (
            round(percentile([float(rank) for rank in ranks], 95), 3) if ranks else None
        ),
    }


def run_proxy_exact_scan_admission_budget(
    oracle: ProxyExactScanOracle,
    query: QueryItem,
    args: argparse.Namespace,
    budget: int,
    exact_top: list[dict[str, Any]],
    exact_rerank_k: int,
) -> dict[str, Any]:
    if str(getattr(args, "multivector_graph", "")) != "document_nodes":
        raise RuntimeError("proxy_exact_scan requires multivector_graph = document_nodes")
    query_vectors = oracle.queries.get(query.query_id)
    if query_vectors is None:
        raise RuntimeError(f"proxy_exact_scan query {query.query_id!r} has no multivector")
    encoder = str(getattr(args, "multivector_proxy_encoder", "normalized_mean") or "normalized_mean")
    centroid_count = str(getattr(args, "multivector_centroid_count", "auto") or "auto")
    final_k = max(args.final_k, args.admission_k)
    started = time.perf_counter()
    query_proxy = build_proxy_exact_scan_vector(query_vectors, encoder, centroid_count)
    scored = [
        (vector_dot(query_proxy, proxy_exact_scan_doc_proxy(doc, encoder, centroid_count)), doc)
        for doc in oracle.docs
    ]
    scored.sort(key=lambda item: (-item[0], item[1].doc_id))
    proxy_scan_time_us = int(round((time.perf_counter() - started) * 1_000_000.0))
    proxy_rank_by_doc_id = {
        doc.doc_id: rank
        for rank, (_score, doc) in enumerate(scored, start=1)
    }
    candidates = [doc for _score, doc in scored[: max(0, int(budget))]]
    rerank_docs = candidates[: max(0, min(int(exact_rerank_k), len(candidates)))]
    rerank_started = time.perf_counter()
    exact_scores = [
        (exact_maxsim_score(query_vectors, doc.vectors), doc)
        for doc in rerank_docs
    ]
    exact_scores.sort(key=lambda item: (-item[0], item[1].doc_id))
    exact_rerank_time_us = int(round((time.perf_counter() - rerank_started) * 1_000_000.0))
    docs = [doc.doc_id for _score, doc in exact_scores[:final_k]]
    result_rank_by_doc_id = {
        doc_id: rank
        for rank, doc_id in enumerate(docs, start=1)
    }
    exact_score_by_doc_id = {
        doc.doc_id: score
        for score, doc in exact_scores
    }
    exact_top_with_admission: list[dict[str, Any]] = []
    for exact in exact_top:
        doc_id = str(exact["doc_id"])
        proxy_rank = proxy_rank_by_doc_id.get(doc_id)
        admitted = proxy_rank is not None and proxy_rank <= int(budget)
        retained = proxy_rank is not None and proxy_rank <= len(rerank_docs)
        exact_top_with_admission.append({
            "rank": exact["rank"],
            "doc_id": doc_id,
            "admitted_before_rerank": admitted,
            "admission_evidence": "proxy_exact_scan",
            "candidate_rank_before_rerank": proxy_rank,
            "retained_for_exact_rerank": retained,
            "exact_rerank_score": exact_score_by_doc_id.get(doc_id),
            "exact_rerank_rank": result_rank_by_doc_id.get(doc_id),
        })
    top10 = exact_top[: min(10, len(exact_top))]
    top10_admitted = sum(
        1
        for item in exact_top_with_admission[: len(top10)]
        if item["admitted_before_rerank"]
    )
    top1_admission = bool(
        exact_top_with_admission and exact_top_with_admission[0]["admitted_before_rerank"]
    )
    rank_summary = proxy_exact_rank_summary(exact_top_with_admission)
    exact_rerank_pairs = len(query_vectors) * sum(len(doc.vectors) for doc in rerank_docs)
    latency_ms = (proxy_scan_time_us + exact_rerank_time_us) / 1000.0
    stats = {
        "observed_latency_ms": latency_ms,
        "multivector_candidate_source": "proxy_exact_scan",
        "multivector_doc_graph_warning": "benchmark_proxy_exact_scan_diagnostic_only",
        "multivector_doc_graph_rescore_source": "proxy_exact_scan_sidecar",
        "proxy_encoder_kind": encoder,
        "proxy_exact_scan_enabled": True,
        "proxy_exact_scan_diagnostic_only": True,
        "proxy_exact_scan_docs_scored": len(oracle.docs),
        "proxy_exact_scan_time_us": proxy_scan_time_us,
        "proxy_exact_scan_candidates": len(candidates),
        "proxy_exact_scan_top10_admission_recall": (
            round(top10_admitted / len(top10), 6) if top10 else 0.0
        ),
        "proxy_exact_scan_top1_admission": top1_admission,
        "proxy_exact_scan_vs_hnsw_gap": None,
        "hnsw_vs_exact_proxy_top10_gap": None,
        **rank_summary,
        "proxy_candidates": len(candidates),
        "proxy_candidates_returned": len(candidates),
        "multivector_proxy_candidates_returned": len(candidates),
        "multivector_doc_graph_docs_scored": len(oracle.docs),
        "multivector_doc_graph_candidates": len(candidates),
        "multivector_exact_rerank_docs": len(rerank_docs),
        "multivector_exact_rerank_pairs": exact_rerank_pairs,
        "multivector_exact_kernel": "python_scalar_diagnostic",
        "multivector_candidate_source_time_us": proxy_scan_time_us,
        "multivector_proxy_candidate_time_us": proxy_scan_time_us,
        "multivector_proxy_scoring_time_us": proxy_scan_time_us,
        "multivector_exact_maxsim_rerank_time_us": exact_rerank_time_us,
    }
    candidate_diagnostics = derive_candidate_underfill_diagnostics({
        "candidate_budget": budget,
        "candidate_source": "proxy_exact_scan",
        "final_k": args.final_k,
        "effective_exact_rerank_k": exact_rerank_k,
        "proxy_candidates": len(candidates),
        "last_scan_stats_sample": stats,
    })
    return {
        "budget": budget,
        **candidate_diagnostics,
        "admission_debug_mode": effective_admission_debug_mode(args),
        "trace_enabled": False,
        "serving_exact_rerank_mode": getattr(args, "serving_exact_rerank_mode", "admission_exhaustive"),
        "requested_serving_exact_rerank_k": int(getattr(args, "serving_exact_rerank_k", 100)),
        "effective_exact_rerank_k": exact_rerank_k,
        "candidate_source": "proxy_exact_scan",
        "plain_fallback_used": False,
        "plain_fallback_reason": "not_applicable",
        "doc_graph_docs_scored": len(oracle.docs),
        "doc_graph_edges_visited": 0,
        "doc_graph_candidates": len(candidates),
        "doc_graph_heap_fetches": 0,
        "doc_graph_warning": "benchmark_proxy_exact_scan_diagnostic_only",
        "proxy_candidates": len(candidates),
        "proxy_exact_rerank_docs": len(rerank_docs),
        "latency_ms": latency_ms,
        "latency": {"ms": latency_ms},
        "retrieval_elapsed_ms": latency_ms,
        "retrieval_query_count": 1,
        "result_doc_ids": docs,
        "exact_top1_admission": top1_admission,
        "exact_top1_admitted": top1_admission,
        "exact_top1_admitted_before_rerank": top1_admission,
        "exact_top10_admission_recall": round(top10_admitted / len(top10), 6) if top10 else 0.0,
        "exact_top1_candidate_rank_before_rerank": rank_summary["proxy_exact_rank_of_exact_top1"],
        "exact_top1_rank": (
            exact_top_with_admission[0]["exact_rerank_rank"] if exact_top_with_admission else None
        ),
        "exact_top1_exact_rerank_rank": (
            exact_top_with_admission[0]["exact_rerank_rank"] if exact_top_with_admission else None
        ),
        "docs_scored": len(oracle.docs),
        "graph_edges_visited": 0,
        "exact_rerank_docs": len(rerank_docs),
        "exact_rerank_pairs": exact_rerank_pairs,
        "exact_rerank_tokens_evaluated": exact_rerank_pairs,
        "exact_rerank_tokens_skipped": 0,
        "exact_rerank_pairs_saved": 0,
        "sidecar_stats": {
            "sidecar_vectors_loaded": len(rerank_docs),
            "sidecar_bytes_touched": 0,
            "sidecar_pages_read": 0,
        },
        "doc_graph_rescore_source": "proxy_exact_scan_sidecar",
        "trace_available": False,
        "trace_entries": 0,
        "admission_inferred_from_result_docs": False,
        "admission_evidence_mode": "proxy_exact_scan",
        "pre_rerank_admission_source": "proxy_exact_scan",
        "pre_rerank_admission_limitations": None,
        "exact_top": exact_top_with_admission,
        "scan_stats": stats,
        **rank_summary,
        "proxy_exact_scan_enabled": True,
        "proxy_exact_scan_diagnostic_only": True,
        "proxy_exact_scan_docs_scored": len(oracle.docs),
        "proxy_exact_scan_time_us": proxy_scan_time_us,
        "proxy_exact_scan_candidates": len(candidates),
        "proxy_exact_scan_top10_admission_recall": (
            round(top10_admitted / len(top10), 6) if top10 else 0.0
        ),
        "proxy_exact_scan_top1_admission": top1_admission,
        "proxy_exact_scan_vs_hnsw_gap": None,
        "hnsw_vs_exact_proxy_top10_gap": None,
    }


def trace_key(entry: dict[str, Any]) -> tuple[int, int] | None:
    try:
        return int(entry["heap_block"]), int(entry["heap_offset"])
    except (KeyError, TypeError, ValueError):
        return None


def can_infer_admission_from_result_docs(
    candidate_source: Any,
    *,
    fallback_used: bool = False,
    plain_fallback: Any = None,
    graph_mode: Any = None,
) -> bool:
    """Return whether final result membership proves exact-rerank admission.

    Some document-level paths exact-rerank candidate documents but do not emit a
    bounded per-document admission trace. In those cases, a returned exact-top
    document proves it was admitted and retained for exact rerank, but not its
    pre-rerank candidate rank.
    """
    if fallback_used or plain_fallback == "force":
        return True
    if graph_mode == "document_nodes":
        return True
    return candidate_source in {
        "exact_doc_scan",
        "doc_graph_prototype",
        "plain_fallback",
        "document_nodes",
        "proxy_vector",
        "quantized_inverted_experimental",
    }


def scan_stat_int(stats: dict[str, Any], key: str) -> int:
    value = stats.get(key, 0)
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0


def scan_stat_float(stats: dict[str, Any], key: str) -> float:
    value = stats.get(key, 0.0)
    try:
        result = float(value)
    except (TypeError, ValueError):
        return 0.0
    return result if math.isfinite(result) else 0.0


def scan_stat_bool(stats: dict[str, Any], key: str) -> bool:
    return stats.get(key) is True or stats.get(key) == "true"


def scan_stat_str(stats: dict[str, Any], key: str) -> str | None:
    value = stats.get(key)
    return value if isinstance(value, str) else None


def storage_capabilities_from_stats(
    stats: dict[str, Any] | None,
    *,
    fallback_storage_kind: str | None = None,
) -> dict[str, Any]:
    if not isinstance(stats, dict):
        stats = {}
    storage_kind = (
        scan_stat_str(stats, "multivector_doc_storage_kind")
        or scan_stat_str(stats, "multivector_doc_storage")
        or fallback_storage_kind
    )
    return {
        "multivector_doc_storage_kind": storage_kind,
        "proxy_only_index": (
            scan_stat_bool(stats, "proxy_only_index")
            if "proxy_only_index" in stats
            else (storage_kind == "proxy_only" if storage_kind is not None else None)
        ),
        "centroid_only_index": (
            scan_stat_bool(stats, "centroid_only_index")
            if "centroid_only_index" in stats
            else (storage_kind == "centroid_only" if storage_kind is not None else None)
        ),
        "full_multivector_sidecar_available": (
            scan_stat_bool(stats, "full_multivector_sidecar_available")
            if "full_multivector_sidecar_available" in stats
            else (
                storage_kind not in {"proxy_only", "centroid_only"}
                if storage_kind is not None
                else None
            )
        ),
        "centroid_sidecar_available": (
            scan_stat_bool(stats, "centroid_sidecar_available")
            if "centroid_sidecar_available" in stats
            else None
        ),
        "centroid_doc_codes_available": (
            scan_stat_bool(stats, "centroid_doc_codes_available")
            if "centroid_doc_codes_available" in stats
            else None
        ),
        "quantized_inverted_sidecar_available": (
            scan_stat_bool(stats, "quantized_inverted_sidecar_available")
            if "quantized_inverted_sidecar_available" in stats
            else None
        ),
        "exact_rerank_source_supported": scan_stat_str(
            stats,
            "exact_rerank_source_supported",
        ),
    }


def serving_storage_memory_fields(
    *,
    build_stats: dict[str, Any],
    index_phase: dict[str, Any],
) -> dict[str, Any]:
    estimate = index_phase.get("build_resource_estimate", {})
    if not isinstance(estimate, dict):
        estimate = {}
    estimate_components = estimate.get("estimate_components", {})
    if not isinstance(estimate_components, dict):
        estimate_components = {}

    def stat_int(*keys: str) -> int | None:
        for key in keys:
            value = build_stats.get(key)
            if value is None or isinstance(value, bool):
                continue
            try:
                return max(int(value), 0)
            except (TypeError, ValueError, OverflowError):
                continue
        return None

    def estimate_int(*keys: str) -> int:
        total = 0
        for key in keys:
            try:
                total += max(int(estimate_components.get(key, 0) or 0), 0)
            except (TypeError, ValueError, OverflowError):
                continue
        return total

    source = "build_stats"
    docmap_bytes = stat_int("multivector_docmap_bytes_estimate")
    if docmap_bytes is None:
        docmap_bytes = estimate_int("docmap")
        source = "estimate"

    sidecar_bytes = stat_int("multivector_doc_sidecar_bytes_estimate")
    if sidecar_bytes is None:
        sidecar_bytes = estimate_int(
            "full_multivector_sidecar",
            "centroid_vectors",
            "centroid_postings",
            "quantized_postings",
            "entry_sidecar",
        )
        source = "estimate"

    graph_node_bytes = stat_int("graph_node_bytes_estimate")
    graph_neighbor_bytes = stat_int("graph_neighbor_bytes_estimate")
    graph_bytes: int | None = None
    if graph_node_bytes is not None or graph_neighbor_bytes is not None:
        graph_bytes = int(graph_node_bytes or 0) + int(graph_neighbor_bytes or 0)
    if graph_bytes is None:
        graph_bytes = estimate_int("graph_nodes", "graph_edges", "proxy_vectors")
        source = "estimate"

    return {
        "docmap_bytes": int(docmap_bytes or 0),
        "sidecar_bytes": int(sidecar_bytes or 0),
        "graph_bytes": int(graph_bytes or 0),
        "storage_memory_bytes_source": (
            source if any((docmap_bytes, sidecar_bytes, graph_bytes)) else "unavailable"
        ),
    }


def memory_estimate_from_stats(stats: dict[str, Any]) -> int:
    return scan_stat_int(stats, "multivector_memory_bytes_estimate")


def scan_docs_scored(stats: dict[str, Any]) -> int:
    return max(
        scan_stat_int(stats, "multivector_doc_graph_docs_scored"),
        scan_stat_int(stats, "multivector_plain_fallback_docs_scored"),
        scan_stat_int(stats, "multivector_doc_candidates"),
        scan_stat_int(stats, "multivector_unique_docs"),
    )


def scan_graph_edges_visited(stats: dict[str, Any]) -> int:
    return scan_stat_int(stats, "multivector_doc_graph_edges_visited")


def scan_exact_rerank_docs(stats: dict[str, Any]) -> int:
    return max(
        scan_stat_int(stats, "multivector_exact_rerank_docs"),
        scan_stat_int(stats, "multivector_doc_graph_exact_rerank_docs"),
    )


def serving_simd_expected() -> bool:
    forced_values = {
        os.environ.get("SIMD_BUILD", ""),
        os.environ.get("PGTURBOHYBRID_SIMD_BUILD", ""),
        os.environ.get("PGTURBOHYBRID_DENSE_EXACT_SIMD_FORCE", ""),
        os.environ.get("PGTURBOHYBRID_DENSE_SIMD_FORCE", ""),
    }
    return not any(str(value).lower() in {"none", "off", "scalar"} for value in forced_values)


def validate_serving_scan_path(
    stats: dict[str, Any],
    args: argparse.Namespace,
    profile: DocumentNodeServingProfile,
) -> list[str]:
    warnings: list[str] = []
    if not isinstance(stats, dict):
        return ["missing_scan_stats"]

    expected_source = profile.candidate_source
    observed_source = scan_stat_str(stats, "multivector_candidate_source")
    if observed_source is not None and observed_source != expected_source:
        warnings.append(
            "candidate_source_mismatch:"
            f"expected={expected_source},observed={observed_source}"
        )

    if scan_stat_bool(stats, "multivector_plain_fallback_used"):
        warnings.append("plain_fallback_used")
    fallback_reason = scan_stat_str(stats, "multivector_plain_fallback_reason")
    if fallback_reason not in (None, "", "not_applicable"):
        warnings.append(f"plain_fallback_reason:{fallback_reason}")

    doc_warning = scan_stat_str(stats, "multivector_doc_graph_warning")
    if (
        doc_warning is not None
        and "document_node_f32_sidecar_exact_scan" in doc_warning
        and expected_source != "exact_doc_scan"
    ):
        warnings.append(f"doc_graph_warning:{doc_warning}")

    storage_caps = storage_capabilities_from_stats(
        stats,
        fallback_storage_kind=profile.storage_kind,
    )
    storage_kind = storage_caps.get("multivector_doc_storage_kind")
    full_sidecar_available = storage_caps.get("full_multivector_sidecar_available")
    if storage_kind == "proxy_only" and full_sidecar_available is True:
        warnings.append("proxy_only_full_sidecar_unexpected")
    if storage_kind == "centroid_only" and full_sidecar_available is True:
        warnings.append("centroid_only_full_sidecar_unexpected")
    exact_source_supported = storage_caps.get("exact_rerank_source_supported")
    runtime_exact_source = scan_stat_str(stats, "multivector_exact_rerank_source")
    if (
        exact_source_supported in {"heap", "none"}
        and runtime_exact_source == "sidecar"
    ):
        warnings.append(
            "exact_sidecar_requested_but_missing:"
            f"storage={storage_kind},supported={exact_source_supported}"
        )

    exact_rerank_docs = scan_exact_rerank_docs(stats)
    configured_rerank_k = int(
        getattr(
            args,
            "multivector_exact_rerank_k",
            getattr(args, "serving_exact_rerank_k", 0),
        )
        or 0
    )
    rerank_tolerance = max(2, int(math.ceil(max(configured_rerank_k, 1) * 0.05)))
    if configured_rerank_k > 0 and exact_rerank_docs > configured_rerank_k + rerank_tolerance:
        warnings.append(
            "exact_rerank_docs_exceeds_serving_budget:"
            f"observed={exact_rerank_docs},limit={configured_rerank_k},tolerance={rerank_tolerance}"
        )
        if runtime_exact_source == "heap":
            warnings.append(
                "heap_rerank_unbounded:"
                f"observed={exact_rerank_docs},limit={configured_rerank_k},tolerance={rerank_tolerance}"
            )

    loaded_document_count = int(getattr(args, "serving_loaded_document_count", 0) or 0)
    docs_scored = scan_docs_scored(stats)
    doc_graph_docs_scored = scan_stat_int(stats, "multivector_doc_graph_docs_scored")
    if loaded_document_count > 0:
        near_threshold = max(1, int(math.floor(loaded_document_count * 0.90)))
        if docs_scored >= near_threshold:
            warnings.append(
                "docs_scored_near_table_size:"
                f"observed={docs_scored},table={loaded_document_count}"
            )
        if doc_graph_docs_scored >= near_threshold:
            warnings.append(
                "doc_graph_docs_scored_near_table_size:"
                f"observed={doc_graph_docs_scored},table={loaded_document_count}"
            )
        if expected_source == "proxy_vector":
            candidate_k = max(
                scan_stat_int(stats, "multivector_proxy_candidate_target"),
                scan_stat_int(stats, "multivector_doc_graph_candidates"),
                scan_stat_int(stats, "proxy_candidates"),
                int(getattr(args, "serving_candidate_k", 0) or 0),
                int(getattr(args, "multivector_doc_candidate_k", 0) or 0),
            )
            sidecar_vectors_loaded = scan_stat_int(
                stats, "multivector_doc_sidecar_vectors_loaded"
            )
            resident_vectors_loaded = scan_stat_int(
                stats, "multivector_doc_sidecar_resident_vectors_loaded"
            )
            sidecar_bytes_touched = scan_stat_int(
                stats, "multivector_doc_sidecar_bytes_touched"
            )
            proxy_full_sidecar_bytes = scan_stat_int(
                stats, "proxy_full_sidecar_bytes_touched"
            )
            proxy_near_exhaustive_flag = scan_stat_bool(
                stats, "proxy_vector_near_exhaustive_sidecar_touch"
            )
            sidecar_docmap_bytes = scan_stat_int(stats, "multivector_docmap_bytes")
            docmap_bytes_touched = scan_stat_int(
                stats, "multivector_doc_sidecar_docmap_bytes_touched"
            )
            bounded_proxy_candidate_band = candidate_k > 0 and candidate_k < near_threshold
            if bounded_proxy_candidate_band and (
                sidecar_vectors_loaded >= near_threshold
                or resident_vectors_loaded >= near_threshold
                or doc_graph_docs_scored >= near_threshold
            ):
                warnings.append(
                    "proxy_vector_near_exhaustive_sidecar_touch:"
                    f"candidate_k={candidate_k},table={loaded_document_count},"
                    f"sidecar_vectors_loaded={sidecar_vectors_loaded},"
                    f"resident_vectors_loaded={resident_vectors_loaded},"
                    f"docs_scored={doc_graph_docs_scored}"
                )
            if (
                bounded_proxy_candidate_band
                and proxy_near_exhaustive_flag
                and sidecar_docmap_bytes > 0
                and max(proxy_full_sidecar_bytes, sidecar_bytes_touched - docmap_bytes_touched)
                >= int(math.floor(sidecar_docmap_bytes * 0.90))
            ):
                warnings.append(
                    "proxy_vector_near_exhaustive_sidecar_touch:"
                    f"candidate_k={candidate_k},table={loaded_document_count},"
                    f"sidecar_bytes_touched={sidecar_bytes_touched},"
                    f"docmap_bytes_touched={docmap_bytes_touched},"
                    f"proxy_full_sidecar_bytes_touched={proxy_full_sidecar_bytes},"
                    f"docmap_bytes={sidecar_docmap_bytes}"
                )

    observed_cache_mode = scan_stat_str(stats, "multivector_doc_sidecar_cache_mode")
    pages_read = scan_stat_int(stats, "multivector_doc_sidecar_pages_read")
    if (
        profile.cache_mode in {"auto", "resident"}
        and observed_cache_mode == "paged"
        and pages_read > max(128, int(max(loaded_document_count, 0) * 0.01))
    ):
        warnings.append(
            "paged_sidecar_high_pages_read:"
            f"expected={profile.cache_mode},observed=paged,pages_read={pages_read}"
        )

    exact_kernel = scan_stat_str(stats, "multivector_exact_kernel")
    if exact_kernel in {"scalar", "blocked_scalar"} and serving_simd_expected():
        warnings.append(f"exact_kernel_scalar:{exact_kernel}")

    if scan_stat_bool(stats, "native_cache_built_this_scan"):
        warnings.append("native_cache_built_this_scan")
    return warnings


def unique_preserve_order(values: Iterable[str]) -> list[str]:
    seen: set[str] = set()
    result: list[str] = []
    for value in values:
        if value in seen:
            continue
        seen.add(value)
        result.append(value)
    return result


def fail_on_serving_slow_path_if_requested(
    warnings: list[str],
    args: argparse.Namespace,
) -> None:
    if warnings and bool(getattr(args, "serving_fail_on_slow_path", False)):
        raise RuntimeError("serving slow path detected: " + "; ".join(warnings))


