def serving_row_candidate_budget(row: dict[str, Any]) -> int | None:
    for key in ("candidate_budget", "largest_budget"):
        value = row.get(key)
        if value is None:
            continue
        try:
            budget = int(value)
        except (TypeError, ValueError):
            continue
        if budget > 0:
            return budget
    return None


def serving_row_is_pure_proxy(row: dict[str, Any]) -> bool:
    sample = row.get("last_scan_stats_sample", row.get("serving_stats_sample", {}))
    if not isinstance(sample, dict):
        sample = {}
    candidate_source = str(
        row.get("candidate_source") or sample.get("multivector_candidate_source") or ""
    )
    sparse_source = str(row.get("sparse_candidate_source") or "off")
    bm25_source = str(row.get("bm25_candidate_injection") or "off")
    reservoirs = str(row.get("candidate_reservoirs") or "off")
    return (
        candidate_source == "proxy_vector"
        and sparse_source == "off"
        and bm25_source == "off"
        and reservoirs == "off"
    )


def serving_row_proxy_high_budget_low_admission(row: dict[str, Any]) -> bool:
    admission = serving_row_metric(row, "exact_top10_admission_recall")
    if admission is None or admission >= 0.25:
        return False
    budget = serving_row_candidate_budget(row) or 0
    ef = int_from_mapping(row, "ef", "multivector_doc_graph_search_ef")
    return serving_row_is_pure_proxy(row) and ef >= 400 and budget >= 400


def serving_proxy_report_classification(
    row: dict[str, Any],
    *,
    min_top10_admission: float,
) -> list[str]:
    if not serving_row_is_pure_proxy(row):
        return []
    classifications: list[str] = []
    admission = serving_row_metric(row, "exact_top10_admission_recall")
    if admission is not None and admission < min_top10_admission:
        classifications.append("proxy_admission_failure")
    if serving_row_proxy_high_budget_low_admission(row):
        classifications.append("proxy_quality_not_threshold_limited")
        p95 = serving_row_p95(row)
        proxy_encoder = str(row.get("proxy_encoder") or "")
        if proxy_encoder == "normalized_mean" and p95 is not None and p95 <= 25.0:
            classifications.insert(0, "fast_unsafe_proxy_baseline")
    return sorted(dict.fromkeys(classifications))


def int_from_mapping(mapping: dict[str, Any], *keys: str) -> int:
    for key in keys:
        value = mapping.get(key)
        if value is None or isinstance(value, bool):
            continue
        try:
            parsed = int(value)
        except (TypeError, ValueError):
            continue
        return parsed
    return 0


def summary_p95_int(value: Any) -> int:
    if isinstance(value, dict):
        return int_from_mapping(value, "p95", "max", "mean")
    if value is None or isinstance(value, bool):
        return 0
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0


def serving_candidate_effective_count(row: dict[str, Any], sample: dict[str, Any]) -> int:
    direct = int_from_mapping(
        row,
        "effective_candidate_k",
        "proxy_candidates_returned",
        "multivector_proxy_candidates_returned",
        "proxy_candidates",
        "multivector_doc_graph_candidates",
        "centroid_candidates",
        "quantized_inverted_candidates",
    )
    if direct > 0:
        return direct
    for key in (
        "proxy_candidates",
        "multivector_proxy_candidates_returned",
        "proxy_candidates_returned",
        "multivector_doc_graph_candidates",
        "centroid_candidates",
        "quantized_inverted_candidates",
    ):
        summarized = summary_p95_int(row.get(key))
        if summarized > 0:
            return summarized
    return int_from_mapping(
        sample,
        "proxy_candidates_returned",
        "multivector_proxy_candidates_returned",
        "proxy_candidates",
        "multivector_doc_graph_candidates",
        "centroid_candidates",
        "quantized_inverted_candidates",
    )


def serving_candidate_underfill_reason(
    row: dict[str, Any],
    *,
    requested_candidate_k: int,
    effective_candidate_k: int,
    sample: dict[str, Any],
) -> str:
    if requested_candidate_k <= 0 or effective_candidate_k <= 0:
        return "unknown"
    if effective_candidate_k >= requested_candidate_k:
        exact_k = int_from_mapping(row, "effective_exact_rerank_k")
        if exact_k > 0 and exact_k < effective_candidate_k:
            return "exact_rerank_k_limits_rescue"
        return "none"

    limit_source = str(
        row.get("proxy_candidate_limit_source")
        or sample.get("proxy_candidate_limit_source")
        or ""
    )
    if limit_source == "search_ef":
        return "capped_by_search_ef"
    if limit_source == "doc_candidate_k":
        return "capped_by_doc_candidate_k"

    search_ef = int_from_mapping(
        row,
        "multivector_doc_graph_search_ef",
        "doc_graph_search_ef",
        "ef",
    ) or int_from_mapping(sample, "multivector_doc_graph_search_ef")
    if search_ef > 0 and search_ef <= effective_candidate_k:
        return "capped_by_search_ef"

    target = int_from_mapping(row, "multivector_proxy_candidate_target") or int_from_mapping(
        sample,
        "multivector_proxy_candidate_target",
    )
    final_k = int_from_mapping(row, "final_k", "final_k_effective") or int_from_mapping(
        sample,
        "final_k_effective",
        "effective_result_target",
        "graph_effective_result_target",
    )
    oversampling = int_from_mapping(
        row,
        "multivector_doc_graph_oversampling",
        "doc_graph_oversampling",
        "oversampling",
    ) or int_from_mapping(sample, "multivector_doc_graph_oversampling")
    if (
        target > 0
        and final_k > 0
        and oversampling > 0
        and target <= max(final_k * oversampling, final_k)
        and target <= effective_candidate_k
    ):
        return "capped_by_final_k_oversampling"

    doc_candidate_k = int_from_mapping(row, "multivector_doc_candidate_k") or int_from_mapping(
        sample,
        "multivector_doc_candidate_k",
    )
    if doc_candidate_k > 0 and doc_candidate_k <= effective_candidate_k:
        return "capped_by_doc_candidate_k"

    return "candidate_source_underfilled"


def next_admission_hint_for_underfill_reason(reason: str) -> str:
    return {
        "capped_by_search_ef": "try_higher_ef_or_entry_sample",
        "capped_by_final_k_oversampling": "increase_oversampling",
        "capped_by_doc_candidate_k": "increase_multivector_doc_candidate_k",
        "candidate_source_underfilled": "try_entry_sidecar_or_stronger_proxy",
        "exact_rerank_k_limits_rescue": "increase_serving_exact_rerank_k_or_candidate_reservoir",
        "unknown": "inspect_candidate_limit_stats",
        "none": "",
    }.get(reason, "inspect_candidate_limit_stats")


def derive_candidate_underfill_diagnostics(row: dict[str, Any]) -> dict[str, Any]:
    sample = row.get("last_scan_stats_sample", row.get("serving_stats_sample", {}))
    if not isinstance(sample, dict):
        sample = {}
    requested = serving_row_candidate_budget(row) or int_from_mapping(
        sample,
        "multivector_proxy_candidate_target",
    )
    effective = serving_candidate_effective_count(row, sample)
    reason = serving_candidate_underfill_reason(
        row,
        requested_candidate_k=requested or 0,
        effective_candidate_k=effective,
        sample=sample,
    )
    ratio = (
        round(min(max(effective / requested, 0.0), 1.0), 6)
        if requested and effective >= 0
        else None
    )
    underfill = bool(requested and effective > 0 and effective < requested)
    hint = next_admission_hint_for_underfill_reason(reason)
    return {
        "requested_candidate_k": requested,
        "effective_candidate_k": effective,
        "candidate_underfill": underfill,
        "candidate_underfill_ratio": ratio,
        "candidate_underfill_reason": reason,
        "next_admission_hint": hint,
    }


def serving_row_exhausted_admitted_band(row: dict[str, Any]) -> bool:
    budget = serving_row_candidate_budget(row)
    if budget is None:
        return False
    mode = str(row.get("serving_exact_rerank_mode") or "")
    effective_rerank = row.get("effective_exact_rerank_k")
    try:
        effective_rerank_int = int(effective_rerank)
    except (TypeError, ValueError):
        effective_rerank_int = 0
    rerank_docs_p95 = row.get("exact_rerank_docs_p95")
    try:
        rerank_docs_p95_float = float(rerank_docs_p95)
    except (TypeError, ValueError):
        rerank_docs_p95_float = 0.0
    if mode == "admission_exhaustive":
        return True
    return effective_rerank_int >= budget and rerank_docs_p95_float >= budget * 0.95


def serving_row_candidate_admission_bottleneck(
    row: dict[str, Any],
    *,
    min_top10_admission: float,
) -> bool:
    admission = serving_row_metric(row, "exact_top10_admission_recall")
    if admission is None or admission >= min_top10_admission:
        return False
    return serving_row_exhausted_admitted_band(row)


def summary_stat_float(value: Any, key: str, default: float = 0.0) -> float:
    if isinstance(value, dict):
        value = value.get(key, default)
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def summary_reason_present(value: Any, reason: str) -> bool:
    if isinstance(value, dict):
        return summary_stat_float(value.get(reason), "count", 0.0) > 0.0
    return str(value or "") == reason


def summary_stat_float_any(
    row: dict[str, Any],
    keys: tuple[str, ...],
    stat: str,
    default: float = 0.0,
) -> float:
    for key in keys:
        value = row.get(key)
        if value is None:
            continue
        result = summary_stat_float(value, stat, default)
        if result != default:
            return result
    return default


def serving_admission_improvement_hints(
    row: dict[str, Any],
    *,
    min_top10_admission: float,
) -> list[str]:
    if serving_row_unsupported_reservoir_evidence(row):
        return ["candidate_reservoirs_not_executed"]

    admission = serving_row_metric(row, "exact_top10_admission_recall")
    if admission is not None and admission >= min_top10_admission:
        return []
    if serving_row_proxy_high_budget_low_admission(row):
        proxy_encoder = str(row.get("proxy_encoder") or "")
        hints = [
            "try_learned_sparse_rescue",
            "try_bm25_rescue",
            "try_centroid_lite_focus",
            "try_quantized_inverted_experimental",
            "try_learned_projection_or_fde",
        ]
        if proxy_encoder not in {"max_pool", "centroid_mean"}:
            hints.append("try_max_pool_or_centroid_mean_proxy_secondary")
        return sorted(dict.fromkeys(hints))

    hints: list[str] = []
    sample = row.get("last_scan_stats_sample", {})
    if not isinstance(sample, dict):
        sample = {}

    candidate_hint = str(row.get("next_admission_hint") or "")
    if candidate_hint:
        hints.append(candidate_hint)
    candidate_underfill_reason = str(row.get("candidate_underfill_reason") or "")
    if candidate_underfill_reason and candidate_underfill_reason not in {"none", "unknown"}:
        hints.append(candidate_underfill_reason)

    if serving_row_candidate_admission_bottleneck(
        row,
        min_top10_admission=min_top10_admission,
    ):
        hints.append("candidate_source_quality_bottleneck")
        hints.append("admitted_band_exhausted")
        proxy_encoder = str(row.get("proxy_encoder") or sample.get("proxy_encoder_kind") or "")
        candidate_source = str(row.get("candidate_source") or sample.get("multivector_candidate_source") or "")
        sparse_source_for_bottleneck = str(row.get("sparse_candidate_source") or "off")
        bm25_for_bottleneck = str(row.get("bm25_candidate_injection") or "off")
        reservoirs_for_bottleneck = str(row.get("candidate_reservoirs") or "off")
        if candidate_source == "proxy_vector":
            entry_sample_count = int(
                row.get(
                    "effective_entry_sample_count",
                    row.get("entry_sample_count", 0),
                )
                or 0
            )
            if entry_sample_count <= 0:
                hints.append("try_entry_sample_sweep")
            if proxy_encoder == "normalized_mean":
                hints.append("try_max_pool_or_centroid_mean_proxy")
            elif proxy_encoder == "max_pool":
                hints.append("try_centroid_mean_proxy")
            elif proxy_encoder == "centroid_mean":
                hints.append("try_sparse_rescue_or_centroid_lite")
        if reservoirs_for_bottleneck == "off":
            hints.append("try_balanced_candidate_reservoirs")
        if sparse_source_for_bottleneck == "off" and bm25_for_bottleneck == "off":
            hints.append("try_bm25_or_learned_sparse_rescue")

    if row.get("candidate_reservoirs") not in (None, "off"):
        if serving_row_unsupported_reservoir_evidence(row):
            hints.append("candidate_reservoirs_not_executed")
        reservoir_union_p95 = summary_stat_float_any(
            row,
            ("multivector_reservoir_union_docs", "reservoir_union_docs"),
            "p95",
        )
        reservoir_score_p95 = summary_stat_float_any(
            row,
            ("multivector_reservoir_score_docs", "reservoir_score_docs"),
            "p95",
        )
        reservoir_duplicates_p95 = summary_stat_float_any(
            row,
            ("multivector_reservoir_duplicates", "reservoir_duplicates"),
            "p95",
        )
        if reservoir_union_p95 <= 0.0:
            hints.append("candidate_reservoirs_no_union")
        elif reservoir_score_p95 > 0.0 and reservoir_union_p95 <= reservoir_score_p95:
            hints.append("candidate_reservoirs_no_extra_docs")
        if reservoir_duplicates_p95 > reservoir_union_p95 and reservoir_union_p95 > 0.0:
            hints.append("candidate_reservoirs_high_duplicates")

    proxy_limit_source = row.get("proxy_candidate_limit_source")
    if proxy_limit_source is None:
        proxy_limit_source = sample.get("proxy_candidate_limit_source")
    if proxy_limit_source == "search_ef":
        hints.append("proxy_candidates_capped_by_search_ef")
        hints.append("try_higher_ef_or_entry_sample")
    elif proxy_limit_source == "doc_candidate_k":
        hints.append("proxy_candidates_capped_by_doc_candidate_k")

    bm25_injection = row.get("bm25_candidate_injection")
    bm25_enabled_queries = int(row.get("bm25_injection_enabled_queries") or 0)
    if bm25_injection and bm25_injection != "off":
        if row.get("bm25_text_query_available") is False:
            hints.append("bm25_rescue_missing_text_query")
        if bm25_enabled_queries <= 0:
            hints.append("bm25_rescue_not_triggering")
        reason_counts = row.get("bm25_injection_limit_reason")
        if summary_reason_present(reason_counts, "exact_rerank_k"):
            hints.append("bm25_rescue_limited_by_exact_rerank_k")
        if summary_reason_present(reason_counts, "doc_candidate_k"):
            hints.append("bm25_rescue_limited_by_doc_candidate_k")
        if summary_reason_present(reason_counts, "bm25_count"):
            hints.append("bm25_rescue_lexical_underfill")
            hints.append("bm25_rescue_underfilled")
        if summary_stat_float(row.get("bm25_injection_candidates"), "p95") <= 0.0:
            hints.append("bm25_rescue_underfilled")
        if (
            summary_stat_float(row.get("bm25_injection_candidates"), "p95") > 0.0
            and summary_stat_float(row.get("bm25_injection_retained"), "p95") <= 0.0
        ):
            hints.append("bm25_rescue_not_retained")
        for admission_delta_key in (
            "exact_top10_admission_recall_delta",
            "bm25_admission_delta",
        ):
            if admission_delta_key in row:
                try:
                    if float(row.get(admission_delta_key) or 0.0) <= 0.0:
                        hints.append("bm25_rescue_no_admission_gain")
                except (TypeError, ValueError):
                    pass
                break
        for latency_delta_key in ("p95_ms_delta", "bm25_latency_delta_ms"):
            if latency_delta_key in row:
                try:
                    if float(row.get(latency_delta_key) or 0.0) > 0.0:
                        hints.append("bm25_rescue_latency_regression")
                except (TypeError, ValueError):
                    pass
                break

    sparse_source = row.get("sparse_candidate_source")
    if sparse_source == "learned_sparse":
        hints.extend(learned_sparse_coverage_failure_reasons(row))
        if summary_stat_float(row.get("learned_sparse_candidates"), "p95") <= 0.0:
            hints.append("learned_sparse_no_candidates")
        elif summary_stat_float(row.get("learned_sparse_retained_for_maxsim"), "p95") <= 0.0:
            hints.append("learned_sparse_not_retained")

    if row.get("candidate_source") == "centroid_lite":
        for warning_name in row.get("centroid_lite_warnings", []) or []:
            hints.append(str(warning_name))
        if str(row.get("comparison", "")) == "centroid_lite_posting_cap":
            try:
                admission_delta = float(
                    row.get("exact_top10_admission_recall_delta") or 0.0
                )
            except (TypeError, ValueError):
                admission_delta = 0.0
            try:
                latency_delta = float(row.get("p95_ms_delta") or 0.0)
            except (TypeError, ValueError):
                latency_delta = 0.0
            if admission_delta <= 0.0:
                hints.append("centroid_lite_no_admission_gain")
            if admission_delta < -0.02:
                hints.append("centroid_lite_cap_too_aggressive")
            if latency_delta > 0.0:
                hints.append("centroid_lite_latency_regression")

    warning = str(sample.get("multivector_doc_graph_warning", "") or "")
    if "near_exhaustive" in warning:
        hints.append("candidate_source_near_exhaustive_scan")

    if not hints:
        hints.append("try_higher_quality_candidate_source_or_rescue")
    return sorted(dict.fromkeys(hints))


def serving_profile_explanation(row: dict[str, Any]) -> str:
    if not isinstance(row, dict) or not row:
        return "No profile was selected."
    sample = row.get("last_scan_stats_sample", {})
    if not isinstance(sample, dict):
        sample = {}
    parts = [
        f"source={row.get('candidate_source', '')}",
        f"p95={float(serving_row_p95(row) or 0.0):.3f}ms",
        f"top10_admission={float(row.get('exact_top10_admission_recall') or 0.0):.6f}",
    ]
    if row.get("ndcg@10") is not None:
        parts.append(f"ndcg@10={float(row.get('ndcg@10') or 0.0):.6f}")
    classifications = row.get("report_classification")
    if isinstance(classifications, list) and classifications:
        parts.append(
            "classification="
            + ",".join(str(classification) for classification in classifications)
        )
    if row.get("entry_sidecar") is not None:
        parts.append(f"entry_sidecar={bool(row.get('entry_sidecar'))}")
    if row.get("entry_sidecar_representatives") is not None:
        parts.append(f"entry_sidecar_reps={row.get('entry_sidecar_representatives')}")
    if row.get("entry_sidecar_strategy") is not None:
        parts.append(f"entry_sidecar_strategy={row.get('entry_sidecar_strategy')}")
    if row.get("candidate_reservoirs") not in (None, "off"):
        parts.append(f"reservoirs={row.get('candidate_reservoirs')}")
    for key, label in (
        ("bm25_injection_enabled_queries", "bm25_enabled_queries"),
        ("bm25_injection_candidates", "bm25_candidates_summary"),
        ("bm25_injection_candidate_limit", "bm25_candidate_limit_summary"),
        ("bm25_injection_pool_size", "bm25_pool_size_summary"),
        ("bm25_injection_limit_reason", "bm25_limit_reason_summary"),
        ("bm25_injection_retained", "bm25_retained_summary"),
        ("bm25_injection_exact_reranked", "bm25_exact_reranked_summary"),
        ("learned_sparse_candidates", "learned_sparse_candidates_summary"),
        ("learned_sparse_retained_for_maxsim", "learned_sparse_retained_summary"),
        ("learned_sparse_branch_latency_us", "learned_sparse_latency_us_summary"),
        ("multivector_doc_graph_warning", "warning"),
        ("graph_entry_sidecar_count", "entry_sidecar_count"),
        ("graph_entry_sidecar_scored", "entry_sidecar_scored"),
        ("graph_entry_sidecar_selected", "entry_sidecar_selected"),
        ("graph_entry_sidecar_strategy", "entry_sidecar_scan_strategy"),
        ("proxy_encoder_kind", "proxy"),
        ("proxy_candidates", "proxy_candidates"),
        ("centroid_candidates", "centroid_candidates"),
        ("centroid_docs_touched", "centroid_docs_touched"),
        ("multivector_doc_graph_exact_rerank_docs", "doc_graph_rerank_docs"),
        ("multivector_exact_rerank_docs", "exact_rerank_docs"),
        ("multivector_exact_rerank_pairs", "exact_pairs"),
        ("multivector_exact_kernel", "kernel"),
        ("multivector_doc_sidecar_cache_mode", "sidecar_cache"),
        ("multivector_doc_sidecar_bytes_touched", "sidecar_bytes"),
        ("multivector_doc_sidecar_docmap_bytes_touched", "sidecar_docmap_bytes"),
        ("multivector_doc_sidecar_resident_vectors_loaded", "sidecar_resident_vectors"),
        ("multivector_doc_sidecar_resident_bytes_loaded", "sidecar_resident_bytes"),
        ("multivector_doc_sidecar_vector_chunk_ref_bytes_touched", "sidecar_chunk_ref_bytes"),
        ("multivector_doc_sidecar_paged_vector_bytes_touched", "sidecar_paged_vector_bytes"),
        ("multivector_tokens_original", "tokens_original"),
        ("multivector_tokens_pooled", "tokens_pooled"),
        ("multivector_bm25_injection_enabled", "bm25_injection"),
        ("multivector_bm25_injection_candidates", "bm25_candidates"),
        ("multivector_bm25_injection_candidate_limit", "bm25_candidate_limit"),
        ("multivector_bm25_injection_pool_size", "bm25_pool_size"),
        ("multivector_bm25_injection_limit_reason", "bm25_limit_reason"),
        ("multivector_bm25_injection_retained", "bm25_retained"),
        ("multivector_bm25_injection_exact_reranked", "bm25_exact_reranked"),
        ("learned_sparse_candidates", "learned_sparse_candidates"),
        ("learned_sparse_retained_for_maxsim", "learned_sparse_retained"),
        ("reservoirs_enabled_queries", "reservoirs_enabled_queries"),
        ("reservoir_score_docs", "reservoir_score_docs_summary"),
        ("reservoir_coverage_docs", "reservoir_coverage_docs_summary"),
        ("reservoir_mean_docs", "reservoir_mean_docs_summary"),
        ("reservoir_per_token_docs", "reservoir_per_token_docs_summary"),
        ("reservoir_union_docs", "reservoir_union_docs_summary"),
        ("reservoir_duplicates", "reservoir_duplicates_summary"),
        ("multivector_reservoirs_enabled", "reservoirs_enabled"),
        ("multivector_reservoir_score_docs", "reservoir_score_docs"),
        ("multivector_reservoir_coverage_docs", "reservoir_coverage_docs"),
        ("multivector_reservoir_mean_docs", "reservoir_mean_docs"),
        ("multivector_reservoir_per_token_docs", "reservoir_per_token_docs"),
        ("multivector_reservoir_union_docs", "reservoir_union_docs"),
        ("multivector_reservoir_duplicates", "reservoir_duplicates"),
        ("quantized_inverted_postings_touched", "quantized_postings"),
    ):
        if key in row and row.get(key) is not None:
            parts.append(f"{label}={row[key]}")
        elif key in sample:
            parts.append(f"{label}={sample[key]}")
    return "; ".join(parts)


def serving_quality_available(rows: list[dict[str, Any]]) -> bool:
    return any(serving_row_metric(row, "ndcg@10") is not None for row in rows)


def serving_qrels_available(rows: list[dict[str, Any]]) -> bool:
    return any(
        serving_row_metric(row, key) is not None
        for row in rows
        for key in ("recall@10", "ndcg@10", "mrr@10")
    )


def serving_oracle_admission_available(rows: list[dict[str, Any]]) -> bool:
    return any(
        serving_row_metric(row, "exact_top10_admission_recall") is not None
        for row in rows
    )


def serving_row_proxy_encoder(row: dict[str, Any]) -> str:
    sample = row.get("last_scan_stats_sample", row.get("serving_stats_sample", {}))
    if not isinstance(sample, dict):
        sample = {}
    return str(
        row.get("proxy_encoder_kind")
        or row.get("proxy_encoder")
        or sample.get("proxy_encoder_kind")
        or ""
    )


def serving_pure_dense_proxy_stronger_nonzero_available(
    rows: list[dict[str, Any]],
    *,
    max_p95_ms: float,
) -> bool:
    for row in rows:
        if not serving_row_is_pure_proxy(row):
            continue
        if serving_row_proxy_encoder(row) not in DOCUMENT_NODE_SERVING_GRID_PURE_DENSE_PROXY_STRONG_ENCODERS:
            continue
        admission = serving_row_metric(row, "exact_top10_admission_recall")
        if admission is None or admission <= 0.0:
            continue
        p95 = serving_row_p95(row)
        if p95 is None:
            continue
        if max_p95_ms > 0.0 and p95 > max_p95_ms:
            continue
        return True
    return False


def serving_exact_baseline_has_nonzero_quality(exact_baseline: dict[str, Any]) -> bool:
    metrics = exact_baseline.get("metrics", {}) if isinstance(exact_baseline, dict) else {}
    if not isinstance(metrics, dict):
        return False
    return any(
        (
            serving_row_metric({key: metrics.get(key)}, key) or 0.0
        )
        > 0.0
        for key in ("recall@10", "ndcg@10", "mrr@10")
    )


def serving_exact_baseline_from_results(results: list[dict[str, Any]]) -> dict[str, Any]:
    for item in results:
        if not isinstance(item, dict):
            continue
        if item.get("method") == EXACT_SCAN_METHOD or item.get("retrieval_mode") == "multivector_exact_scan":
            metrics = item.get("metrics", {})
            serial_latency = item.get("serial_latency", {})
            return {
                "available": True,
                "method": item.get("method"),
                "metrics": metrics if isinstance(metrics, dict) else {},
                "serial_latency": serial_latency if isinstance(serial_latency, dict) else {},
            }
    return {
        "available": False,
        "reason": "exact scan method was not included in this benchmark run",
    }


def serving_profile_promotion_failures(
    row: dict[str, Any],
    *,
    qrels_available: bool,
    oracle_admission_available: bool,
    exact_oracle_has_nonzero_quality: bool,
) -> list[str]:
    failures: list[str] = []
    recall = serving_row_metric(row, "recall@10")
    ndcg = serving_row_metric(row, "ndcg@10")
    admission = serving_row_metric(row, "exact_top10_admission_recall")
    zero_qrels_quality = False
    if qrels_available:
        zero_qrels_quality = (
            (recall is not None and recall <= 0.0)
            or (ndcg is not None and ndcg <= 0.0)
        )
        if zero_qrels_quality:
            failures.append("rejected_zero_qrels_quality")

    zero_admission = False
    if oracle_admission_available and admission is not None and admission <= 0.0:
        zero_admission = True
        failures.append("rejected_zero_exact_admission")
    if exact_oracle_has_nonzero_quality and admission is not None and admission <= 0.0:
        zero_admission = True
        failures.append("rejected_zero_exact_admission")

    if not qrels_available and not oracle_admission_available:
        failures.append("rejected_oracle_quality_unproven")

    if serving_row_is_pure_proxy(row) and (zero_qrels_quality or zero_admission):
        failures.append("rejected_fast_but_dead_proxy")

    if (
        str(row.get("candidate_source") or "") == "centroid_lite"
        and zero_qrels_quality
    ):
        failures.append("rejected_centroid_lite_slow_and_zero_quality")

    return sorted(dict.fromkeys(failures))


def serving_negative_control_next_action(row: dict[str, Any]) -> str:
    reasons = set(str(reason) for reason in row.get("failure_reasons", []) or [])
    if "rejected_oracle_quality_unproven" in reasons:
        return "run_oracle_quality_check_before_promotion"
    if "rejected_fast_but_dead_proxy" in reasons:
        return "keep_as_latency_baseline; test_native_colbert_candidate_generation"
    if "rejected_centroid_lite_slow_and_zero_quality" in reasons:
        return "keep_as_negative_control; inspect_centroid_candidate_generation"
    if "rejected_zero_exact_admission" in reasons:
        return "do_not_promote; improve_candidate_admission"
    if "rejected_zero_qrels_quality" in reasons:
        return "do_not_promote; verify_oracle_quality_and_docid_alignment"
    return "inspect_rejection_reasons"


def serving_threshold_failures(
    row: dict[str, Any],
    *,
    min_top10_admission: float,
    min_ndcg_ratio_vs_exact: float,
    max_p95_ms: float,
    exact_baseline_ndcg: float | None,
    accept_partial_learned_sparse_coverage: bool = False,
) -> tuple[list[str], list[str]]:
    failures: list[str] = []
    unavailable: list[str] = []
    p95 = serving_row_p95(row)
    if p95 is None:
        failures.append("missing_p95_latency")
    elif max_p95_ms > 0.0 and p95 > max_p95_ms:
        failures.append("p95_latency_above_cap")

    admission = serving_row_metric(row, "exact_top10_admission_recall")
    if admission is None:
        failures.append("missing_exact_top10_admission_recall")
    elif admission < min_top10_admission:
        failures.append("top10_admission_below_threshold")

    ndcg = serving_row_metric(row, "ndcg@10")
    if exact_baseline_ndcg is None:
        unavailable.append("ndcg_ratio_vs_exact")
    elif ndcg is None:
        failures.append("missing_ndcg@10")
    elif ndcg < exact_baseline_ndcg * min_ndcg_ratio_vs_exact:
        failures.append("ndcg_ratio_below_threshold")

    if not accept_partial_learned_sparse_coverage:
        failures.extend(learned_sparse_coverage_failure_reasons(row))
    if serving_row_unsupported_reservoir_evidence(row):
        failures.append("candidate_reservoirs_not_executed")

    return sorted(dict.fromkeys(failures)), unavailable


def pareto_frontier_latency_quality(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    use_ndcg = serving_quality_available(rows)
    frontier: list[dict[str, Any]] = []
    for row in rows:
        p95 = serving_row_p95(row)
        if p95 is None:
            continue
        admission = serving_row_metric(row, "exact_top10_admission_recall") or 0.0
        ndcg = serving_row_metric(row, "ndcg@10") or 0.0
        dominated = False
        for other in rows:
            if other is row:
                continue
            other_p95 = serving_row_p95(other)
            other_comparable_p95 = other_p95 if other_p95 is not None else float("inf")
            other_admission = serving_row_metric(other, "exact_top10_admission_recall") or 0.0
            other_ndcg = serving_row_metric(other, "ndcg@10") or 0.0
            better_or_equal = (
                other_comparable_p95 <= p95
                and other_admission >= admission
                and (not use_ndcg or other_ndcg >= ndcg)
            )
            strictly_better = (
                other_comparable_p95 < p95
                or other_admission > admission
                or (use_ndcg and other_ndcg > ndcg)
            )
            if better_or_equal and strictly_better:
                dominated = True
                break
        if not dominated:
            frontier.append(serving_recommendation_row(row))
    return sorted(
        frontier,
        key=lambda item: (
            serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
            str(item.get("id", "")),
        ),
    )


def compute_document_node_serving_recommendation(
    serving_grid: dict[str, Any],
    *,
    exact_baseline: dict[str, Any],
    min_top10_admission: float,
    min_ndcg_ratio_vs_exact: float,
    max_p95_ms: float,
    accept_partial_learned_sparse_coverage: bool = False,
) -> dict[str, Any]:
    raw_rows = serving_grid.get("results", serving_grid.get("summary_rows", []))
    rows = [
        item
        for item in raw_rows
        if isinstance(item, dict)
    ]
    pure_colbert_only = bool(serving_grid.get("pure_colbert_only", False))
    pure_dense_proxy_focus = bool(serving_grid.get("pure_dense_proxy_focus", False))
    stronger_proxy_nonzero_available = (
        serving_pure_dense_proxy_stronger_nonzero_available(
            rows,
            max_p95_ms=max_p95_ms,
        )
        if pure_dense_proxy_focus
        else False
    )

    def pure_colbert_hints(hints: Sequence[Any]) -> list[str]:
        if not pure_colbert_only:
            return [str(item) for item in hints if item]
        blocked = ("bm25", "learned_sparse", "sparse_rescue", "sparse")
        return [
            str(item)
            for item in hints
            if item and not any(token in str(item).lower() for token in blocked)
        ]

    def row_allowed_for_named_selection(row: dict[str, Any]) -> bool:
        if accept_partial_learned_sparse_coverage:
            return True
        return not bool(learned_sparse_coverage_failure_reasons(row))

    exact_metrics = exact_baseline.get("metrics", {}) if isinstance(exact_baseline, dict) else {}
    exact_baseline_ndcg = (
        serving_row_metric({"ndcg@10": exact_metrics.get("ndcg@10")}, "ndcg@10")
        if isinstance(exact_metrics, dict)
        else None
    )
    qrels_available = serving_qrels_available(rows)
    oracle_admission_available = serving_oracle_admission_available(rows)
    exact_oracle_has_nonzero_quality = serving_exact_baseline_has_nonzero_quality(
        exact_baseline if isinstance(exact_baseline, dict) else {}
    )
    threshold_rows: list[dict[str, Any]] = []
    rejected_profiles: list[dict[str, Any]] = []
    for row in rows:
        failures, unavailable = serving_threshold_failures(
            row,
            min_top10_admission=min_top10_admission,
            min_ndcg_ratio_vs_exact=min_ndcg_ratio_vs_exact,
            max_p95_ms=max_p95_ms,
            exact_baseline_ndcg=exact_baseline_ndcg,
            accept_partial_learned_sparse_coverage=accept_partial_learned_sparse_coverage,
        )
        failures.extend(
            serving_profile_promotion_failures(
                row,
                qrels_available=qrels_available,
                oracle_admission_available=oracle_admission_available,
                exact_oracle_has_nonzero_quality=exact_oracle_has_nonzero_quality,
            )
        )
        if (
            pure_dense_proxy_focus
            and serving_row_is_pure_proxy(row)
            and serving_row_proxy_encoder(row) == "normalized_mean"
            and stronger_proxy_nonzero_available
        ):
            failures.append("rejected_normalized_mean_superseded_by_stronger_proxy")
        failures = sorted(dict.fromkeys(failures))
        summary = serving_recommendation_row(row)
        summary["report_classification"] = serving_proxy_report_classification(
            summary,
            min_top10_admission=min_top10_admission,
        )
        candidate_bottleneck = serving_row_candidate_admission_bottleneck(
            summary,
            min_top10_admission=min_top10_admission,
        )
        summary["threshold_pass"] = not failures
        summary["failure_reasons"] = failures
        if (
            summary["failure_reasons"]
            and bool(summary.get("candidate_underfill"))
            and "candidate_underfill" not in summary["failure_reasons"]
        ):
            summary["failure_reasons"] = [
                *summary["failure_reasons"],
                "candidate_underfill",
            ]
        if candidate_bottleneck and "candidate_admission_bottleneck" not in summary["failure_reasons"]:
            summary["failure_reasons"] = [
                *summary["failure_reasons"],
                "candidate_admission_bottleneck",
            ]
        summary["unavailable_criteria"] = unavailable
        summary["candidate_admission_bottleneck"] = candidate_bottleneck
        summary["next_action"] = (
            serving_negative_control_next_action(summary)
            if any(
                str(reason).startswith("rejected_")
                for reason in summary["failure_reasons"]
            )
            else ""
        )
        if candidate_bottleneck:
            summary["candidate_admission_bottleneck_reason"] = (
                "exact rerank exhausted the admitted candidate band, but "
                "exact_top10_admission_recall remained below threshold"
            )
        summary["admission_improvement_hints"] = pure_colbert_hints(
            serving_admission_improvement_hints(
                summary,
                min_top10_admission=min_top10_admission,
            )
        )
        threshold_rows.append(summary)
        if summary["failure_reasons"]:
            rejected_profiles.append(summary)

    eligible = [
        item for item in threshold_rows
        if (
            item["threshold_pass"]
            and not serving_row_experimental(item)
            and serving_row_p95(item) is not None
        )
    ]
    hard_rejected_ids = {
        serving_row_id(item)
        for item in threshold_rows
        if any(
            str(reason).startswith("rejected_")
            for reason in item.get("failure_reasons", []) or []
        )
    }
    best_latency_safe = min(
        eligible,
        key=lambda item: (
            serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
            str(item.get("id", "")),
        ),
        default=None,
    )
    if best_latency_safe is not None:
        best_latency_safe = {
            **best_latency_safe,
            "criteria_unavailable": sorted({
                criterion
                for item in threshold_rows
                for criterion in item.get("unavailable_criteria", [])
            }),
        }

    use_ndcg = serving_quality_available(rows)
    quality_rows = [
        row for row in rows
        if (
            not serving_row_unsupported_reservoir_evidence(row)
            and row_allowed_for_named_selection(row)
            and serving_row_id(row) not in hard_rejected_ids
        )
    ]
    quality_rows = [
        row for row in quality_rows
        if row_allowed_for_named_selection(row)
    ]
    best_quality_row = max(
        quality_rows,
        key=lambda item: (
            (serving_row_metric(item, "ndcg@10") or 0.0)
            if use_ndcg
            else (serving_row_metric(item, "exact_top10_admission_recall") or 0.0),
            serving_row_metric(item, "exact_top10_admission_recall") or 0.0,
            0 if not serving_row_unsupported_reservoir_evidence(item) else -1,
            0 if not serving_row_experimental(item) else -1,
            -(serving_row_p95(item) if serving_row_p95(item) is not None else float("inf")),
            str(item.get("profile", "")),
        ),
        default=None,
    )
    best_quality = serving_recommendation_row(best_quality_row) if best_quality_row else None
    if best_quality is not None:
        best_quality["selection_basis"] = "ndcg@10" if use_ndcg else "exact_top10_admission_recall"

    ordered_by_latency = sorted(
        rows,
        key=lambda item: (
            serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
            str(item.get("profile", "")),
            int(item.get("ef", 0) or 0),
            int(item.get("oversampling", 0) or 0),
        ),
    )
    latency_rank = {
        serving_row_id(item): rank
        for rank, item in enumerate(ordered_by_latency, start=1)
    }
    best_admission = max(
        (serving_row_metric(item, "exact_top10_admission_recall") or 0.0 for item in rows),
        default=0.0,
    )
    best_ndcg = max(
        (serving_row_metric(item, "ndcg@10") or 0.0 for item in rows),
        default=0.0,
    )
    non_experimental_has_usable_metrics = any(
        not serving_row_experimental(item) and serving_row_has_usable_metrics(item)
        for item in rows
    )
    balanced_candidates: list[dict[str, Any]] = []
    for row in rows:
        if not row_allowed_for_named_selection(row):
            continue
        if serving_row_id(row) in hard_rejected_ids:
            continue
        admission = serving_row_metric(row, "exact_top10_admission_recall") or 0.0
        ndcg = serving_row_metric(row, "ndcg@10") or 0.0
        admission_loss_penalty = round(max(0.0, best_admission - admission) * 100.0, 3)
        quality_loss_penalty = round(max(0.0, best_ndcg - ndcg) * 100.0, 3) if use_ndcg else 0.0
        storage_penalty = serving_storage_penalty(row)
        experimental_penalty = (
            1_000_000
            if serving_row_experimental(row) and non_experimental_has_usable_metrics
            else 0
        )
        partial_evidence_penalty = (
            500_000
            if not accept_partial_learned_sparse_coverage
            and bool(learned_sparse_coverage_failure_reasons(row))
            and non_experimental_has_usable_metrics
            else 0
        )
        unsupported_reservoir_penalty = (
            500_000
            if serving_row_unsupported_reservoir_evidence(row)
            and non_experimental_has_usable_metrics
            else 0
        )
        score = (
            latency_rank.get(serving_row_id(row), len(rows) + 1)
            + admission_loss_penalty
            + quality_loss_penalty
            + storage_penalty
            + experimental_penalty
            + partial_evidence_penalty
            + unsupported_reservoir_penalty
        )
        balanced_candidates.append({
            **serving_recommendation_row(row),
            "score": round(score, 3),
            "score_components": {
                "latency_rank": latency_rank.get(serving_row_id(row), len(rows) + 1),
                "admission_loss_penalty": admission_loss_penalty,
                "quality_loss_penalty": quality_loss_penalty,
                "storage_penalty": storage_penalty,
                "experimental_penalty": experimental_penalty,
                "partial_evidence_penalty": partial_evidence_penalty,
                "unsupported_reservoir_penalty": unsupported_reservoir_penalty,
            },
        })
    best_balanced = min(
        balanced_candidates,
        key=lambda item: (
            float(item["score"]),
            serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
            str(item.get("id", "")),
        ),
        default=None,
    )

    balanced_formula = (
        "score = latency_rank + max(0,best_admission-admission)*100 "
        "+ max(0,best_ndcg-ndcg)*100 when qrels exist + storage_penalty; "
        "storage_penalty is sq8=0, f16=1, f32=2, other=3; "
        "experimental_penalty is 1000000 when any non-experimental profile has usable metrics"
    )
    if not pure_colbert_only:
        balanced_formula += (
            "; learned-sparse incomplete feature coverage and unsupported-reservoir "
            "penalties are 500000 under the same condition"
        )

    def strip_non_colbert_recommendation_fields(value: Any) -> Any:
        if not pure_colbert_only:
            return value
        blocked = ("bm25", "learned_sparse", "sparse")
        if isinstance(value, dict):
            return {
                key: strip_non_colbert_recommendation_fields(item)
                for key, item in value.items()
                if not any(token in str(key).lower() for token in blocked)
            }
        if isinstance(value, list):
            return [
                strip_non_colbert_recommendation_fields(item)
                for item in value
            ]
        return value

    recommendation_notes = (
        [
            (
                "Pure proxy ANN is not a safe ColBERT retrieval path for "
                "this artifact; use it only as a latency baseline."
            )
        ]
        if any(
            "fast_unsafe_proxy_baseline" in item.get("report_classification", [])
            or "proxy_quality_not_threshold_limited" in item.get("report_classification", [])
            for item in threshold_rows
        )
        else []
    )
    if pure_dense_proxy_focus:
        pure_proxy_rows = [row for row in rows if serving_row_is_pure_proxy(row)]
        known_admissions = [
            serving_row_metric(row, "exact_top10_admission_recall")
            for row in pure_proxy_rows
        ]
        if known_admissions and all(
            admission is not None and admission <= 0.0
            for admission in known_admissions
        ):
            recommendation_notes.append(
                "All pure dense proxy profiles had zero exact top10 admission; "
                "next pure-ColBERT targets are document-node MaxSim graph or "
                "quantized_inverted_experimental, not BM25 or learned sparse."
            )

    recommendation = {
        "thresholds": {
            "serving_min_top10_admission": min_top10_admission,
            "serving_min_ndcg_ratio_vs_exact": min_ndcg_ratio_vs_exact,
            "serving_max_p95_ms": max_p95_ms,
            "serving_accept_partial_learned_sparse_coverage": (
                accept_partial_learned_sparse_coverage
            ),
        },
        "exact_baseline": exact_baseline,
        "best_latency_safe": best_latency_safe,
        "best_quality": best_quality,
        "best_balanced": best_balanced,
        "balanced_formula": balanced_formula,
        "pareto_frontier_latency_quality": pareto_frontier_latency_quality(rows),
        "pareto_frontier": pareto_frontier_latency_quality(rows),
        "profile_thresholds": sorted(
            threshold_rows,
            key=lambda item: (
                serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
                str(item.get("id", "")),
            ),
        ),
        "candidate_admission_bottlenecks": sorted(
            [
                item for item in threshold_rows
                if item.get("candidate_admission_bottleneck")
            ],
            key=lambda item: (
                float(item.get("exact_top10_admission_recall") or 0.0),
                serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
                str(item.get("id", "")),
            ),
        ),
        "rejected_fast_profiles": sorted(
            [
                item for item in threshold_rows
                if any(
                    str(reason).startswith("rejected_")
                    for reason in item.get("failure_reasons", []) or []
                )
            ],
            key=lambda item: (
                serving_row_p95(item)
                if serving_row_p95(item) is not None
                else float("inf"),
                str(item.get("id", "")),
            ),
        ),
        "recommendation_notes": recommendation_notes,
        "candidate_source_delta_summary": document_node_candidate_source_delta_summary(
            serving_grid.get("candidate_source_deltas")
        ),
        "rejected_profiles": sorted(
            rejected_profiles,
            key=lambda item: (
                serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
                str(item.get("id", "")),
            ),
        ),
    }
    return strip_non_colbert_recommendation_fields(recommendation)


def serving_profile_gate_effective_count(
    dataset: dict[str, Any],
    max_key: str,
    loaded_key: str,
) -> int | None:
    for key in (max_key, loaded_key):
        value = dataset.get(key)
        try:
            parsed = int(value)
        except (TypeError, ValueError):
            continue
        if parsed > 0:
            return parsed
    return None


def serving_profile_gate_row(
    selected: dict[str, Any],
    rows_by_id: dict[str, dict[str, Any]],
    rows_by_profile: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    if not isinstance(selected, dict) or not selected:
        return {}
    row_id = str(selected.get("id") or "")
    profile = str(selected.get("profile") or "")
    if row_id and row_id in rows_by_id:
        return {**rows_by_id[row_id], **selected}
    if profile and profile in rows_by_profile:
        return {**rows_by_profile[profile], **selected}
    return selected


def serving_profile_gate_slow_warnings(row: dict[str, Any], grid: dict[str, Any]) -> list[str]:
    warnings: list[str] = []
    for source in (grid.get("serving_slow_path_warnings"), row.get("serving_slow_path_warnings")):
        if isinstance(source, list):
            warnings.extend(str(item) for item in source if item)
        elif source:
            warnings.append(str(source))
    sample = row.get("last_scan_stats_sample", row.get("serving_stats_sample", {}))
    if isinstance(sample, dict):
        sample_warning = sample.get("multivector_doc_graph_warning")
        if sample_warning:
            warnings.append(str(sample_warning))
    return sorted(dict.fromkeys(warnings))


def serving_profile_gate_learned_sparse_coverage_ok(
    row: dict[str, Any],
    grid: dict[str, Any],
) -> tuple[bool, list[str]]:
    if not serving_row_uses_learned_sparse(row):
        return True, []
    coverage = row.get("learned_sparse_coverage")
    if not isinstance(coverage, dict):
        coverage = grid.get("learned_sparse_coverage")
    if not isinstance(coverage, dict):
        return False, [
            "learned_sparse_missing_doc_features",
            "learned_sparse_missing_query_features",
        ]
    reasons = learned_sparse_coverage_failure_reasons({**row, "learned_sparse_coverage": coverage})
    return not reasons, reasons


def serving_profile_guc_validation_command() -> str:
    return (
        "nix develop .#bench\n"
        "python benchmarks/dbpedia_colbert_multivector.py \\\n"
        "  --database pgturbohybrid_dbpedia_colbert_10k_rescue_validation \\\n"
        "  --precomputed-dataset johannhartmann/pgturbohybrid_dbpedia_colbert \\\n"
        "  --max-docs 10000 \\\n"
        "  --max-queries 100 \\\n"
        "  --reuse-data \\\n"
        "  --document-node-serving-grid \\\n"
        "  --serving-min-top10-admission 0.80 \\\n"
        "  --output .nix-dev/tmp/dbpedia-colbert-serving-validation-10k.json"
    )


def validate_serving_profile_guc_evidence(
    report: dict[str, Any],
    *,
    min_docs: int = SERVING_PROFILE_GUC_MIN_DOCS,
    min_queries: int = SERVING_PROFILE_GUC_MIN_QUERIES,
    allow_unsafe: bool = False,
) -> dict[str, Any]:
    reasons: list[str] = []
    warnings: list[str] = []
    selected_profiles: dict[str, dict[str, Any] | None] = {}

    grid = report.get("document_node_serving_grid")
    if not isinstance(grid, dict):
        reasons.append("missing_document_node_serving_grid")
        grid = {}
    rec = report.get("document_node_serving_recommendation")
    if not isinstance(rec, dict):
        reasons.append("missing_document_node_serving_recommendation")
        rec = {}
    dataset = report.get("dataset")
    if not isinstance(dataset, dict):
        reasons.append("missing_dataset_metadata")
        dataset = {}

    settings = report.get("settings")
    if not isinstance(settings, dict):
        settings = {}
    smoke_mode = (
        str(grid.get("mode") or "").lower() == "smoke"
        or bool(grid.get("smoke_only"))
        or bool(settings.get("document_node_serving_grid_smoke"))
    )
    if smoke_mode:
        reasons.append("artifact_is_smoke_only")

    docs = serving_profile_gate_effective_count(dataset, "max_docs", "documents")
    queries = serving_profile_gate_effective_count(dataset, "max_queries", "queries")
    if docs is None:
        reasons.append("missing_max_docs")
    elif docs < min_docs:
        reasons.append(f"max_docs_below_minimum:{docs}<{min_docs}")
    if queries is None:
        reasons.append("missing_max_queries")
    elif queries < min_queries:
        reasons.append(f"max_queries_below_minimum:{queries}<{min_queries}")

    raw_rows = grid.get("results", grid.get("summary_rows", []))
    rows = [row for row in raw_rows if isinstance(row, dict)] if isinstance(raw_rows, list) else []
    rows_by_id = {serving_row_id(row): row for row in rows}
    rows_by_profile = {
        str(row.get("profile")): row
        for row in rows
        if row.get("profile") is not None
    }

    thresholds = rec.get("thresholds", {}) if isinstance(rec, dict) else {}
    if not isinstance(thresholds, dict):
        thresholds = {}
    try:
        min_top10 = float(thresholds.get("serving_min_top10_admission", 0.80))
    except (TypeError, ValueError):
        min_top10 = 0.80
    quality_waived = allow_unsafe or bool(rec.get("quality_metrics_waived"))

    for key in ("best_latency_safe", "best_balanced", "best_quality"):
        selected = rec.get(key) if isinstance(rec, dict) else None
        row = serving_profile_gate_row(
            selected if isinstance(selected, dict) else {},
            rows_by_id,
            rows_by_profile,
        )
        selected_profiles[key] = serving_recommendation_row(row) if row else None
        if not row:
            reasons.append(f"{key}_missing")
            continue
        profile = str(row.get("profile") or key)
        if serving_row_experimental(row):
            reasons.append(f"{profile}:experimental_profile")
        if str(row.get("candidate_source") or "") == "quantized_inverted_experimental":
            reasons.append(f"{profile}:experimental_candidate_source")

        admission = serving_row_metric(row, "exact_top10_admission_recall")
        if admission is None:
            reasons.append(f"{profile}:missing_exact_top10_admission_recall")
        elif admission < min_top10:
            reasons.append(f"{profile}:top10_admission_below_threshold")

        ndcg = serving_row_metric(row, "ndcg@10")
        recall = serving_row_metric(row, "recall@10")
        mrr = serving_row_metric(row, "mrr@10")
        if ndcg is None and recall is None and mrr is None and not quality_waived:
            reasons.append(f"{profile}:missing_qrels_quality_metrics")

        coverage_ok, coverage_reasons = serving_profile_gate_learned_sparse_coverage_ok(row, grid)
        if not coverage_ok:
            reasons.extend(f"{profile}:{reason}" for reason in coverage_reasons)

        slow_warnings = serving_profile_gate_slow_warnings(row, grid)
        if slow_warnings:
            warnings.extend(f"{profile}:{warning}" for warning in slow_warnings)
            reasons.append(f"{profile}:slow_path_warnings_present")

    unsafe_reasons = sorted(dict.fromkeys(reasons))
    accepted = not unsafe_reasons or allow_unsafe
    return {
        "accepted": accepted,
        "unsafe_override": bool(allow_unsafe and unsafe_reasons),
        "reasons": [] if accepted and allow_unsafe else unsafe_reasons,
        "unsafe_reasons": unsafe_reasons,
        "warnings": sorted(dict.fromkeys(warnings)),
        "minimums": {
            "min_docs": min_docs,
            "min_queries": min_queries,
        },
        "observed": {
            "max_docs": docs,
            "max_queries": queries,
            "mode": grid.get("mode"),
            "smoke_only": smoke_mode,
        },
        "selected_profiles": selected_profiles,
        "suggested_validation_command": (
            None if accepted and not unsafe_reasons else serving_profile_guc_validation_command()
        ),
    }


def compare_metric(value: Any) -> float | None:
    if value is None:
        return None
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return None
    return parsed if math.isfinite(parsed) else None


SERVING_EVIDENCE_LEVELS = (
    "smoke",
    "validation",
    "production_candidate",
    "plumbing_only",
)


def serving_report_counts(report: dict[str, Any]) -> tuple[int | None, int | None]:
    dataset = report.get("dataset")
    grid = report.get("document_node_serving_grid")
    if not isinstance(dataset, dict):
        dataset = {}
    if not isinstance(grid, dict):
        grid = {}

    def first_positive_int(*values: Any) -> int | None:
        for value in values:
            try:
                parsed = int(value)
            except (TypeError, ValueError):
                continue
            if parsed > 0:
                return parsed
        return None

    return (
        first_positive_int(
            dataset.get("max_docs"),
            dataset.get("documents"),
            grid.get("max_docs"),
            grid.get("loaded_documents"),
        ),
        first_positive_int(
            dataset.get("max_queries"),
            dataset.get("queries"),
            grid.get("max_queries"),
            grid.get("loaded_queries"),
            grid.get("queries_run"),
        ),
    )


def learned_sparse_plumbing_evidence_from_coverage(coverage: dict[str, Any]) -> bool:
    if bool(coverage.get("partial_coverage", False)):
        return True
    if bool(coverage.get("learned_sparse_plumbing_only", False)):
        return True
    if bool(coverage.get("not_safe_serving_evidence", False)):
        return True
    warnings = coverage.get("warnings", coverage.get("learned_sparse_feature_warnings", []))
    if not isinstance(warnings, list):
        warnings = [warnings] if warnings else []
    warning_text = " ".join(str(item).lower() for item in warnings)
    if "hash" in warning_text or "toy" in warning_text or "plumbing" in warning_text:
        return True
    source = str(
        coverage.get("learned_sparse_feature_source")
        or coverage.get("feature_source")
        or ""
    ).lower()
    return any(token in source for token in ("hash", "toy", "plumbing"))


def serving_report_has_sparse_plumbing_only(report: dict[str, Any]) -> bool:
    grid = report.get("document_node_serving_grid")
    if not isinstance(grid, dict):
        grid = {}
    coverage = grid.get("learned_sparse_coverage")
    grid_coverage_is_complete = False
    if isinstance(coverage, dict) and learned_sparse_plumbing_evidence_from_coverage(coverage):
        return True
    if isinstance(coverage, dict):
        grid_coverage_is_complete = True
    for row in serving_rows_from_artifact(report):
        if not serving_row_uses_learned_sparse(row):
            continue
        row_coverage = row.get("learned_sparse_coverage")
        if isinstance(row_coverage, dict) and learned_sparse_plumbing_evidence_from_coverage(row_coverage):
            return True
        if not isinstance(row_coverage, dict) and grid_coverage_is_complete:
            continue
        row_for_reasons = (
            {**row, "learned_sparse_coverage": coverage}
            if isinstance(coverage, dict)
            else row
        )
        if learned_sparse_coverage_failure_reasons(row_for_reasons):
            return True
    return False


def serving_report_slow_path_warnings(report: dict[str, Any]) -> list[str]:
    grid = report.get("document_node_serving_grid")
    if not isinstance(grid, dict):
        grid = {}
    warnings: list[str] = []
    for item in grid.get("serving_slow_path_warnings", []) or []:
        warnings.append(str(item))
    rec = report.get("document_node_serving_recommendation")
    selected: list[dict[str, Any]] = []
    if isinstance(rec, dict):
        for key in ("best_latency_safe", "best_quality", "best_balanced"):
            value = rec.get(key)
            if isinstance(value, dict):
                selected.append(value)
    for row in selected:
        warnings.extend(serving_profile_gate_slow_warnings(row, grid))
    return sorted(dict.fromkeys(item for item in warnings if item))


def serving_report_evidence_level(report: dict[str, Any]) -> str:
    grid = report.get("document_node_serving_grid")
    if not isinstance(grid, dict):
        grid = {}
    settings = report.get("settings")
    if not isinstance(settings, dict):
        settings = {}

    if serving_report_has_sparse_plumbing_only(report):
        return "plumbing_only"

    docs, queries = serving_report_counts(report)
    smoke = (
        str(grid.get("mode") or "").lower() == "smoke"
        or bool(grid.get("smoke_only", False))
        or bool(settings.get("document_node_serving_grid_smoke", False))
        or docs is None
        or queries is None
        or docs < SERVING_PROFILE_GUC_MIN_DOCS
        or queries < SERVING_PROFILE_GUC_MIN_QUERIES
    )
    if smoke:
        return "smoke"

    rec = report.get("document_node_serving_recommendation")
    best_latency_safe = rec.get("best_latency_safe") if isinstance(rec, dict) else None
    if (
        isinstance(best_latency_safe, dict)
        and best_latency_safe
        and not serving_report_slow_path_warnings(report)
    ):
        return "production_candidate"

    return "validation"


def serving_evidence_safety_label(evidence_level: str) -> str:
    return {
        "smoke": "safe_within_smoke_only",
        "validation": "validation_candidate",
        "production_candidate": "production_candidate",
        "plumbing_only": "plumbing_only_not_safe_serving_evidence",
    }.get(evidence_level, "unknown_evidence_level")


def annotate_serving_recommendation_evidence_level(report: dict[str, Any]) -> None:
    rec = report.get("document_node_serving_recommendation")
    if not isinstance(rec, dict):
        return
    evidence_level = serving_report_evidence_level(report)
    rec["evidence_level"] = evidence_level
    rec["evidence_safety_label"] = serving_evidence_safety_label(evidence_level)
    rec["slow_path_warnings"] = serving_report_slow_path_warnings(report)
    for key in ("best_latency_safe", "best_quality", "best_balanced"):
        selected = rec.get(key)
        if isinstance(selected, dict) and selected:
            selected["evidence_level"] = evidence_level
            selected["safety_label"] = serving_evidence_safety_label(evidence_level)


def compare_artifact_mode(path: Path, report: dict[str, Any]) -> dict[str, Any]:
    grid = report.get("document_node_serving_grid", {})
    if not isinstance(grid, dict):
        grid = {}
    dataset = report.get("dataset", {})
    if not isinstance(dataset, dict):
        dataset = {}
    mode = str(grid.get("mode") or "")
    max_docs = dataset.get("max_docs")
    max_queries = dataset.get("max_queries")
    filename_smoke = "smoke" in path.name.lower()
    explicit_smoke = mode == "smoke" or filename_smoke
    notes: list[str] = []
    if explicit_smoke:
        notes.append("smoke")
    elif mode:
        notes.append(mode)
    else:
        notes.append("unknown_mode")
    for key, label in (("max_docs", "docs"), ("max_queries", "queries")):
        value = dataset.get(key)
        if value is not None:
            notes.append(f"{label}={value}")
    if filename_smoke and mode != "smoke":
        notes.append("filename_smoke")
    evidence_level = serving_report_evidence_level(report)
    notes.append(f"evidence_level={evidence_level}")
    if evidence_level == "smoke" and any(
        serving_row_uses_learned_sparse(row)
        for row in serving_rows_from_artifact(report)
    ):
        notes.append(
            "hypothesis: learned_sparse may beat BM25 quality; needs full coverage validation"
        )
    return {
        "mode": mode or ("smoke" if explicit_smoke else "unknown"),
        "max_docs": max_docs,
        "max_queries": max_queries,
        "evidence_level": evidence_level,
        "notes": notes,
    }


def compare_profile_settings(row: dict[str, Any]) -> dict[str, Any]:
    return {
        "candidate_source": row.get("candidate_source"),
        "proxy_encoder": row.get("proxy_encoder"),
        "centroids": row.get("centroids"),
        "centroid_count": row.get("centroid_count"),
        "storage_kind": row.get("storage_kind"),
        "storage_cache_mode": row.get(
            "storage_cache_mode",
            row.get("cache_mode"),
        ),
        "token_pooling": row.get("token_pooling"),
        "token_pooling_target_ratio": row.get("token_pooling_target_ratio"),
        "candidate_reservoirs": row.get("candidate_reservoirs"),
        "bm25_candidate_injection": row.get("bm25_candidate_injection"),
        "sparse_candidate_source": row.get("sparse_candidate_source"),
        "branch_plan": row.get("branch_plan"),
    }


def compact_compare_profile(row: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(row, dict) or not row:
        return None
    return {
        "id": row.get("id", serving_row_id(row)),
        "profile": row.get("profile"),
        "p50_ms": compare_metric(
            row.get("p50_ms", row.get("p50_latency_ms_at_largest_budget"))
        ),
        "p95_ms": serving_row_p95(row),
        "exact_top1_admission_rate": compare_metric(row.get("exact_top1_admission_rate")),
        "exact_top10_admission_recall": compare_metric(
            row.get("exact_top10_admission_recall")
        ),
        "recall@10": compare_metric(row.get("recall@10")),
        "ndcg@10": compare_metric(row.get("ndcg@10")),
        "mrr@10": compare_metric(row.get("mrr@10")),
        "index_bytes": row.get("index_bytes"),
        "settings": compare_profile_settings(row),
        "evidence_level": row.get("evidence_level"),
        "safety_label": row.get("safety_label"),
        "learned_sparse_coverage": row.get("learned_sparse_coverage"),
        "learned_sparse_doc_coverage": row.get("learned_sparse_doc_coverage"),
        "learned_sparse_query_coverage": row.get("learned_sparse_query_coverage"),
        "learned_sparse_feature_source": row.get("learned_sparse_feature_source"),
        "learned_sparse_feature_version": row.get("learned_sparse_feature_version"),
        "learned_sparse_missing_doc_count": row.get("learned_sparse_missing_doc_count"),
        "learned_sparse_missing_query_count": row.get("learned_sparse_missing_query_count"),
        "learned_sparse_partial_coverage": row.get("learned_sparse_partial_coverage"),
        "failure_reasons": list(row.get("failure_reasons", []) or []),
        "unavailable_criteria": list(row.get("unavailable_criteria", []) or []),
    }


def serving_rows_from_artifact(report: dict[str, Any]) -> list[dict[str, Any]]:
    grid = report.get("document_node_serving_grid", {})
    if not isinstance(grid, dict):
        return []
    raw_rows = grid.get("results", grid.get("summary_rows", []))
    if not isinstance(raw_rows, list):
        return []
    return [row for row in raw_rows if isinstance(row, dict)]


def compare_recommendation_row(
    rec: dict[str, Any],
    key: str,
    rows_by_id: dict[str, dict[str, Any]],
    rows_by_profile: dict[str, dict[str, Any]],
) -> dict[str, Any] | None:
    row = rec.get(key)
    if not isinstance(row, dict) or not row:
        return None
    source = row
    row_id = str(row.get("id") or "")
    profile = str(row.get("profile") or "")
    if row_id and row_id in rows_by_id:
        source = {**rows_by_id[row_id], **row}
    elif profile and profile in rows_by_profile:
        source = {**rows_by_profile[profile], **row}
    return compact_compare_profile(source)


def promising_rejected_profiles(
    rec: dict[str, Any],
    rows: list[dict[str, Any]],
    *,
    limit: int = 5,
) -> list[dict[str, Any]]:
    rejected = rec.get("rejected_profiles", [])
    if not isinstance(rejected, list) or not rejected:
        rejected = [
            row for row in rows
            if serving_row_has_usable_metrics(row)
        ]
    compacted = [
        compact_compare_profile(row)
        for row in rejected
        if isinstance(row, dict)
    ]
    compacted = [row for row in compacted if row is not None]
    return sorted(
        compacted,
        key=lambda row: (
            -(row.get("exact_top10_admission_recall") or 0.0),
            -(row.get("ndcg@10") or 0.0),
            row.get("p95_ms") if row.get("p95_ms") is not None else float("inf"),
            str(row.get("profile") or ""),
        ),
    )[:limit]


def compare_single_serving_artifact(path: Path, report: dict[str, Any]) -> dict[str, Any]:
    rows = serving_rows_from_artifact(report)
    rows_by_id = {
        serving_row_id(row): row for row in rows
    }
    rows_by_profile = {
        str(row.get("profile")): row for row in rows
        if row.get("profile") is not None
    }
    rec = report.get("document_node_serving_recommendation", {})
    if not isinstance(rec, dict):
        rec = {}
    grid = report.get("document_node_serving_grid", {})
    if not isinstance(grid, dict):
        grid = {}
    coverage = grid.get("learned_sparse_coverage")
    if not isinstance(coverage, dict):
        coverage = None
    artifact_report = {
        **report,
        "document_node_serving_recommendation": rec,
        "document_node_serving_grid": grid,
    }
    annotate_serving_recommendation_evidence_level(artifact_report)
    rec = artifact_report.get("document_node_serving_recommendation", rec)
    if not isinstance(rec, dict):
        rec = {}
    evidence_level = serving_report_evidence_level(artifact_report)

    return {
        "artifact": portable_path(path),
        "artifact_name": path.name,
        "mode": compare_artifact_mode(path, report),
        "evidence_level": evidence_level,
        "evidence_safety_label": serving_evidence_safety_label(evidence_level),
        "profile_count": len(rows),
        "best_latency_safe": compare_recommendation_row(
            rec,
            "best_latency_safe",
            rows_by_id,
            rows_by_profile,
        ),
        "best_quality": compare_recommendation_row(
            rec,
            "best_quality",
            rows_by_id,
            rows_by_profile,
        ),
        "best_balanced": compare_recommendation_row(
            rec,
            "best_balanced",
            rows_by_id,
            rows_by_profile,
        ),
        "top_promising_rejected_profiles": promising_rejected_profiles(rec, rows),
        "learned_sparse_coverage": coverage,
        "has_recommendation": bool(rec),
    }


def compare_serving_artifacts(paths: Sequence[Path]) -> dict[str, Any]:
    artifacts: list[dict[str, Any]] = []
    for path in paths:
        report = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(report, dict):
            raise SystemExit(f"artifact is not a JSON object: {path}")
        artifacts.append(compare_single_serving_artifact(path, report))
    return {
        "suite": "dbpedia_colbert_serving_artifact_compare",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "artifacts": artifacts,
        "artifact_count": len(artifacts),
    }


def markdown_compare_serving_artifacts(report: dict[str, Any]) -> str:
    lines = [
        "# DBpedia ColBERT Serving Artifact Comparison",
        "",
        "| artifact | evidence | mode | best_latency_safe | best_quality | best_balanced | p50 ms | p95 ms | top1 | top10 | recall@10 | ndcg@10 | mrr@10 | index bytes | coverage | notes |",
        "|---|---|---|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---|---|",
    ]

    def metric_text(row: dict[str, Any] | None, key: str) -> str:
        if not isinstance(row, dict):
            return ""
        value = row.get(key)
        if value is None:
            return ""
        if isinstance(value, float):
            return f"{value:.6f}" if key.endswith("@10") or "admission" in key else f"{value:.3f}"
        return str(value)

    def profile_text(row: dict[str, Any] | None) -> str:
        if not isinstance(row, dict) or not row:
            return ""
        return str(row.get("profile") or row.get("id") or "")

    for artifact in report.get("artifacts", []):
        if not isinstance(artifact, dict):
            continue
        best = artifact.get("best_latency_safe")
        if not isinstance(best, dict):
            best = artifact.get("best_quality")
        if not isinstance(best, dict):
            best = artifact.get("best_balanced")
        if not isinstance(best, dict):
            best = {}
        mode = artifact.get("mode", {})
        if not isinstance(mode, dict):
            mode = {}
        coverage = artifact.get("learned_sparse_coverage")
        coverage_text = ""
        if isinstance(coverage, dict):
            coverage_text = "docs={doc} queries={query} partial={partial}".format(
                doc=coverage.get("doc_coverage_ratio", ""),
                query=coverage.get("query_coverage_ratio", ""),
                partial=bool(coverage.get("partial_coverage", False)),
            )
        notes = list(mode.get("notes", []) or [])
        if artifact.get("evidence_level") == "smoke" and any(
            serving_row_uses_learned_sparse(item)
            for item in [
                artifact.get("best_latency_safe") or {},
                artifact.get("best_quality") or {},
                artifact.get("best_balanced") or {},
                *(artifact.get("top_promising_rejected_profiles", []) or []),
            ]
            if isinstance(item, dict)
        ):
            notes.append(
                "hypothesis: learned_sparse may beat BM25 quality; needs full coverage validation"
            )
        lines.append(
            "| {artifact} | {evidence} | {mode} | {latency} | {quality} | {balanced} | {p50} | {p95} | {top1} | {top10} | {recall} | {ndcg} | {mrr} | {index_bytes} | {coverage} | {notes} |".format(
                artifact=artifact.get("artifact_name", ""),
                evidence=artifact.get("evidence_level", mode.get("evidence_level", "")),
                mode=mode.get("mode", ""),
                latency=profile_text(artifact.get("best_latency_safe")),
                quality=profile_text(artifact.get("best_quality")),
                balanced=profile_text(artifact.get("best_balanced")),
                p50=metric_text(best, "p50_ms"),
                p95=metric_text(best, "p95_ms"),
                top1=metric_text(best, "exact_top1_admission_rate"),
                top10=metric_text(best, "exact_top10_admission_recall"),
                recall=metric_text(best, "recall@10"),
                ndcg=metric_text(best, "ndcg@10"),
                mrr=metric_text(best, "mrr@10"),
                index_bytes=best.get("index_bytes", "") if isinstance(best, dict) else "",
                coverage=coverage_text,
                notes=", ".join(str(note) for note in dict.fromkeys(notes)),
            )
        )

    lines.extend(["", "## Promising Rejected Profiles", ""])
    for artifact in report.get("artifacts", []):
        if not isinstance(artifact, dict):
            continue
        rejected = artifact.get("top_promising_rejected_profiles", [])
        if not isinstance(rejected, list) or not rejected:
            lines.extend([f"### {artifact.get('artifact_name', '')}", "", "- None", ""])
            continue
        lines.extend([
            f"### {artifact.get('artifact_name', '')}",
            "",
            "| profile | evidence | p95 ms | top10 | ndcg@10 | reasons | settings |",
            "|---|---|---:|---:|---:|---|---|",
        ])
        for row in rejected:
            if not isinstance(row, dict):
                continue
            settings = row.get("settings", {})
            if not isinstance(settings, dict):
                settings = {}
            setting_text = ", ".join(
                f"{key}={value}"
                for key, value in settings.items()
                if value not in (None, "", "off")
            )
            reasons = row.get("failure_reasons", [])
            if not isinstance(reasons, list):
                reasons = []
            lines.append(
                "| {profile} | {evidence} | {p95} | {top10} | {ndcg} | {reasons} | {settings} |".format(
                    profile=row.get("profile", ""),
                    evidence=row.get("evidence_level", artifact.get("evidence_level", "")),
                    p95=metric_text(row, "p95_ms"),
                    top10=metric_text(row, "exact_top10_admission_recall"),
                    ndcg=metric_text(row, "ndcg@10"),
                    reasons=", ".join(str(reason) for reason in reasons),
                    settings=setting_text,
                )
            )
        lines.append("")
    return "\n".join(lines)


def compute_document_node_token_pooling_recommendation(
    serving_grid: dict[str, Any],
    *,
    exact_baseline: dict[str, Any],
    min_top10_admission: float,
    min_ndcg_ratio_vs_exact: float,
    max_p95_ms: float,
) -> dict[str, Any]:
    raw_rows = serving_grid.get("results", serving_grid.get("summary_rows", []))
    rows = [
        item
        for item in raw_rows
        if isinstance(item, dict)
        and str(item.get("profile", "")) in DOCUMENT_NODE_SERVING_GRID_TOKEN_POOLING_FOCUS_PROFILES
    ]
    exact_metrics = exact_baseline.get("metrics", {}) if isinstance(exact_baseline, dict) else {}
    exact_baseline_ndcg = (
        serving_row_metric({"ndcg@10": exact_metrics.get("ndcg@10")}, "ndcg@10")
        if isinstance(exact_metrics, dict)
        else None
    )
    threshold_rows: list[dict[str, Any]] = []
    rejected_profiles: list[dict[str, Any]] = []
    rejected_pooling_too_lossy: list[dict[str, Any]] = []
    rejected_pooling_no_memory_gain: list[dict[str, Any]] = []
    rejected_pooling_build_failed: list[dict[str, Any]] = []
    unavailable_criteria: set[str] = set()
    baseline_memory_by_family: dict[str, int] = {}

    def pooling_family(profile: str) -> str:
        for suffix in ("_pool_075", "_pool_050", "_pool_033"):
            if profile.endswith(suffix):
                return profile[: -len(suffix)]
        return profile

    def row_memory_bytes(row: dict[str, Any]) -> int:
        for key in ("index_bytes", "estimated_index_bytes"):
            value = row.get(key)
            try:
                parsed = int(value)
            except (TypeError, ValueError):
                continue
            if parsed > 0:
                return parsed
        return (
            int(row.get("docmap_bytes") or 0)
            + int(row.get("sidecar_bytes") or 0)
            + int(row.get("graph_bytes") or 0)
        )

    for row in rows:
        if str(row.get("token_pooling", "off")) == "off":
            memory_bytes = row_memory_bytes(row)
            if memory_bytes > 0:
                baseline_memory_by_family[pooling_family(str(row.get("profile", "")))] = (
                    memory_bytes
                )

    for row in rows:
        failures, unavailable = serving_threshold_failures(
            row,
            min_top10_admission=min_top10_admission,
            min_ndcg_ratio_vs_exact=min_ndcg_ratio_vs_exact,
            max_p95_ms=max_p95_ms,
            exact_baseline_ndcg=exact_baseline_ndcg,
        )
        summary = serving_recommendation_row(row)
        profile_name = str(summary.get("profile", ""))
        family = pooling_family(profile_name)
        memory_bytes = row_memory_bytes(row)
        baseline_memory_bytes = baseline_memory_by_family.get(family, 0)
        token_pooling = str(summary.get("token_pooling") or row.get("token_pooling") or "off")
        pooled_row = token_pooling != "off"
        memory_gain_ratio = (
            round(1.0 - (memory_bytes / baseline_memory_bytes), 6)
            if memory_bytes > 0 and baseline_memory_bytes > 0
            else None
        )
        build_failed = bool(
            row.get("build_failed")
            or row.get("skipped")
            or row.get("index_build_failed")
            or str(row.get("terminated_or_completed", "")).lower() in {"failed", "skipped"}
            or (memory_bytes <= 0 and row.get("index_bytes") is not None)
        )
        if build_failed and "rejected_pooling_build_failed" not in failures:
            failures.append("rejected_pooling_build_failed")
        if (
            pooled_row
            and baseline_memory_bytes > 0
            and memory_bytes > 0
            and memory_bytes >= baseline_memory_bytes
            and "rejected_pooling_no_memory_gain" not in failures
        ):
            failures.append("rejected_pooling_no_memory_gain")
        if (
            pooled_row
            and any(
                reason in failures
                for reason in (
                    "top10_admission_below_threshold",
                    "ndcg_below_exact_ratio",
                    "rejected_zero_qrels_quality",
                    "rejected_zero_exact_admission",
                )
            )
            and "rejected_pooling_too_lossy" not in failures
        ):
            failures.append("rejected_pooling_too_lossy")
        failures = sorted(dict.fromkeys(failures))
        summary["threshold_pass"] = not failures
        summary["failure_reasons"] = failures
        summary["unavailable_criteria"] = unavailable
        summary["pooling_family"] = family
        summary["memory_bytes"] = memory_bytes
        summary["baseline_memory_bytes"] = baseline_memory_bytes or None
        summary["memory_gain_ratio_vs_unpooled"] = memory_gain_ratio
        summary["selection_metrics"] = {
            "p95_ms": serving_row_p95(row),
            "exact_top10_admission_recall": serving_row_metric(
                row,
                "exact_top10_admission_recall",
            ),
            "ndcg@10": serving_row_metric(row, "ndcg@10"),
            "tokens_pooled_p50": row.get("tokens_pooled_p50"),
            "token_pooling_ratio_p50": row.get("token_pooling_ratio_p50"),
            "exact_rerank_pairs_p50": row.get("exact_rerank_pairs_p50"),
            "index_build_elapsed_ms": row.get("index_build_elapsed_ms"),
            "index_bytes": row.get("index_bytes"),
            "docmap_bytes": row.get("docmap_bytes"),
            "sidecar_bytes": row.get("sidecar_bytes"),
            "graph_bytes": row.get("graph_bytes"),
            "memory_gain_ratio_vs_unpooled": memory_gain_ratio,
        }
        unavailable_criteria.update(str(item) for item in unavailable)
        threshold_rows.append(summary)
        if failures:
            rejected_profiles.append(summary)
        if "rejected_pooling_too_lossy" in failures:
            rejected_pooling_too_lossy.append(summary)
        if "rejected_pooling_no_memory_gain" in failures:
            rejected_pooling_no_memory_gain.append(summary)
        if "rejected_pooling_build_failed" in failures:
            rejected_pooling_build_failed.append(summary)

    eligible = [
        item for item in threshold_rows
        if (
            item["threshold_pass"]
            and not serving_row_experimental(item)
            and serving_row_p95(item) is not None
        )
    ]
    pooled_eligible = [
        item
        for item in eligible
        if str(item.get("token_pooling") or "off") != "off"
        and int(item.get("memory_bytes") or 0) > 0
    ]
    best_memory_safe_pooling = min(
        pooled_eligible,
        key=lambda item: (
            int(item.get("memory_bytes") or 0),
            serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
            str(item.get("id", "")),
        ),
        default=None,
    )
    best_pooling_latency_safe = min(
        pooled_eligible,
        key=lambda item: (
            serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
            int(item.get("memory_bytes") or 0),
            str(item.get("id", "")),
        ),
        default=None,
    )
    use_ndcg = serving_quality_available(rows)
    best_pooling_quality_safe = max(
        pooled_eligible,
        key=lambda item: (
            (serving_row_metric(item, "ndcg@10") or 0.0)
            if use_ndcg
            else (serving_row_metric(item, "exact_top10_admission_recall") or 0.0),
            serving_row_metric(item, "exact_top10_admission_recall") or 0.0,
            -(serving_row_p95(item) if serving_row_p95(item) is not None else float("inf")),
            str(item.get("id", "")),
        ),
        default=None,
    )
    if best_pooling_latency_safe is not None:
        best_pooling_latency_safe = {
            **best_pooling_latency_safe,
            "criteria_unavailable": sorted(unavailable_criteria),
            "selection_basis": "lowest_p95_passing_thresholds",
        }
    if best_memory_safe_pooling is not None:
        best_memory_safe_pooling = {
            **best_memory_safe_pooling,
            "criteria_unavailable": sorted(unavailable_criteria),
            "selection_basis": "lowest_index_bytes_passing_thresholds",
        }
    if best_pooling_quality_safe is not None:
        best_pooling_quality_safe = {
            **best_pooling_quality_safe,
            "criteria_unavailable": sorted(unavailable_criteria),
            "selection_basis": "ndcg@10" if use_ndcg else "exact_top10_admission_recall",
        }
    return {
        "available": bool(rows),
        "profile_count": len(rows),
        "thresholds": {
            "serving_min_top10_admission": min_top10_admission,
            "serving_min_ndcg_ratio_vs_exact": min_ndcg_ratio_vs_exact,
            "serving_max_p95_ms": max_p95_ms,
        },
        "exact_baseline": exact_baseline,
        "selection_basis": (
            "qrels_ndcg_and_admission_latency"
            if use_ndcg
            else "admission_latency_without_qrels"
        ),
        "best_memory_safe_pooling": best_memory_safe_pooling,
        "best_latency_safe_pooling": best_pooling_latency_safe,
        "best_pooling_latency_safe": best_pooling_latency_safe,
        "best_pooling_quality_safe": best_pooling_quality_safe,
        "profile_thresholds": sorted(
            threshold_rows,
            key=lambda item: (
                serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
                str(item.get("id", "")),
            ),
        ),
        "rejected_pooling_profiles": sorted(
            rejected_profiles,
            key=lambda item: (
                serving_row_p95(item) if serving_row_p95(item) is not None else float("inf"),
                str(item.get("id", "")),
            ),
        ),
        "rejected_pooling_too_lossy": sorted(
            rejected_pooling_too_lossy,
            key=lambda item: (str(item.get("pooling_family", "")), str(item.get("id", ""))),
        ),
        "rejected_pooling_no_memory_gain": sorted(
            rejected_pooling_no_memory_gain,
            key=lambda item: (str(item.get("pooling_family", "")), str(item.get("id", ""))),
        ),
        "rejected_pooling_build_failed": sorted(
            rejected_pooling_build_failed,
            key=lambda item: (str(item.get("pooling_family", "")), str(item.get("id", ""))),
        ),
    }


def _synthetic_serving_row(
    profile: str,
    *,
    p95: float | None,
    admission: float,
    ndcg: float | None,
    storage: str = "f16",
    candidate_source: str = "proxy_vector",
    proxy_encoder: str = "normalized_mean",
    centroids: str = "off",
    token_pooling: str = "off",
    token_pooling_target_ratio: float = 1.0,
    ef: int = 100,
    oversampling: int = 1,
    stats_sample: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if stats_sample is None:
        stats_sample = {}
    return {
        "profile": profile,
        "candidate_source": candidate_source,
        "proxy_encoder": proxy_encoder,
        "centroids": centroids,
        "storage_kind": storage,
        "cache_mode": "auto",
        "token_pooling": token_pooling,
        "token_pooling_target_ratio": token_pooling_target_ratio,
        "ef": ef,
        "oversampling": oversampling,
        "largest_budget": 800,
        "p50_latency_ms_at_largest_budget": None if p95 is None else round(p95 * 0.7, 3),
        "p95_latency_ms_at_largest_budget": p95,
        "exact_top1_admission_rate": admission,
        "exact_top10_admission_recall": admission,
        "recall@10": ndcg,
        "ndcg@10": ndcg,
        "mrr@10": ndcg,
        "index_bytes": 1000,
        "stats_available": document_node_serving_stats_available(stats_sample),
        "last_scan_stats_sample": stats_sample,
    }


