def document_node_colbert_candidate_source_focus_skipped_row(
    *,
    args: argparse.Namespace,
    profile: DocumentNodeServingProfile,
    candidate_k: int,
    effective_rerank_k: int,
    estimate: dict[str, Any],
    decision: dict[str, Any],
    counts: dict[str, int],
) -> dict[str, Any]:
    docs_loaded = int(counts.get("docs_loaded", 0) or 0)
    codebook_source, codebook_path, codebook_top_m = (
        effective_quantized_inverted_codebook_settings(args, profile)
    )
    return {
        "profile": profile.name,
        "candidate_source": profile.candidate_source,
        "graph_mode": "document_nodes",
        "proxy_encoder": profile.proxy_encoder,
        "centroids": profile.centroids,
        "centroid_count": profile.centroid_count,
        "storage_kind": profile.storage_kind,
        "storage_cache_mode": profile.cache_mode,
        "token_pooling": profile.token_pooling,
        "token_pooling_target_ratio": profile.token_pooling_target_ratio,
        "centroid_lite_max_postings_per_token": (
            profile.centroid_lite_max_postings_per_token
        ),
        "centroid_lite_probe_centroids_per_token": (
            profile.centroid_lite_probe_centroids_per_token
        ),
        "centroid_lite_codeword_top_m": profile.centroid_lite_codeword_top_m,
        "centroid_lite_posting_selection": profile.centroid_lite_posting_selection,
        "centroid_lite_candidate_scoring": profile.centroid_lite_candidate_scoring,
        "centroid_lite_score_threshold": profile.centroid_lite_score_threshold,
        "centroid_lite_score_drop_from_best": (
            profile.centroid_lite_score_drop_from_best
        ),
        "centroid_lite_pruning": profile.centroid_lite_pruning,
        "centroid_lite_bitset_prefilter": profile.centroid_lite_bitset_prefilter,
        "centroid_lite_bitset_min_token_matches": (
            profile.centroid_lite_bitset_min_token_matches
        ),
        "quantized_inverted_codebook": codebook_source,
        "quantized_inverted_codebook_path": (
            portable_path(Path(codebook_path)) if codebook_path else ""
        ),
        "quantized_inverted_codebook_top_m": codebook_top_m,
        "quantized_inverted_max_postings_per_token": (
            profile.quantized_inverted_max_postings_per_token
        ),
        "quantized_inverted_probe_codewords_per_token_config": (
            profile.quantized_inverted_probe_codewords_per_token
        ),
        "quantized_inverted_posting_selection": (
            profile.quantized_inverted_posting_selection
        ),
        "quantized_inverted_compact_scoring": (
            profile.quantized_inverted_compact_scoring
        ),
        "quantized_inverted_query_codeword_kernel": (
            profile.quantized_inverted_query_codeword_kernel
        ),
        "quantized_inverted_compact_doc_order": (
            profile.quantized_inverted_compact_doc_order
        ),
        "quantized_inverted_token_coverage": (
            profile.quantized_inverted_token_coverage
        ),
        "quantized_inverted_min_token_matches_config": (
            effective_quantized_inverted_min_token_matches(args, profile)
        ),
        "quantized_inverted_precompact_mode": profile.quantized_inverted_precompact,
        "quantized_inverted_precompact_score_k": (
            profile.quantized_inverted_precompact_score_k
        ),
        "quantized_inverted_precompact_coverage_k": (
            profile.quantized_inverted_precompact_coverage_k
        ),
        "quantized_inverted_precompact_per_token_k": (
            profile.quantized_inverted_precompact_per_token_k
        ),
        "quantized_inverted_compact_max_docs": (
            profile.quantized_inverted_compact_max_docs
        ),
        "candidate_budget": candidate_k,
        "exact_rerank_mode": profile.exact_rerank_mode,
        "requested_exact_rerank_k": int(
            profile.exact_rerank_k or getattr(args, "exact_rerank_k", 0) or 0
        ),
        "exact_rerank_k": effective_rerank_k,
        "effective_exact_rerank_k": effective_rerank_k,
        "docs": docs_loaded,
        "index_build_skipped": True,
        "index_rebuild_reason": "estimate_exceeds_limit",
        "skip_reason": "estimate_exceeds_limit",
        "skip_reasons": list(decision.get("reasons", [])),
        "p50_ms": None,
        "p95_ms": None,
        "p99_ms": None,
        "qps": None,
        "recall@10": None,
        "ndcg@10": None,
        "mrr@10": None,
        "metrics": {},
        "qrels_covered": 0,
        "queries_with_qrels": 0,
        "exact_top1_admission_rate": None,
        "exact_top10_admission_recall": None,
        "exact_topk_admission_recall": None,
        "sampled_admission": {
            "admission_evidence": "unavailable",
            "exact_admission_available": False,
            "reason": "index_build_skipped",
        },
        "admission_evidence": "unavailable",
        "exact_admission_available": False,
        "oracle_queries_compared": 0,
        "scan_stats_summary": {},
        "candidate_source_stats": {},
        "final_ranking_source": "unavailable",
        "bm25_or_sparse_rescue_active": (
            profile.bm25_candidate_injection != "off"
            or profile.sparse_candidate_source != "off"
        ),
        "serving_slow_path_warnings": ["index_build_skipped_estimate_exceeds_limit"],
        "serving_slow_path_failed": False,
        "index_phase": {
            "skipped": True,
            "reason": "estimate_exceeds_limit",
            "build_resource_estimate": estimate,
            "build_resource_estimate_decision": decision,
            "index_bytes": 0,
            "index_stats": {},
            "build_stats": {},
        },
        "estimated_build_memory_mb": estimate.get("estimated_build_memory_mb"),
        "estimated_index_bytes": estimate.get("estimated_index_bytes"),
        "estimate_components": estimate.get("estimate_components"),
        "build_resource_estimate": estimate,
        "build_resource_estimate_decision": decision,
    }


def document_node_colbert_candidate_source_focus_recommendation(
    rows: Sequence[dict[str, Any]],
    *,
    docs_loaded: int,
) -> dict[str, Any]:
    def metric_float(row: dict[str, Any] | None, key: str, default: float = 0.0) -> float:
        if row is None:
            return default
        value = row.get(key)
        if isinstance(value, dict):
            for summary_key in ("p50", "mean", "max", "value"):
                summary_value = value.get(summary_key)
                if summary_value is not None:
                    try:
                        return float(summary_value)
                    except (TypeError, ValueError):
                        return default
            return default
        if value is None:
            return default
        try:
            return float(value)
        except (TypeError, ValueError):
            return default

    valid_rows = [row for row in rows if isinstance(row, dict)]
    proxy_rows = [
        row
        for row in valid_rows
        if row.get("profile") == "proxy_normalized_mean_proxy_only"
    ]
    proxy_best = max(
        proxy_rows,
        key=lambda row: float(row.get("ndcg@10", 0.0) or 0.0),
        default=None,
    )
    proxy_ndcg = float(proxy_best.get("ndcg@10", 0.0) or 0.0) if proxy_best else 0.0
    centroid_rows = [
        row
        for row in valid_rows
        if str(row.get("candidate_source", "")) == "centroid_lite"
    ]
    centroid_best = max(
        centroid_rows,
        key=lambda row: float(row.get("ndcg@10", 0.0) or 0.0),
        default=None,
    )
    capped_rows = [
        row
        for row in centroid_rows
        if int(row.get("centroid_lite_max_postings_per_token", 0) or 0) > 0
    ]
    capped_best = max(
        capped_rows,
        key=lambda row: float(row.get("ndcg@10", 0.0) or 0.0),
        default=None,
    )
    uncapped_centroid_rows = [
        row
        for row in centroid_rows
        if int(row.get("centroid_lite_max_postings_per_token", 0) or 0) == 0
    ]
    uncapped_centroid_best = max(
        uncapped_centroid_rows,
        key=lambda row: (
            metric_float(row, "exact_top10_admission_recall"),
            metric_float(row, "ndcg@10"),
        ),
        default=None,
    )
    quantized_rows = [
        row
        for row in valid_rows
        if str(row.get("candidate_source", "")) == "quantized_inverted_experimental"
    ]
    quantized_best = max(
        quantized_rows,
        key=lambda row: float(row.get("ndcg@10", 0.0) or 0.0),
        default=None,
    )
    quantized_rank_limited_profiles: list[dict[str, Any]] = []
    for row in quantized_rows:
        candidates = metric_float(row, "quantized_inverted_candidates")
        docs_scored = metric_float(row, "quantized_inverted_docs_scored")
        exact_docs = metric_float(row, "exact_rerank_docs")
        effective_rerank_k = metric_float(row, "effective_exact_rerank_k")
        ndcg = metric_float(row, "ndcg@10")
        candidate_pool = max(candidates, docs_scored)
        if (
            candidate_pool > 0.0
            and exact_docs > 0.0
            and candidate_pool > exact_docs * 1.5
            and ndcg < 0.30
        ):
            quantized_rank_limited_profiles.append(
                {
                    "profile": row.get("profile"),
                    "candidate_budget": row.get("candidate_budget"),
                    "effective_exact_rerank_k": (
                        int(effective_rerank_k) if effective_rerank_k else None
                    ),
                    "quantized_inverted_candidates": int(candidates),
                    "quantized_inverted_docs_scored": int(docs_scored),
                    "exact_rerank_docs": int(exact_docs),
                    "ndcg@10": ndcg,
                }
            )
    recommendations: list[str] = []
    if centroid_best is not None:
        centroid_ndcg = metric_float(centroid_best, "ndcg@10")
        touched_ratio = metric_float(
            centroid_best, "centroid_docs_touched_ratio", default=-1.0
        )
        if (
            centroid_ndcg > proxy_ndcg
            and touched_ratio >= 0.80
        ):
            recommendations.append("centroid_pruning_or_bitset_prefilter")
    if centroid_best is not None and capped_best is not None:
        recommendations.append("uniform_centroid_caps_diagnostic_only")
        centroid_ndcg = metric_float(uncapped_centroid_best, "ndcg@10")
        capped_ndcg = metric_float(capped_best, "ndcg@10")
        capped_p95 = metric_float(capped_best, "p95_ms")
        centroid_p95 = metric_float(uncapped_centroid_best, "p95_ms")
        if centroid_ndcg - capped_ndcg >= 0.10 and (
            capped_p95 <= centroid_p95 or capped_p95 > 0.0
        ):
            recommendations.append("uniform_centroid_caps_insufficient")
        uncapped_admission = metric_float(
            uncapped_centroid_best, "exact_top10_admission_recall"
        )
        capped_admission = metric_float(capped_best, "exact_top10_admission_recall")
        uncapped_docs_touched = metric_float(
            uncapped_centroid_best, "centroid_docs_touched_ratio", default=-1.0
        )
        capped_docs_touched = metric_float(
            capped_best, "centroid_docs_touched_ratio", default=-1.0
        )
        if uncapped_docs_touched < 0.0:
            uncapped_docs_touched = metric_float(
                uncapped_centroid_best, "centroid_docs_touched", default=-1.0
            )
        if capped_docs_touched < 0.0:
            capped_docs_touched = metric_float(
                capped_best, "centroid_docs_touched", default=-1.0
            )
        cap_improves_admission = capped_admission > uncapped_admission
        cap_reduces_docs = (
            uncapped_docs_touched >= 0.0
            and capped_docs_touched >= 0.0
            and capped_docs_touched < uncapped_docs_touched
        )
        if not (cap_improves_admission and cap_reduces_docs):
            recommendations.append("uniform_centroid_cap_not_promotable")
    if quantized_best is not None:
        quantized_ndcg = float(quantized_best.get("ndcg@10", 0.0) or 0.0)
        quantized_admission = quantized_best.get("exact_top10_admission_recall")
        centroid_ndcg = (
            float(centroid_best.get("ndcg@10", 0.0) or 0.0)
            if centroid_best is not None
            else 0.0
        )
        if quantized_ndcg > max(proxy_ndcg, centroid_ndcg) or (
            quantized_admission is not None
            and float(quantized_admission) >= 0.80
        ):
            recommendations.append("prioritize_quantized_codebook_postings")
        if quantized_rank_limited_profiles:
            recommendations.append("quantized_compact_ranking_bottleneck")
            recommendations.append("sweep_exact_rerank_k_for_quantized")
    best_native = max(
        valid_rows,
        key=lambda row: (
            float(row.get("ndcg@10", 0.0) or 0.0),
            -float(row.get("p95_ms", 1e12) or 1e12),
        ),
        default=None,
    )
    if best_native is not None and proxy_best is not None:
        best_ndcg = float(best_native.get("ndcg@10", 0.0) or 0.0)
        if best_native.get("profile") == proxy_best.get("profile") or best_ndcg <= proxy_ndcg:
            recommendations.append("learned_fde_or_different_native_colbert_admission")
    return {
        "docs_loaded": docs_loaded,
        "best_proxy_baseline": proxy_best.get("profile") if proxy_best else None,
        "best_centroid_lite": centroid_best.get("profile") if centroid_best else None,
        "best_quantized": quantized_best.get("profile") if quantized_best else None,
        "best_overall_by_ndcg": best_native.get("profile") if best_native else None,
        "quantized_rank_limited_profiles": quantized_rank_limited_profiles,
        "recommendations": unique_preserve_order(recommendations),
    }


def _row_float_metric(
    row: dict[str, Any],
    key: str,
    *,
    stat: str = "p95",
) -> float | None:
    value = row.get(key)
    if isinstance(value, dict):
        for candidate_key in (stat, "p95", "p50", "mean", "value"):
            candidate = value.get(candidate_key)
            if candidate is None:
                continue
            try:
                return float(candidate)
            except (TypeError, ValueError):
                return None
        return None
    if value is None or isinstance(value, bool):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def quantized_inverted_precompact_rejection_reasons(
    row: dict[str, Any],
    baseline: dict[str, Any] | None = None,
) -> list[str]:
    baseline = baseline or DOCUMENT_NODE_COLBERT_QUANTIZED_INVERTED_PRECOMPACT_BASELINE
    reasons: list[str] = []
    if str(row.get("candidate_source", "")) != "quantized_inverted_experimental":
        reasons.append("rejected_wrong_candidate_source")
    if bool(row.get("bm25_or_sparse_rescue_active", False)):
        reasons.append("rejected_sparse_or_bm25_rescue_active")
    if str(row.get("final_ranking_source", "")) != "exact_heap_maxsim":
        reasons.append("rejected_final_ranking_not_exact_maxsim")

    top1 = _row_float_metric(row, "exact_top1_admission_rate", stat="p50")
    if top1 is None or top1 < 0.94:
        reasons.append("rejected_top1_admission_below_gate")
    top10 = _row_float_metric(row, "exact_top10_admission_recall", stat="p50")
    if top10 is None or top10 < 0.80:
        reasons.append("rejected_top10_admission_below_gate")

    recall = _row_float_metric(row, "recall@10", stat="p50")
    baseline_recall = float(baseline.get("recall@10", 0.0) or 0.0)
    if recall is not None and recall < baseline_recall - 0.01:
        reasons.append("rejected_recall_drop")
    ndcg = _row_float_metric(row, "ndcg@10", stat="p50")
    baseline_ndcg = float(baseline.get("ndcg@10", 0.0) or 0.0)
    if ndcg is not None and ndcg < baseline_ndcg - 0.01:
        reasons.append("rejected_ndcg_drop")

    p95 = _row_float_metric(row, "p95_ms", stat="p95")
    baseline_p95 = float(baseline.get("p95_ms", 0.0) or 0.0)
    if p95 is None or baseline_p95 <= 0.0 or p95 > baseline_p95 * 0.75:
        reasons.append("rejected_latency_not_improved")

    compact_docs = _row_float_metric(
        row,
        "quantized_inverted_compact_docs_scored",
        stat="p95",
    )
    if compact_docs is None:
        compact_docs = _row_float_metric(row, "quantized_inverted_docs_scored", stat="p95")
    if (
        compact_docs is None
        or compact_docs
        > DOCUMENT_NODE_COLBERT_QUANTIZED_INVERTED_PRECOMPACT_COMPACT_DOC_GATE
    ):
        reasons.append("rejected_compact_docs_too_high")
    return unique_preserve_order(reasons)


def quantized_inverted_precompact_focus_recommendation(
    rows: Sequence[dict[str, Any]],
) -> dict[str, Any]:
    baseline = dict(DOCUMENT_NODE_COLBERT_QUANTIZED_INVERTED_PRECOMPACT_BASELINE)
    valid_rows = [row for row in rows if isinstance(row, dict)]
    rejected_profiles: list[dict[str, Any]] = []
    accepted_rows: list[dict[str, Any]] = []
    for row in valid_rows:
        reasons = quantized_inverted_precompact_rejection_reasons(row, baseline)
        if reasons:
            rejected_profiles.append(
                {
                    "profile": row.get("profile"),
                    "candidate_budget": row.get("candidate_budget"),
                    "p95_ms": row.get("p95_ms"),
                    "exact_top1_admission_rate": row.get("exact_top1_admission_rate"),
                    "exact_top10_admission_recall": row.get(
                        "exact_top10_admission_recall"
                    ),
                    "recall@10": row.get("recall@10"),
                    "ndcg@10": row.get("ndcg@10"),
                    "quantized_inverted_compact_docs_scored": row.get(
                        "quantized_inverted_compact_docs_scored"
                    ),
                    "rejection_reasons": reasons,
                }
            )
        else:
            accepted_rows.append(row)
    accepted_rows = sorted(
        accepted_rows,
        key=lambda row: (
            _row_float_metric(row, "p95_ms") if _row_float_metric(row, "p95_ms") is not None else float("inf"),
            _row_float_metric(row, "quantized_inverted_compact_docs_scored") if _row_float_metric(row, "quantized_inverted_compact_docs_scored") is not None else float("inf"),
            str(row.get("profile", "")),
        ),
    )
    return {
        "baseline": baseline,
        "thresholds": {
            "min_exact_top1_admission_rate": 0.94,
            "min_exact_top10_admission_recall": 0.80,
            "min_recall_delta_vs_baseline": -0.01,
            "min_ndcg_delta_vs_baseline": -0.01,
            "max_p95_ms": float(baseline["p95_ms"]) * 0.75,
            "max_compact_docs_scored": (
                DOCUMENT_NODE_COLBERT_QUANTIZED_INVERTED_PRECOMPACT_COMPACT_DOC_GATE
            ),
        },
        "best_quantized_inverted_precompact": (
            accepted_rows[0] if accepted_rows else None
        ),
        "accepted_profiles": accepted_rows,
        "rejected_profiles": rejected_profiles,
    }


def quantized_inverted_exact_rerank_focus_recommendation(
    rows: Sequence[dict[str, Any]],
) -> dict[str, Any]:
    valid_rows = [row for row in rows if isinstance(row, dict)]
    if not valid_rows:
        return {
            "baseline": None,
            "thresholds": {
                "baseline_exact_rerank_k": 512,
                "min_exact_top1_admission_rate": 0.94,
                "min_exact_top10_admission_recall": 0.80,
                "max_recall_drop_vs_512": 0.005,
                "max_ndcg_drop_vs_512": 0.005,
            },
            "best_exact_rerank_setting": None,
            "accepted_profiles": [],
            "rejected_profiles": [],
        }
    baseline_candidates = [
        row
        for row in valid_rows
        if int(row.get("effective_exact_rerank_k", 0) or 0) == 512
        and str(row.get("exact_rerank_mode", "")) == "topk"
    ]
    if not baseline_candidates:
        baseline_candidates = [
            row
            for row in valid_rows
            if int(row.get("effective_exact_rerank_k", 0) or 0)
            == max(int(item.get("effective_exact_rerank_k", 0) or 0) for item in valid_rows)
        ]
    baseline = sorted(
        baseline_candidates,
        key=lambda row: (
            str(row.get("exact_rerank_mode", "")) != "topk",
            str(row.get("profile", "")),
        ),
    )[0]
    baseline_recall = _row_float_metric(baseline, "recall@10", stat="p50")
    baseline_ndcg = _row_float_metric(baseline, "ndcg@10", stat="p50")
    baseline_k = int(baseline.get("effective_exact_rerank_k", 0) or 0)

    accepted_rows: list[dict[str, Any]] = []
    rejected_profiles: list[dict[str, Any]] = []
    for row in valid_rows:
        reasons: list[str] = []
        if str(row.get("candidate_source", "")) != "quantized_inverted_experimental":
            reasons.append("rejected_wrong_candidate_source")
        if bool(row.get("bm25_or_sparse_rescue_active", False)):
            reasons.append("rejected_sparse_or_bm25_rescue_active")
        if str(row.get("final_ranking_source", "")) != "exact_heap_maxsim":
            reasons.append("rejected_final_ranking_not_exact_maxsim")
        top1 = _row_float_metric(row, "exact_top1_admission_rate", stat="p50")
        if top1 is None:
            reasons.append("rejected_exact_top1_admission_unavailable")
        elif top1 < 0.94:
            reasons.append("rejected_top1_admission_below_gate")
        top10 = _row_float_metric(row, "exact_top10_admission_recall", stat="p50")
        if top10 is None:
            reasons.append("rejected_exact_top10_admission_unavailable")
        elif top10 < 0.80:
            reasons.append("rejected_top10_admission_below_gate")

        row_k = int(row.get("effective_exact_rerank_k", 0) or 0)
        if row_k < baseline_k:
            recall = _row_float_metric(row, "recall@10", stat="p50")
            if baseline_recall is not None and recall is not None:
                if recall < baseline_recall - 0.005:
                    reasons.append("rejected_recall_drop_vs_512")
            elif baseline_recall is not None:
                reasons.append("rejected_recall_unavailable")
            ndcg = _row_float_metric(row, "ndcg@10", stat="p50")
            if baseline_ndcg is not None and ndcg is not None:
                if ndcg < baseline_ndcg - 0.005:
                    reasons.append("rejected_ndcg_drop_vs_512")
            elif baseline_ndcg is not None:
                reasons.append("rejected_ndcg_unavailable")
            adaptive_changed = row.get("adaptive_rerank_topk_changed_vs_full")
            if str(row.get("exact_rerank_mode", "")) == "adaptive" and (
                adaptive_changed is True or str(adaptive_changed).lower() == "true"
            ):
                reasons.append("rejected_adaptive_topk_changed")
        if row_k < baseline_k and reasons:
            reasons.append("quality_risk_lower_exact_rerank_k")
        if reasons:
            rejected_profiles.append(
                {
                    "profile": row.get("profile"),
                    "exact_rerank_mode": row.get("exact_rerank_mode"),
                    "effective_exact_rerank_k": row.get("effective_exact_rerank_k"),
                    "candidate_budget": row.get("candidate_budget"),
                    "p95_ms": row.get("p95_ms"),
                    "exact_top1_admission_rate": row.get("exact_top1_admission_rate"),
                    "exact_top10_admission_recall": row.get(
                        "exact_top10_admission_recall"
                    ),
                    "recall@10": row.get("recall@10"),
                    "ndcg@10": row.get("ndcg@10"),
                    "exact_rerank_time_us": row.get("exact_rerank_time_us"),
                    "exact_heap_fetch_time_us": row.get("exact_heap_fetch_time_us"),
                    "rejection_reasons": unique_preserve_order(reasons),
                }
            )
        else:
            accepted_rows.append(row)
    accepted_rows = sorted(
        accepted_rows,
        key=lambda row: (
            _row_float_metric(row, "p95_ms")
            if _row_float_metric(row, "p95_ms") is not None
            else float("inf"),
            int(row.get("effective_exact_rerank_k", 0) or 0),
            str(row.get("exact_rerank_mode", "")),
            str(row.get("profile", "")),
        ),
    )
    return {
        "baseline": baseline,
        "thresholds": {
            "baseline_exact_rerank_k": baseline_k,
            "min_exact_top1_admission_rate": 0.94,
            "min_exact_top10_admission_recall": 0.80,
            "max_recall_drop_vs_512": 0.005,
            "max_ndcg_drop_vs_512": 0.005,
        },
        "best_exact_rerank_setting": accepted_rows[0] if accepted_rows else None,
        "accepted_profiles": accepted_rows,
        "rejected_profiles": rejected_profiles,
    }


def _quantized_acceptance_artifact_section(report: dict[str, Any]) -> dict[str, Any]:
    for key in (
        "document_node_colbert_quantized_inverted_precompact_focus",
        "document_node_colbert_quantized_inverted_exact_rerank_focus",
        "document_node_colbert_candidate_source_focus",
    ):
        value = report.get(key)
        if isinstance(value, dict):
            return value
    return {}


def _quantized_acceptance_rows(report: dict[str, Any]) -> list[dict[str, Any]]:
    section = _quantized_acceptance_artifact_section(report)
    rows = section.get("results") or []
    return [row for row in rows if isinstance(row, dict)]


def _quantized_acceptance_find_row(
    rows: Sequence[dict[str, Any]],
    *,
    name: str | None = None,
    contains: str | None = None,
) -> dict[str, Any] | None:
    candidates: list[dict[str, Any]] = []
    for row in rows:
        profile = str(row.get("profile", ""))
        if name is not None and profile == name:
            candidates.append(row)
        elif contains is not None and contains in profile:
            candidates.append(row)
    if not candidates:
        return None
    return sorted(
        candidates,
        key=lambda row: (
            _row_float_metric(row, "p95_ms")
            if _row_float_metric(row, "p95_ms") is not None
            else float("inf"),
            str(row.get("profile", "")),
        ),
    )[0]


def _quantized_acceptance_best_row(
    rows: Sequence[dict[str, Any]],
    *,
    prefer_admission: bool = False,
) -> dict[str, Any] | None:
    valid = [
        row
        for row in rows
        if isinstance(row, dict)
        and str(row.get("candidate_source", "")) == "quantized_inverted_experimental"
    ]
    if not valid:
        return None
    if prefer_admission:
        valid = sorted(
            valid,
            key=lambda row: (
                -(_row_float_metric(row, "exact_top10_admission_recall") or -1.0),
                -(_row_float_metric(row, "exact_top1_admission_rate") or -1.0),
                _row_float_metric(row, "p95_ms")
                if _row_float_metric(row, "p95_ms") is not None
                else float("inf"),
                str(row.get("profile", "")),
            ),
        )
    else:
        valid = sorted(
            valid,
            key=lambda row: (
                _row_float_metric(row, "p95_ms")
                if _row_float_metric(row, "p95_ms") is not None
                else float("inf"),
                _row_float_metric(row, "quantized_inverted_compact_docs_scored")
                if _row_float_metric(row, "quantized_inverted_compact_docs_scored")
                is not None
                else float("inf"),
                str(row.get("profile", "")),
            ),
        )
    return valid[0]


def _quantized_acceptance_metric(row: dict[str, Any] | None, key: str) -> Any:
    if not row:
        return None
    return row.get(key)


def _quantized_acceptance_row_summary(row: dict[str, Any] | None) -> dict[str, Any] | None:
    if not row:
        return None
    return {
        "profile": row.get("profile"),
        "candidate_source": row.get("candidate_source"),
        "candidate_budget": row.get("candidate_budget"),
        "exact_rerank_k": row.get("effective_exact_rerank_k")
        or row.get("exact_rerank_k"),
        "exact_rerank_mode": row.get("exact_rerank_mode"),
        "final_ranking_source": row.get("final_ranking_source"),
        "p95_ms": row.get("p95_ms"),
        "exact_top1_admission_rate": row.get("exact_top1_admission_rate"),
        "exact_top10_admission_recall": row.get("exact_top10_admission_recall"),
        "recall@10": row.get("recall@10"),
        "ndcg@10": row.get("ndcg@10"),
        "compact_docs_scored": row.get("quantized_inverted_compact_docs_scored"),
        "compact_score_us": row.get("quantized_inverted_compact_score_us"),
        "query_codeword_us": row.get("quantized_inverted_query_codeword_us"),
        "exact_rerank_us": row.get("exact_rerank_time_us")
        or row.get("multivector_exact_rerank_us"),
        "exact_heap_fetch_us": row.get("exact_heap_fetch_time_us"),
        "exact_kernel": row.get("exact_kernel"),
        "bm25_or_sparse_rescue_active": bool(
            row.get("bm25_or_sparse_rescue_active", False)
        ),
    }


def quantized_inverted_default_quality_acceptance_rejection_reasons(
    row: dict[str, Any] | None,
    baseline: dict[str, Any] | None,
    *,
    output_path: Path | None = None,
) -> list[str]:
    if row is None:
        return ["missing_candidate_row"]
    reasons: list[str] = []
    if str(row.get("candidate_source", "")) != "quantized_inverted_experimental":
        reasons.append("rejected_wrong_candidate_source")
    if str(row.get("final_ranking_source", "")) != "exact_heap_maxsim":
        reasons.append("rejected_final_ranking_not_exact_maxsim")
    if bool(row.get("bm25_or_sparse_rescue_active", False)):
        reasons.append("rejected_bm25_or_learned_sparse_active")
    top10 = _row_float_metric(row, "exact_top10_admission_recall")
    if top10 is None or top10 < 0.80:
        reasons.append("rejected_top10_admission_below_gate")
    top1 = _row_float_metric(row, "exact_top1_admission_rate")
    if top1 is None or top1 < 0.94:
        reasons.append("rejected_top1_admission_below_gate")
    if baseline is not None:
        baseline_recall = _row_float_metric(baseline, "recall@10")
        recall = _row_float_metric(row, "recall@10")
        if baseline_recall is not None:
            if recall is None or recall < baseline_recall - 0.01:
                reasons.append("rejected_recall_drop_vs_baseline")
        baseline_ndcg = _row_float_metric(baseline, "ndcg@10")
        ndcg = _row_float_metric(row, "ndcg@10")
        if baseline_ndcg is not None:
            if ndcg is None or ndcg < baseline_ndcg - 0.01:
                reasons.append("rejected_ndcg_drop_vs_baseline")
        baseline_p95 = _row_float_metric(baseline, "p95_ms")
        p95 = _row_float_metric(row, "p95_ms")
        if baseline_p95 is not None:
            if p95 is None or p95 > baseline_p95 * 0.75:
                reasons.append("rejected_p95_not_25_percent_faster_than_baseline")
    compact_docs = _row_float_metric(row, "quantized_inverted_compact_docs_scored")
    if compact_docs is None:
        compact_docs = _row_float_metric(row, "compact_docs_scored")
    compact_score_us = _row_float_metric(row, "quantized_inverted_compact_score_us")
    exact_rerank_us = _row_float_metric(row, "exact_rerank_time_us")
    if exact_rerank_us is None:
        exact_rerank_us = _row_float_metric(row, "multivector_exact_rerank_us")
    candidate_source_us = _row_float_metric(row, "multivector_candidate_source_time_us")
    compact_not_top_two = False
    if compact_score_us is not None:
        phase_values = [
            value
            for value in (compact_score_us, exact_rerank_us, candidate_source_us)
            if value is not None
        ]
        if len(phase_values) >= 2:
            compact_not_top_two = compact_score_us < sorted(phase_values, reverse=True)[1]
    if compact_docs is None:
        reasons.append("rejected_compact_docs_scored_unavailable")
    elif (
        compact_docs
        > DOCUMENT_NODE_COLBERT_QUANTIZED_INVERTED_PRECOMPACT_COMPACT_DOC_GATE
        and not compact_not_top_two
    ):
        reasons.append("rejected_compact_docs_scored_above_gate")
    if output_path is not None and ".nix-dev/tmp" not in output_path.as_posix():
        reasons.append("rejected_generated_output_not_under_nix_dev_tmp")
    return unique_preserve_order(reasons)


def run_quantized_inverted_default_quality_acceptance_report(
    precompact_path: Path,
    *,
    query_codeword_path: Path | None = None,
    compact_layout_path: Path | None = None,
    exact_rerank_path: Path | None = None,
    output_path: Path | None = None,
) -> dict[str, Any]:
    artifact_paths = {
        "precompact_grid": precompact_path,
        "query_codeword_grid": query_codeword_path,
        "compact_layout_grid": compact_layout_path,
        "exact_rerank_grid": exact_rerank_path,
    }
    artifacts: dict[str, dict[str, Any] | None] = {}
    for key, path in artifact_paths.items():
        if path is None:
            artifacts[key] = None
            continue
        artifacts[key] = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(artifacts[key], dict):
            raise SystemExit(f"{key} is not a JSON object: {path}")

    precompact_rows = _quantized_acceptance_rows(artifacts["precompact_grid"] or {})
    query_codeword_rows = _quantized_acceptance_rows(artifacts["query_codeword_grid"] or {})
    compact_layout_rows = _quantized_acceptance_rows(artifacts["compact_layout_grid"] or {})
    exact_rows = _quantized_acceptance_rows(artifacts["exact_rerank_grid"] or {})
    report = run_quantized_inverted_default_quality_acceptance_report_from_rows(
        precompact_rows=precompact_rows,
        query_codeword_rows=query_codeword_rows,
        compact_layout_rows=compact_layout_rows,
        exact_rows=exact_rows,
        exact_rerank_recommendation=(
            (_quantized_acceptance_artifact_section(artifacts["exact_rerank_grid"] or {})).get(
                "exact_rerank_recommendation"
            )
            if artifacts["exact_rerank_grid"]
            else None
        ),
        artifact_paths=artifact_paths,
        output_path=output_path,
    )
    return report


def run_quantized_inverted_default_quality_acceptance_report_from_rows(
    *,
    precompact_rows: Sequence[dict[str, Any]],
    query_codeword_rows: Sequence[dict[str, Any]] | None = None,
    compact_layout_rows: Sequence[dict[str, Any]] | None = None,
    exact_rows: Sequence[dict[str, Any]] | None = None,
    exact_rerank_recommendation: dict[str, Any] | None = None,
    artifact_paths: dict[str, Path | None] | None = None,
    output_path: Path | None = None,
) -> dict[str, Any]:
    query_codeword_rows = query_codeword_rows or []
    compact_layout_rows = compact_layout_rows or []
    exact_rows = exact_rows or []
    artifact_paths = artifact_paths or {
        "precompact_grid": None,
        "query_codeword_grid": None,
        "compact_layout_grid": None,
        "exact_rerank_grid": None,
    }
    current_baseline = (
        _quantized_acceptance_find_row(precompact_rows, name="precompact_off")
        or dict(DOCUMENT_NODE_COLBERT_QUANTIZED_INVERTED_PRECOMPACT_BASELINE)
    )
    best_precompact = _quantized_acceptance_best_row(precompact_rows)
    best_query_codeword = (
        _quantized_acceptance_best_row(query_codeword_rows)
        if query_codeword_rows
        else _quantized_acceptance_find_row(precompact_rows, contains="_blocked")
    )
    best_compact_layout = (
        _quantized_acceptance_best_row(compact_layout_rows)
        if compact_layout_rows
        else _quantized_acceptance_find_row(precompact_rows, contains="_docid")
    )
    exact_rec: dict[str, Any] = (
        exact_rerank_recommendation if isinstance(exact_rerank_recommendation, dict) else {}
    )
    best_exact = None
    if exact_rec:
        best_exact = exact_rec.get("best_exact_rerank_setting")
    if not best_exact:
        best_exact = _quantized_acceptance_best_row(exact_rows, prefer_admission=True)

    final_candidate = best_exact or best_compact_layout or best_precompact
    rejection_reasons = quantized_inverted_default_quality_acceptance_rejection_reasons(
        final_candidate,
        current_baseline,
        output_path=output_path,
    )
    accepted = not rejection_reasons

    before = _quantized_acceptance_row_summary(current_baseline)
    after = _quantized_acceptance_row_summary(final_candidate)
    summary = {
        "before_p95_ms": _quantized_acceptance_metric(before, "p95_ms"),
        "after_p95_ms": _quantized_acceptance_metric(after, "p95_ms"),
        "compact_docs_before": _quantized_acceptance_metric(
            before, "compact_docs_scored"
        ),
        "compact_docs_after": _quantized_acceptance_metric(
            after, "compact_docs_scored"
        ),
        "compact_score_us_before": _quantized_acceptance_metric(
            before, "compact_score_us"
        ),
        "compact_score_us_after": _quantized_acceptance_metric(
            after, "compact_score_us"
        ),
        "query_codeword_us_before": _quantized_acceptance_metric(
            before, "query_codeword_us"
        ),
        "query_codeword_us_after": _quantized_acceptance_metric(
            after, "query_codeword_us"
        ),
        "exact_rerank_us_before": _quantized_acceptance_metric(
            before, "exact_rerank_us"
        ),
        "exact_rerank_us_after": _quantized_acceptance_metric(
            after, "exact_rerank_us"
        ),
        "recall_before": _quantized_acceptance_metric(before, "recall@10"),
        "recall_after": _quantized_acceptance_metric(after, "recall@10"),
        "ndcg_before": _quantized_acceptance_metric(before, "ndcg@10"),
        "ndcg_after": _quantized_acceptance_metric(after, "ndcg@10"),
    }
    report = {
        "suite": "dbpedia_colbert_quantized_inverted_acceptance",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "artifact_paths": {
            key: portable_path(path) if path is not None else None
            for key, path in artifact_paths.items()
        },
        "constraints": {
            "bm25_allowed": False,
            "learned_sparse_allowed": False,
            "candidate_source": "quantized_inverted_experimental",
            "experimental_only": True,
            "final_ranking": "exact_heap_maxsim",
        },
        "thresholds": {
            "min_exact_top10_admission_recall": 0.80,
            "min_exact_top1_admission_rate": 0.94,
            "max_recall_drop_vs_baseline": 0.01,
            "max_ndcg_drop_vs_baseline": 0.01,
            "max_p95_ratio_vs_baseline": 0.75,
            "max_compact_docs_scored": (
                DOCUMENT_NODE_COLBERT_QUANTIZED_INVERTED_PRECOMPACT_COMPACT_DOC_GATE
            ),
        },
        "current_baseline_row": before,
        "best_precompact_row": _quantized_acceptance_row_summary(best_precompact),
        "best_query_codeword_kernel_row": _quantized_acceptance_row_summary(
            best_query_codeword
        ),
        "best_compact_layout_row": _quantized_acceptance_row_summary(
            best_compact_layout
        ),
        "best_exact_rerank_row": _quantized_acceptance_row_summary(best_exact),
        "selected_candidate_row": after,
        "recommended_profile_name": (
            DOCUMENT_NODE_COLBERT_CANDIDATE_SOURCE_DEFAULT_EXTERNAL_QUANTIZED_PROFILE
            if accepted
            else None
        ),
        "benchmark_default_profile": (
            DOCUMENT_NODE_COLBERT_CANDIDATE_SOURCE_DEFAULT_EXTERNAL_QUANTIZED_PROFILE
        ),
        "experimental_default_quality_candidate": (
            DOCUMENT_NODE_COLBERT_CANDIDATE_SOURCE_DEFAULT_EXTERNAL_QUANTIZED_PROFILE
            if accepted
            else None
        ),
        "accepted": accepted,
        "rejection_reasons": rejection_reasons,
        "recommendation_summary": summary,
        "exact_rerank_recommendation": exact_rec if isinstance(exact_rec, dict) else {},
    }
    report["markdown_summary"] = markdown_quantized_inverted_default_quality_acceptance(
        report
    )
    return report


def markdown_quantized_inverted_default_quality_acceptance(
    report: dict[str, Any],
) -> str:
    def fmt(value: Any) -> str:
        if value is None:
            return ""
        if isinstance(value, float):
            return f"{value:.6g}"
        return str(value)

    rows = [
        ("current baseline", report.get("current_baseline_row")),
        ("best precompact", report.get("best_precompact_row")),
        ("best query-codeword", report.get("best_query_codeword_kernel_row")),
        ("best compact layout", report.get("best_compact_layout_row")),
        ("best exact rerank", report.get("best_exact_rerank_row")),
        ("selected", report.get("selected_candidate_row")),
    ]
    lines = [
        "# Quantized Inverted Experimental Acceptance Report",
        "",
        f"- Accepted: `{bool(report.get('accepted'))}`",
        f"- Benchmark default profile: `{report.get('benchmark_default_profile') or ''}`",
        f"- Experimental default-quality candidate: `{report.get('experimental_default_quality_candidate') or ''}`",
        f"- Rejection reasons: `{','.join(str(item) for item in report.get('rejection_reasons', []))}`",
        "",
        "This report is evidence gating for the opt-in `quantized_inverted_experimental` branch. It does not make the branch a production default and final SQL ordering remains exact heap MaxSim.",
        "",
        "| role | profile | p95 ms | top1 | top10 | recall@10 | ndcg@10 | compact docs | compact us | query-codeword us | exact rerank us |",
        "| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for role, row in rows:
        if not isinstance(row, dict):
            continue
        lines.append(
            "| {role} | {profile} | {p95} | {top1} | {top10} | {recall} | {ndcg} | {compact_docs} | {compact_us} | {query_us} | {rerank_us} |".format(
                role=role,
                profile=row.get("profile", ""),
                p95=fmt(row.get("p95_ms")),
                top1=fmt(row.get("exact_top1_admission_rate")),
                top10=fmt(row.get("exact_top10_admission_recall")),
                recall=fmt(row.get("recall@10")),
                ndcg=fmt(row.get("ndcg@10")),
                compact_docs=fmt(row.get("compact_docs_scored")),
                compact_us=fmt(row.get("compact_score_us")),
                query_us=fmt(row.get("query_codeword_us")),
                rerank_us=fmt(row.get("exact_rerank_us")),
            )
        )
    lines.extend(
        [
            "",
            "## Gate Summary",
            "",
            "- Candidate source must be `quantized_inverted_experimental`.",
            "- BM25 and learned-sparse rescue must be inactive.",
            "- Exact top-10 admission must be at least `0.80`; exact top-1 admission must be at least `0.94`.",
            "- Recall@10 and ndcg@10 may drop by at most `0.01` from the baseline row.",
            "- p95 must be at most `0.75x` the baseline p95.",
            "- Compact docs scored must be at most `6000` unless compact scoring is no longer a top-two bottleneck.",
            "- Generated acceptance artifacts must stay under `.nix-dev/tmp/`.",
        ]
    )
    return "\n".join(lines) + "\n"


def run_document_node_colbert_candidate_source_focus(
    conn: psycopg.Connection[Any],
    args: argparse.Namespace,
    queries: list[QueryItem],
    qrels: dict[str, dict[str, int]],
) -> dict[str, Any]:
    started = time.perf_counter()
    if not qrels:
        raise SystemExit(
            "--document-node-colbert-candidate-source-focus requires loaded qrels; "
            "reuse an imported DB with dbpedia_colbert_qrels or load BEIR qrels first"
        )
    query_limit = int(getattr(args, "query_limit", 0) or 0)
    selected_queries = queries[:query_limit] if query_limit > 0 else list(queries)
    if not selected_queries:
        raise SystemExit("--document-node-colbert-candidate-source-focus has no queries")
    counts = dbpedia_colbert_loaded_counts(conn)
    recorder = IncrementalRecorder(getattr(args, "incremental_output", None))
    oracle_artifact: dict[str, Any] | None = None
    oracle_records_all: list[dict[str, Any]] = []
    oracle_records: list[dict[str, Any]] = []
    oracle_missing_loaded_query_ids: list[str] = []
    if args.oracle_input is not None:
        oracle_artifact = load_exact_oracle_artifact(args.oracle_input)
        oracle_records_all = completed_exact_oracle_records(oracle_artifact)
        selected_query_ids = {query.query_id for query in selected_queries}
        loaded_query_ids = {query.query_id for query in queries}
        oracle_missing_loaded_query_ids = [
            str(record.get("query_id"))
            for record in oracle_records_all
            if str(record.get("query_id")) not in loaded_query_ids
        ]
        oracle_records = [
            record
            for record in oracle_records_all
            if str(record.get("query_id")) in selected_query_ids
        ]
    precompact_focus = bool(
        getattr(args, "document_node_colbert_quantized_inverted_precompact_focus", False)
    )
    exact_rerank_focus = bool(
        getattr(
            args,
            "document_node_colbert_quantized_inverted_exact_rerank_focus",
            False,
        )
    )
    active_query_tokens = int(getattr(args, "max_query_vectors", 0) or 0)
    profiles = document_node_colbert_candidate_source_focus_profiles(
        args,
        active_query_tokens=active_query_tokens,
    )
    budgets = effective_document_node_colbert_candidate_source_focus_budgets(args)
    centroid_lite_caps = effective_document_node_colbert_candidate_source_focus_caps(args)
    centroid_lite_probes = effective_document_node_colbert_candidate_source_focus_probes(args)
    centroid_lite_score_thresholds = (
        effective_document_node_colbert_candidate_source_focus_score_thresholds(args)
    )
    centroid_lite_score_drops = (
        effective_document_node_colbert_candidate_source_focus_score_drops(args)
    )
    if recorder.enabled:
        recorder.record(
            "run_metadata",
            metadata={
                "mode": (
                    "document_node_colbert_quantized_inverted_exact_rerank_focus"
                    if exact_rerank_focus
                    else "document_node_colbert_quantized_inverted_precompact_focus"
                    if precompact_focus
                    else "document_node_colbert_candidate_source_focus"
                ),
                "pure_colbert_only": True,
                "quantized_inverted_precompact_focus": precompact_focus,
                "quantized_inverted_exact_rerank_focus": exact_rerank_focus,
                "exact_admission_available": bool(oracle_artifact),
                "admission_evidence": (
                    "sampled_exact_oracle"
                    if oracle_artifact is not None
                    else "beir_qrels_only"
                ),
                "profiles": [profile.name for profile in profiles],
                "candidate_budgets": budgets,
                "centroid_lite_caps": centroid_lite_caps,
                "centroid_lite_probes": centroid_lite_probes,
                "centroid_lite_score_thresholds": centroid_lite_score_thresholds,
                "centroid_lite_score_drop_from_best_values": centroid_lite_score_drops,
                "quantized_inverted_precompact_score_grid": (
                    effective_quantized_inverted_precompact_score_grid(args)
                    if precompact_focus or exact_rerank_focus
                    else []
                ),
                "quantized_inverted_precompact_coverage_k": (
                    effective_quantized_inverted_precompact_coverage_k(args)
                    if precompact_focus or exact_rerank_focus
                    else 0
                ),
                "quantized_inverted_precompact_per_token_k": (
                    effective_quantized_inverted_precompact_per_token_k(args)
                    if precompact_focus or exact_rerank_focus
                    else 0
                ),
                "quantized_inverted_precompact_active_query_tokens": (
                    active_query_tokens if precompact_focus or exact_rerank_focus else 0
                ),
                "exact_rerank_k": int(getattr(args, "exact_rerank_k", 0) or 0),
                "quantized_inverted_exact_rerank_grid": (
                    effective_quantized_inverted_exact_rerank_grid(args)
                    if exact_rerank_focus
                    else []
                ),
                "quantized_inverted_exact_rerank_modes": (
                    effective_quantized_inverted_exact_rerank_modes(args)
                    if exact_rerank_focus
                    else []
                ),
                "query_limit": query_limit,
                "docs_loaded": int(counts.get("docs_loaded", 0) or 0),
                "queries_available": len(queries),
                "queries_evaluated": len(selected_queries),
                "qrels_loaded": int(counts.get("qrels_loaded", 0) or 0),
                "oracle_input": portable_path(args.oracle_input)
                if args.oracle_input
                else None,
            },
        )
        recorder.record(
            "import_preflight",
            docs_loaded=int(counts.get("docs_loaded", 0) or 0),
            queries_available=len(queries),
            effective_queries=len(selected_queries),
            qrels_loaded=int(counts.get("qrels_loaded", 0) or 0),
            oracle_query_count=len(oracle_records_all),
        )
        for profile in profiles:
            recorder.record(
                "planned_profile",
                row_id=f"planned:{profile.name}",
                profile=profile.name,
                candidate_source=profile.candidate_source,
                physical_index_signature=serializable_index_signature(
                    serving_profile_index_signature(args, profile)
                ),
            )
    rows: list[dict[str, Any]] = []
    index_phases: list[dict[str, Any]] = []
    built_index_phases: dict[tuple[tuple[str, Any], ...], dict[str, Any]] = {}
    built_index_profile_names: dict[tuple[tuple[str, Any], ...], list[str]] = {}
    for profile in profiles:
        if not budgets:
            continue
        profile_signature = serving_profile_index_signature(args, profile)
        estimate_args, first_effective_rerank_k = (
            document_node_colbert_candidate_source_focus_args(
                args,
                profile,
                budgets[0],
            )
        )
        dataset_stats_for_estimate = multivector_dataset_stats_for_build_estimate(
            conn,
            profile,
        )
        build_estimate = estimate_index_build_resources(
            dataset_stats_for_estimate,
            estimate_args,
            profile,
        )
        decision_args = (
            args
            if bool(getattr(args, "fail_if_estimate_exceeds_limit", False))
            else clone_args(args, skip_profile_if_estimate_exceeds_limit=True)
        )
        build_estimate_decision = index_build_estimate_decision(
            build_estimate,
            decision_args,
        )
        if build_estimate_decision.get("action") == "fail" and recorder.enabled:
            recorder.record(
                "index_build_failed",
                row_id=f"index:{profile.name}",
                profile=profile.name,
                reason="estimate_exceeds_limit",
                build_resource_estimate=build_estimate,
                build_resource_estimate_decision=build_estimate_decision,
            )
        fail_index_build_estimate_if_requested(
            profile_name=profile.name,
            estimate=build_estimate,
            decision=build_estimate_decision,
        )
        if build_estimate_decision.get("action") == "skip":
            skipped_index_phase = {
                "profile": profile.name,
                "skipped": True,
                "reason": "estimate_exceeds_limit",
                "build_resource_estimate": build_estimate,
                "build_resource_estimate_decision": build_estimate_decision,
                "index_bytes": 0,
                "index_stats": {},
                "build_stats": {},
            }
            index_phases.append({
                "profile": profile.name,
                "candidate_budget": budgets[0],
                "index_phase": skipped_index_phase,
            })
            if recorder.enabled:
                recorder.record(
                    "index_build_skipped",
                    row_id=f"index:{profile.name}",
                    profile=profile.name,
                    reason="estimate_exceeds_limit",
                    candidate_source=profile.candidate_source,
                    physical_index_signature=serializable_index_signature(
                        serving_profile_index_signature(args, profile)
                    ),
                    build_resource_estimate=build_estimate,
                    build_resource_estimate_decision=build_estimate_decision,
                )
            for candidate_k in budgets:
                _focus_args, effective_rerank_k = (
                    document_node_colbert_candidate_source_focus_args(
                        args,
                        profile,
                        candidate_k,
                    )
                )
                row = document_node_colbert_candidate_source_focus_skipped_row(
                    args=args,
                    profile=profile,
                    candidate_k=candidate_k,
                    effective_rerank_k=effective_rerank_k,
                    estimate=build_estimate,
                    decision=build_estimate_decision,
                    counts=counts,
                )
                rows.append(row)
                if recorder.enabled:
                    recorder.record(
                        "query_evaluation_skipped",
                        row_id=f"{profile.name}:candidate_k={candidate_k}",
                        profile=profile.name,
                        candidate_budget=candidate_k,
                        reason="index_build_skipped",
                        row=row,
                    )
            if recorder.enabled:
                recorder.record(
                    "profile_completed",
                    row_id=f"profile:{profile.name}",
                    profile=profile.name,
                    budgets=budgets,
                    skipped=True,
                    rows=[
                        row
                        for row in rows
                        if isinstance(row, dict) and row.get("profile") == profile.name
                    ],
                )
            continue
        profile_index_phase: dict[str, Any] | None = None
        profile_reused_index = profile_signature in built_index_phases
        for budget_index, candidate_k in enumerate(budgets):
            row_id = f"{profile.name}:candidate_k={candidate_k}"
            focus_args, effective_rerank_k = (
                document_node_colbert_candidate_source_focus_args(
                    args,
                    profile,
                    candidate_k,
                )
            )
            if budget_index == 0:
                if profile_reused_index:
                    profile_index_phase = built_index_phases[profile_signature]
                    validate_serving_profile_index_reuse(
                        args=focus_args,
                        profile=profile,
                        index_phase=profile_index_phase,
                        expected_signature=profile_signature,
                    )
                    reused_for = built_index_profile_names.setdefault(
                        profile_signature,
                        [],
                    )
                    if profile.name not in reused_for:
                        reused_for.append(profile.name)
                    profile_index_phase["index_build_reused_for_profiles"] = list(
                        reused_for
                    )
                    if recorder.enabled:
                        recorder.record(
                            "index_build_reused",
                            row_id=f"index:{profile.name}",
                            profile=profile.name,
                            candidate_source=profile.candidate_source,
                            physical_index_signature=serializable_index_signature(
                                profile_signature
                            ),
                            reused_from_profiles=[
                                name for name in reused_for if name != profile.name
                            ],
                        )
                else:
                    if recorder.enabled:
                        recorder.record(
                            "index_build_started",
                            row_id=f"index:{profile.name}",
                            profile=profile.name,
                            candidate_source=profile.candidate_source,
                            physical_index_signature=serializable_index_signature(
                                profile_signature
                            ),
                        )
                    try:
                        profile_index_phase = build_index(conn, focus_args)
                    except Exception as exc:
                        if recorder.enabled:
                            recorder.record(
                                "index_build_failed",
                                row_id=f"index:{profile.name}",
                                profile=profile.name,
                                error=str(exc),
                                error_type=type(exc).__name__,
                            )
                        raise
                    profile_index_phase["index_signature_tuple"] = profile_signature
                    profile_index_phase["index_signature"] = serializable_index_signature(
                        profile_signature
                    )
                    built_index_phases[profile_signature] = profile_index_phase
                    built_index_profile_names[profile_signature] = [profile.name]
                    profile_index_phase["index_build_reused_for_profiles"] = [
                        profile.name
                    ]
                    if recorder.enabled:
                        recorder.record(
                            "index_build_succeeded",
                            row_id=f"index:{profile.name}",
                            profile=profile.name,
                            index_phase=profile_index_phase,
                        )
                index_phases.append({
                    "profile": profile.name,
                    "candidate_budget": candidate_k,
                    "index_build_reused": profile_reused_index,
                    "index_build_reused_for_profiles": list(
                        built_index_profile_names.get(profile_signature, [profile.name])
                    ),
                    "index_signature": serializable_index_signature(profile_signature),
                    "index_phase": profile_index_phase,
                })
            assert profile_index_phase is not None
            validate_serving_profile_index_reuse(
                args=focus_args,
                profile=profile,
                index_phase=profile_index_phase,
                expected_signature=profile_signature,
            )
            focus_args = clone_args(
                focus_args,
                serving_loaded_document_count=loaded_document_count(conn),
            )
            set_retrieval_gucs(conn, focus_args, "dbpedia_colbert_candidate_source_focus")
            exec_sql(
                conn,
                "SELECT set_config('turbohybrid.multivector_debug_admission', 'off', false)",
            )
            if recorder.enabled:
                recorder.record(
                    "query_evaluation_started",
                    row_id=row_id,
                    profile=profile.name,
                    candidate_budget=candidate_k,
                    query_count=len(selected_queries),
                )
            try:
                loop = run_serving_latency_query_loop(
                    conn,
                    focus_args,
                    selected_queries,
                    profile,
                )
            except Exception as exc:
                if recorder.enabled:
                    recorder.record(
                        "query_evaluation_failed",
                        row_id=row_id,
                        profile=profile.name,
                        candidate_budget=candidate_k,
                        error=str(exc),
                        error_type=type(exc).__name__,
                    )
                raise
            fail_on_serving_slow_path_if_requested(
                loop["serving_slow_path_warnings"],
                focus_args,
            )
            row = build_document_node_colbert_candidate_source_focus_row(
                args=args,
                profile=profile,
                candidate_k=candidate_k,
                effective_rerank_k=effective_rerank_k,
                index_phase=profile_index_phase,
                loop=loop,
                qrels=qrels,
                counts=counts,
                oracle_artifact=oracle_artifact,
                oracle_records=oracle_records,
            )
            row["index_signature"] = serializable_index_signature(profile_signature)
            row["index_build_reused"] = profile_reused_index
            row["index_build_reused_for_profiles"] = list(
                built_index_profile_names.get(profile_signature, [profile.name])
            )
            rows.append(row)
            if recorder.enabled:
                recorder.record(
                    "query_evaluation_succeeded",
                    row_id=row_id,
                    profile=profile.name,
                    candidate_budget=candidate_k,
                    row=row,
                )
            if loop.get("query_evaluation_failed") and bool(
                getattr(focus_args, "document_node_colbert_abort_profile_on_query_timeout", False)
            ):
                break
        if recorder.enabled:
            recorder.record(
                "profile_completed",
                row_id=f"profile:{profile.name}",
                profile=profile.name,
                budgets=budgets,
                rows=[
                    row
                    for row in rows
                    if isinstance(row, dict) and row.get("profile") == profile.name
                ],
            )
    recommendation = document_node_colbert_candidate_source_focus_recommendation(
        rows,
        docs_loaded=int(counts.get("docs_loaded", 0) or 0),
    )
    precompact_recommendation = (
        quantized_inverted_precompact_focus_recommendation(rows)
        if precompact_focus
        else None
    )
    exact_rerank_recommendation = (
        quantized_inverted_exact_rerank_focus_recommendation(rows)
        if exact_rerank_focus
        else None
    )
    return {
        "enabled": True,
        "pure_colbert_only": True,
        "quantized_inverted_precompact_focus": precompact_focus,
        "quantized_inverted_exact_rerank_focus": exact_rerank_focus,
        "exact_admission_available": "sampled" if oracle_artifact else False,
        "exact_admission_reason": (
            "sampled_exact_oracle_from_oracle_input"
            if oracle_artifact is not None
            else "not_requested"
        ),
        "admission_evidence": (
            "sampled_exact_oracle" if oracle_artifact is not None else "beir_qrels_only"
        ),
        "oracle_input": portable_path(args.oracle_input) if args.oracle_input else None,
        "oracle_query_count": len(oracle_records_all),
        "oracle_queries_compared": max(
            (int(row.get("oracle_queries_compared", 0) or 0) for row in rows),
            default=0,
        ),
        "oracle_queries_missing_loaded_embeddings": len(oracle_missing_loaded_query_ids),
        "missing_oracle_query_ids": oracle_missing_loaded_query_ids[:50],
        "profiles": [profile.name for profile in profiles],
        "candidate_budgets": budgets,
        "exact_rerank_k": int(getattr(args, "exact_rerank_k", 0) or 0),
        "centroid_lite_caps": centroid_lite_caps,
        "centroid_lite_probes": centroid_lite_probes,
        "centroid_lite_score_thresholds": centroid_lite_score_thresholds,
        "centroid_lite_score_drop_from_best_values": centroid_lite_score_drops,
        "quantized_inverted_precompact_score_grid": (
            effective_quantized_inverted_precompact_score_grid(args)
            if precompact_focus or exact_rerank_focus
            else []
        ),
        "quantized_inverted_precompact_coverage_k": (
            effective_quantized_inverted_precompact_coverage_k(args)
            if precompact_focus or exact_rerank_focus
            else 0
        ),
        "quantized_inverted_precompact_per_token_k": (
            effective_quantized_inverted_precompact_per_token_k(args)
            if precompact_focus or exact_rerank_focus
            else 0
        ),
        "quantized_inverted_precompact_active_query_tokens": (
            active_query_tokens if precompact_focus or exact_rerank_focus else 0
        ),
        "quantized_inverted_exact_rerank_grid": (
            effective_quantized_inverted_exact_rerank_grid(args)
            if exact_rerank_focus
            else []
        ),
        "quantized_inverted_exact_rerank_modes": (
            effective_quantized_inverted_exact_rerank_modes(args)
            if exact_rerank_focus
            else []
        ),
        "query_limit": query_limit,
        "queries_available": len(queries),
        "queries_evaluated": len(selected_queries),
        "docs": int(counts.get("docs_loaded", 0) or 0),
        "qrels_loaded": int(counts.get("qrels_loaded", 0) or 0),
        "experimental_included": bool(
            getattr(args, "include_quantized_inverted_experimental", False)
            or getattr(args, "document_node_colbert_include_experimental", False)
            or precompact_focus
            or exact_rerank_focus
        ),
        "index_phases": index_phases,
        "results": rows,
        "recommendation": recommendation,
        "precompact_recommendation": precompact_recommendation,
        "exact_rerank_recommendation": exact_rerank_recommendation,
        "total_elapsed_ms": elapsed_ms_since(started),
        "incremental_output": portable_path(recorder.path) if recorder.path else None,
        "incremental_records": len(recorder.records),
    }


def run_document_node_colbert_1m_beir_quality_only(
    conn: psycopg.Connection[Any],
    args: argparse.Namespace,
    queries: list[QueryItem],
    qrels: dict[str, dict[str, int]],
) -> dict[str, Any]:
    started = time.perf_counter()
    if not qrels:
        raise SystemExit(
            "--document-node-colbert-1m-beir-quality-only requires loaded qrels; "
            "reuse an imported DB with dbpedia_colbert_qrels or load BEIR qrels first"
        )
    query_limit = document_node_colbert_1m_query_limit_summary(
        requested_max_queries=int(getattr(args, "max_queries", 0) or 0),
        queries_loaded=len(queries),
        strict_query_count=bool(getattr(args, "strict_query_count", False)),
    )
    if query_limit["strict_query_count_failed"]:
        raise SystemExit(query_limit["strict_query_count_error"])
    effective_query_count = int(query_limit.get("effective_max_queries", 0) or 0)
    selected_queries = (
        queries[:effective_query_count] if effective_query_count > 0 else list(queries)
    )
    quality_args, profile, effective_rerank_k = document_node_colbert_beir_quality_args(args)
    index_phase = build_index(conn, quality_args)
    quality_args = clone_args(
        quality_args,
        serving_loaded_document_count=loaded_document_count(conn),
    )
    set_retrieval_gucs(conn, quality_args, "dbpedia_colbert_beir_quality_only")
    exec_sql(conn, "SELECT set_config('turbohybrid.multivector_debug_admission', 'off', false)")
    loop = run_serving_latency_query_loop(conn, quality_args, selected_queries, profile)
    fail_on_serving_slow_path_if_requested(
        loop["serving_slow_path_warnings"],
        quality_args,
    )
    counts = dbpedia_colbert_loaded_counts(conn)
    return build_document_node_colbert_beir_quality_report(
        args=args,
        profile=profile,
        effective_rerank_k=effective_rerank_k,
        index_phase=index_phase,
        loop=loop,
        qrels=qrels,
        counts=counts,
        query_limit=query_limit,
        started=started,
    )


SYNTHETIC_GATE_QUERY = """turbohybrid_multivector(ARRAY[
    '[1,0,0,0]'::vector,
    '[0,1,0,0]'::vector,
    '[0,0,1,0]'::vector,
    '[0,0,0,1]'::vector
])"""


def setup_multivector_recall_gate(conn: psycopg.Connection[Any]) -> None:
    exec_sql(conn, "CREATE EXTENSION IF NOT EXISTS vector")
    exec_sql(conn, "CREATE EXTENSION IF NOT EXISTS pgturbohybrid")
    load_pgturbohybrid_library(conn)
    exec_sql(conn, "DROP TABLE IF EXISTS mv_recall_gate_docs")
    exec_sql(
        conn,
        """
        CREATE TEMP TABLE mv_recall_gate_docs (
            id text PRIMARY KEY,
            colbert turbohybrid_multivector
        ) ON COMMIT PRESERVE ROWS
        """,
    )
    exec_sql(
        conn,
        """
        INSERT INTO mv_recall_gate_docs VALUES
          ('spike_1', turbohybrid_multivector(ARRAY['[1,0,0,0]'::vector])),
          ('spike_2', turbohybrid_multivector(ARRAY['[0,1,0,0]'::vector])),
          ('spike_3', turbohybrid_multivector(ARRAY['[0,0,1,0]'::vector])),
          ('spike_4', turbohybrid_multivector(ARRAY['[0,0,0,1]'::vector])),
          ('good', turbohybrid_multivector(ARRAY[
            '[0.8,0.6,0,0]'::vector,
            '[0.6,0.8,0,0]'::vector,
            '[0,0,0.8,0.6]'::vector,
            '[0,0,0.6,0.8]'::vector
          ]))
        """,
    )
    create_synthetic_gate_index(conn, "token_nodes")
    exec_sql(conn, "ANALYZE mv_recall_gate_docs")


def create_synthetic_gate_index(conn: psycopg.Connection[Any], graph_mode: str) -> None:
    if graph_mode not in {"token_nodes", "document_nodes"}:
        raise ValueError(f"unsupported synthetic gate graph mode: {graph_mode}")
    exec_sql(conn, "DROP INDEX IF EXISTS mv_recall_gate_docs_idx")
    exec_sql(
        conn,
        f"""
        CREATE INDEX mv_recall_gate_docs_idx ON mv_recall_gate_docs USING turbohybrid
          (colbert multivector_cosine_turbohybrid_ops)
          WITH (multivector_graph = {graph_mode},
                multivector_doc_build_scorer = proxy,
                exact_storage = off,
                graph_m = 4,
                graph_ef_construction = 8,
                graph_ef_search = 8)
        """,
    )


def synthetic_exact_top(conn: psycopg.Connection[Any], limit: int) -> list[dict[str, Any]]:
    rows = fetch_all(
        conn,
        f"""
        WITH q AS (SELECT {SYNTHETIC_GATE_QUERY} AS mv)
        SELECT d.id,
               d.ctid::text,
               turbohybrid_multivector_maxsim_distance(q.mv, d.colbert) AS distance
        FROM mv_recall_gate_docs d, q
        ORDER BY turbohybrid_multivector_maxsim_distance(q.mv, d.colbert), d.id
        LIMIT %s
        """,
        (limit,),
    )
    exact: list[dict[str, Any]] = []
    for rank, row in enumerate(rows, start=1):
        block, offset = tid_parts(str(row[1]))
        exact.append({
            "rank": rank,
            "doc_id": str(row[0]),
            "heap_block": block,
            "heap_offset": offset,
            "distance": float(row[2]),
            "maxsim": -float(row[2]),
        })
    return exact


def run_synthetic_exact_scan(conn: psycopg.Connection[Any], final_k: int) -> dict[str, Any]:
    started = time.perf_counter()
    rows = fetch_all(
        conn,
        f"""
        WITH q AS (SELECT {SYNTHETIC_GATE_QUERY} AS mv)
        SELECT d.id
        FROM mv_recall_gate_docs d, q
        ORDER BY turbohybrid_multivector_maxsim_distance(q.mv, d.colbert), d.id
        LIMIT %s
        """,
        (final_k,),
    )
    latency_ms = (time.perf_counter() - started) * 1000.0
    docs = [str(row[0]) for row in rows]
    return {
        "mode": "exact_scan",
        "candidate_source": "exact_scan",
        "result_doc_ids": docs,
        "top1": docs[0] if docs else None,
        "latency_ms": round(latency_ms, 3),
        "latency": summarize_ms([latency_ms]),
        "exact_top1_admitted_before_rerank": True,
        "exact_top10_admission_recall": 1.0,
        "doc_candidates": len(docs),
        "exact_rerank_docs": len(docs),
        "memory_bytes_estimate": 0,
        "scan_stats": {},
    }


def run_synthetic_gate_mode(
    conn: psycopg.Connection[Any],
    mode: dict[str, str],
    exact_top: list[dict[str, Any]],
    budget: int,
    final_k: int,
) -> dict[str, Any]:
    create_synthetic_gate_index(conn, mode.get("graph_mode", "token_nodes"))
    settings = {
        "enable_seqscan": "off",
        "jit": "off",
        "turbohybrid.multivector_subvector_k": "1",
        "turbohybrid.multivector_unique_docs_per_token": "1",
        "turbohybrid.multivector_max_raw_hits_per_token": "1",
        "turbohybrid.multivector_doc_candidate_k": str(budget),
        "turbohybrid.multivector_exact_rerank_k": str(max(budget, final_k, 10)),
        "turbohybrid.multivector_adaptive_widening": "off",
        "turbohybrid.multivector_candidate_source": mode["candidate_source"],
        "turbohybrid.multivector_plain_fallback": mode["plain_fallback"],
        "turbohybrid.multivector_candidate_reservoirs": mode["reservoirs"],
        "turbohybrid.multivector_debug_admission": "trace",
        "turbohybrid.multivector_debug_trace_limit": "1000",
    }
    for key, value in settings.items():
        exec_sql(conn, "SELECT set_config(%s, %s, false)", (key, value))

    started = time.perf_counter()
    rows = fetch_all(
        conn,
        f"""
        WITH q AS (SELECT {SYNTHETIC_GATE_QUERY} AS mv)
        SELECT d.id
        FROM mv_recall_gate_docs d, q
        ORDER BY d.colbert <~> turbohybrid_query(
            multivector_query => q.mv,
            dense_k => %s,
            final_k => %s
        )
        LIMIT %s
        """,
        (budget, final_k, final_k),
    )
    latency_ms = (time.perf_counter() - started) * 1000.0
    docs = [str(row[0]) for row in rows]
    stats = last_scan_stats(conn)
    trace = stats.get("multivector_admission_trace")
    trace_entries = trace if isinstance(trace, list) else []
    trace_by_heap = {
        key: entry
        for entry in trace_entries
        if isinstance(entry, dict) and (key := trace_key(entry)) is not None
    }
    inferred_exact_doc_admission = (
        not trace_by_heap
        and can_infer_admission_from_result_docs(
            mode["candidate_source"],
            plain_fallback=mode["plain_fallback"],
            graph_mode=mode.get("graph_mode"),
        )
    )
    exact_with_admission: list[dict[str, Any]] = []
    for exact in exact_top:
        key = (int(exact["heap_block"]), int(exact["heap_offset"]))
        entry = trace_by_heap.get(key)
        result_rank = docs.index(exact["doc_id"]) + 1 if exact["doc_id"] in docs else None
        admitted = entry is not None or (inferred_exact_doc_admission and result_rank is not None)
        admission_evidence = (
            "trace"
            if entry is not None
            else "result_doc"
            if inferred_exact_doc_admission and result_rank is not None
            else "missing"
        )
        exact_with_admission.append({
            "rank": exact["rank"],
            "doc_id": exact["doc_id"],
            "admitted_before_rerank": admitted,
            "admission_evidence": admission_evidence,
            "exact_rerank_rank": result_rank,
            "candidate_rank_before_rerank": (
                int(entry["candidate_rank_before_truncation"])
                if isinstance(entry, dict) and entry.get("candidate_rank_before_truncation") is not None
                else None
            ),
        })
    top = exact_with_admission[: min(10, len(exact_with_admission))]
    admitted_count = sum(1 for item in top if item["admitted_before_rerank"])
    return {
        "mode": mode["name"],
        "candidate_source": stats.get("multivector_candidate_source"),
        "configured_candidate_source": mode["candidate_source"],
        "graph_mode": stats.get("multivector_graph_mode"),
        "configured_graph_mode": mode.get("graph_mode", "token_nodes"),
        "plain_fallback": mode["plain_fallback"],
        "reservoirs": mode["reservoirs"],
        "result_doc_ids": docs,
        "top1": docs[0] if docs else None,
        "latency_ms": round(latency_ms, 3),
        "latency": summarize_ms([latency_ms]),
        "exact_top1_admitted_before_rerank": bool(exact_with_admission and exact_with_admission[0]["admitted_before_rerank"]),
        "exact_top10_admission_recall": round(admitted_count / len(top), 6) if top else 0.0,
        "doc_candidates": max(
            scan_stat_int(stats, "multivector_doc_candidates"),
            scan_stat_int(stats, "multivector_doc_graph_candidates"),
        ),
        "exact_rerank_docs": max(
            scan_stat_int(stats, "multivector_exact_rerank_docs"),
            scan_stat_int(stats, "multivector_doc_graph_exact_rerank_docs"),
        ),
        **exact_rerank_work_from_stats(stats),
        **proxy_work_from_stats(stats),
        "memory_bytes_estimate": memory_estimate_from_stats(stats),
        "raw_subvector_hits": scan_stat_int(stats, "multivector_raw_subvector_hits"),
        "unique_docs": scan_stat_int(stats, "multivector_unique_docs"),
        "trace_entries": len(trace_entries),
        "admission_inferred_from_result_docs": inferred_exact_doc_admission,
        "exact_top": exact_with_admission,
        "scan_stats": stats,
    }


def markdown_recall_gate_summary(report: dict[str, Any]) -> str:
    status = "PASS" if report["passed"] else "FAIL"
    lines = [
        "## Multivector Recall Gate",
        "",
        f"Status: **{status}**",
        "",
        f"- Dataset: `{report['dataset']}`",
        f"- Exact top-1: `{report['exact_top1']}`",
        f"- Small candidate budget: `{report['candidate_budget']}`",
        f"- DBpedia data: `{report['dbpedia_status']}`",
        "",
        "| mode | top1 | top1 admitted | top10 admission recall | p50 ms | p95 ms | candidates | exact rerank docs | memory bytes |",
        "|---|---:|---:|---:|---:|---:|---:|---:|---:|",
    ]
    for item in report["results"]:
        latency = item.get("latency", {})
        lines.append(
            "| {mode} | {top1} | {admitted} | {recall:.3f} | {p50:.3f} | {p95:.3f} | {candidates} | {rerank} | {memory} |".format(
                mode=item["mode"],
                top1=item.get("top1"),
                admitted="yes" if item.get("exact_top1_admitted_before_rerank") else "no",
                recall=float(item.get("exact_top10_admission_recall", 0.0)),
                p50=float(latency.get("p50_ms", 0.0)),
                p95=float(latency.get("p95_ms", 0.0)),
                candidates=item.get("doc_candidates", 0),
                rerank=item.get("exact_rerank_docs", 0),
                memory=item.get("memory_bytes_estimate", 0),
            )
        )
    lines.extend([
        "",
        "Gate condition: `exact_scan`, `plain_fallback`, `exact_doc_scan`, "
        "`doc_graph_prototype`, `document_nodes`, and `proxy_vector` must return "
        "and admit the synthetic exact top-1 document at the configured small candidate "
        "budget. DBpedia admission reporting remains optional and is run with "
        "`--admission-debug` when local data is available.",
        "",
    ])
    return "\n".join(lines)


def markdown_learned_sparse_jsonl_validation(report: dict[str, Any]) -> str:
    validation = report.get("learned_sparse_jsonl_validation", {})
    if not isinstance(validation, dict):
        validation = {}
    warnings = validation.get("warnings", [])
    if not isinstance(warnings, list):
        warnings = []
    lines = [
        "## Learned-sparse JSONL validation",
        "",
        f"- Database: `{validation.get('database', '')}`",
        f"- Document JSONL: `{validation.get('doc_jsonl', '')}`",
        f"- Query JSONL: `{validation.get('query_jsonl', '')}`",
        f"- Strict mode: `{bool(validation.get('strict', False))}`",
        f"- Safe serving evidence: `{bool(validation.get('safe_serving_evidence', False))}`",
        f"- Plumbing only: `{bool(validation.get('plumbing_only', False))}`",
        f"- Feature source: `{validation.get('feature_source', '')}`",
        f"- Feature version: `{validation.get('feature_version', '')}`",
        f"- Elapsed: `{float(validation.get('elapsed_ms', 0.0) or 0.0):.3f} ms`",
        "",
        "| side | expected | rows | coverage | missing | duplicate rows | extra |",
        "|---|---:|---:|---:|---:|---:|---:|",
        "| docs | {expected} | {rows} | {coverage:.6f} | {missing} | {duplicates} | {extra} |".format(
            expected=int(validation.get("expected_doc_count", 0) or 0),
            rows=int(validation.get("doc_rows", 0) or 0),
            coverage=float(validation.get("doc_coverage", 0.0) or 0.0),
            missing=int(validation.get("missing_doc_count", 0) or 0),
            duplicates=int(validation.get("duplicate_doc_count", 0) or 0),
            extra=int(validation.get("extra_doc_count", 0) or 0),
        ),
        "| queries | {expected} | {rows} | {coverage:.6f} | {missing} | {duplicates} | {extra} |".format(
            expected=int(validation.get("expected_query_count", 0) or 0),
            rows=int(validation.get("query_rows", 0) or 0),
            coverage=float(validation.get("query_coverage", 0.0) or 0.0),
            missing=int(validation.get("missing_query_count", 0) or 0),
            duplicates=int(validation.get("duplicate_query_count", 0) or 0),
            extra=int(validation.get("extra_query_count", 0) or 0),
        ),
        "",
        "This mode validates sparse feature files only. It does not build indexes, run retrieval, or run exact scans.",
    ]
    if warnings:
        lines.extend([
            "",
            "Warnings:",
            "",
        ])
        lines.extend(f"- `{warning}`" for warning in warnings)
    return "\n".join(lines) + "\n"


def markdown_benchmark_summary(report: dict[str, Any]) -> str:
    dataset = report.get("dataset", {})
    settings = report.get("settings", {})
    lines = [
        "## DBpedia ColBERT Multivector Benchmark",
        "",
        f"- Documents: `{dataset.get('documents', 0)}`",
        f"- Queries: `{dataset.get('queries', 0)}`",
        f"- Qrels: `{dataset.get('qrels', 0)}`",
        f"- Final K: `{settings.get('final_k', 0)}`",
        f"- Clients: `{settings.get('clients', 0)}`",
        f"- Multivector graph: `{settings.get('multivector_graph', '')}`",
        f"- Candidate source: `{settings.get('multivector_candidate_source', '')}`",
        f"- Sparse candidate source: `{settings.get('multivector_sparse_candidate_source', '')}`",
        f"- Token pooling: `{settings.get('multivector_token_pooling', '')}`",
        f"- Token pooling target ratio: `{settings.get('multivector_token_pooling_target_ratio', '')}`",
        f"- Centroids: `{settings.get('multivector_centroids', '')}`",
        f"- Centroid count: `{settings.get('multivector_centroid_count', '')}`",
        f"- Proxy encoder: `{settings.get('multivector_proxy_encoder', '')}`",
        f"- Doc graph search EF: `{settings.get('multivector_doc_graph_search_ef', 0)}`",
        f"- Doc graph oversampling: `{settings.get('multivector_doc_graph_oversampling', 1)}`",
        f"- Doc graph rescore K: `{settings.get('multivector_doc_graph_rescore_k', 0)}`",
        f"- Doc graph entry sample count: `{settings.get('multivector_doc_graph_entry_sample_count', 0)}`",
        f"- Plain fallback: `{settings.get('multivector_plain_fallback', '')}`",
        f"- Reservoirs: `{settings.get('multivector_candidate_reservoirs', '')}`",
        "",
        "| method | recall@10 | ndcg@10 | serial p50 ms | serial p95 ms | 8x qps |",
        "|---|---:|---:|---:|---:|---:|",
    ]
    for item in report.get("results", []):
        metrics = item.get("metrics", {})
        serial = item.get("serial_latency", {})
        parallel = item.get("parallel_8x", {})
        lines.append(
            "| {method} | {recall:.6f} | {ndcg:.6f} | {p50:.3f} | {p95:.3f} | {qps:.3f} |".format(
                method=item.get("method", ""),
                recall=float(metrics.get("recall@10", 0.0)),
                ndcg=float(metrics.get("ndcg@10", 0.0)),
                p50=float(serial.get("p50_ms", 0.0)),
                p95=float(serial.get("p95_ms", 0.0)),
                qps=float(parallel.get("throughput_qps", 0.0)),
            )
        )
    skipped_parallel = [
        item
        for item in report.get("results", [])
        if isinstance(item, dict)
        and isinstance(item.get("parallel_8x"), dict)
        and item["parallel_8x"].get("skipped") is True
    ]
    failed_parallel = [
        item
        for item in report.get("results", [])
        if isinstance(item, dict)
        and isinstance(item.get("parallel_8x"), dict)
        and item["parallel_8x"].get("failed") is True
    ]
    if skipped_parallel or failed_parallel:
        lines.extend([
            "",
            "### Parallel Retrieval Notes",
            "",
        ])
        for item in skipped_parallel:
            parallel = item["parallel_8x"]
            lines.append(
                "- `{method}` skipped 8x retrieval: {reason}".format(
                    method=item.get("method", ""),
                    reason=parallel.get("skip_reason", ""),
                )
            )
        for item in failed_parallel:
            parallel = item["parallel_8x"]
            lines.append(
                "- `{method}` failed 8x retrieval: {error}".format(
                    method=item.get("method", ""),
                    error=parallel.get("error", ""),
                )
            )

    phases = report.get("phases", {})
    learned_sparse_phase = {}
    if isinstance(phases, dict):
        candidate_phase = phases.get("load_learned_sparse_vectors", {})
        if isinstance(candidate_phase, dict):
            learned_sparse_phase = candidate_phase
    if learned_sparse_phase and not bool(learned_sparse_phase.get("skipped", False)):
        coverage = learned_sparse_phase.get("coverage", {})
        if not isinstance(coverage, dict):
            coverage = {}
        warnings = learned_sparse_phase.get("warnings", coverage.get("warnings", []))
        if not isinstance(warnings, list):
            warnings = []
        doc_ratio = coverage.get("doc_coverage_ratio")
        query_ratio = coverage.get("query_coverage_ratio")
        lines.extend([
            "",
            "### Learned-sparse fixture coverage",
            "",
            f"- Documents covered: `{int(coverage.get('learned_sparse_documents', 0) or 0)}` / `{int(coverage.get('loaded_documents', 0) or 0)}`",
            f"- Document coverage ratio: `{float(doc_ratio) if doc_ratio is not None else 0.0:.6f}`",
            f"- Queries covered: `{int(coverage.get('learned_sparse_queries', 0) or 0)}` / `{int(coverage.get('loaded_queries', 0) or 0)}`",
            f"- Query coverage ratio: `{float(query_ratio) if query_ratio is not None else 0.0:.6f}`",
            f"- Partial coverage: `{bool(learned_sparse_phase.get('partial_coverage', coverage.get('partial_coverage', False)))}`",
        ])
        if warnings:
            lines.append("- Warnings: `" + ",".join(str(item) for item in warnings) + "`")
            lines.append(
                "- Learned-sparse rescue results with partial fixture coverage are "
                "candidate-source plumbing evidence, not production serving evidence."
            )
        else:
            lines.append("- Warnings: `none`")

    admission = report.get("admission_debug")
    if isinstance(admission, dict):
        aggregate = admission.get("aggregate", {})
        first_budget = aggregate.get("exact_top1_first_budget_admitted", {})
        lines.extend([
            "",
            "### Admission Debug",
            "",
            f"- Candidate source: `{admission.get('candidate_source', '')}`",
            f"- Sparse candidate source: `{admission.get('sparse_candidate_source', '')}`",
            f"- Plain fallback: `{admission.get('plain_fallback', '')}`",
            f"- Reservoirs: `{admission.get('candidate_reservoirs', '')}`",
            f"- Admission K: `{aggregate.get('admission_k', 0)}`",
            f"- Admission debug mode: `{aggregate.get('admission_debug_mode', 'trace')}`",
            f"- Trace enabled: `{bool(aggregate.get('trace_enabled', False))}`",
            f"- Admission evidence mode: `{aggregate.get('admission_evidence_mode', 'unavailable')}`",
            f"- Trace entries: `{int(aggregate.get('trace_entries', 0) or 0)}`",
            f"- Exact rerank mode: `{aggregate.get('serving_exact_rerank_mode', 'admission_exhaustive')}`",
            f"- Requested serving exact rerank K: `{int(aggregate.get('requested_serving_exact_rerank_k', 0) or 0)}`",
            f"- Exact top-1 admission rate: `{float(aggregate.get('exact_top1_admission_rate', 0.0)):.6f}`",
            f"- Exact top-10 admission recall: `{float(aggregate.get('exact_top10_admission_recall', 0.0)):.6f}`",
            f"- First admitted budget p50: `{first_budget.get('p50', 0)}`",
            "",
            "| candidate budget | exact rerank k | top1 admission | top10 admission recall | latency p50 ms | latency p95 ms | docs scored p50 | graph edges p50 | exact rerank docs p50 | pairs saved p50 | runs |",
            "|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|",
        ])
        admission_by_budget = aggregate.get("admission_by_budget", {})
        if isinstance(admission_by_budget, dict):
            for budget, budget_stats in sorted(admission_by_budget.items(), key=lambda item: int(item[0])):
                if not isinstance(budget_stats, dict):
                    continue
                latency = budget_stats.get("latency", {})
                docs_scored = budget_stats.get("docs_scored", {})
                graph_edges = budget_stats.get("graph_edges_visited", {})
                exact_rerank_docs = budget_stats.get("exact_rerank_docs", {})
                exact_rerank_pairs_saved = budget_stats.get("exact_rerank_pairs_saved", {})
                if not isinstance(latency, dict):
                    latency = {}
                if not isinstance(docs_scored, dict):
                    docs_scored = {}
                if not isinstance(graph_edges, dict):
                    graph_edges = {}
                if not isinstance(exact_rerank_docs, dict):
                    exact_rerank_docs = {}
                if not isinstance(exact_rerank_pairs_saved, dict):
                    exact_rerank_pairs_saved = {}
                lines.append(
                    "| {budget} | {exact_k} | {top1:.6f} | {top10:.6f} | {p50:.3f} | {p95:.3f} | {docs_p50:.3f} | {edges_p50:.3f} | {rerank_p50:.3f} | {pairs_saved_p50:.3f} | {runs} |".format(
                        budget=budget,
                        exact_k=int(budget_stats.get("effective_exact_rerank_k", 0) or 0),
                        top1=float(budget_stats.get("exact_top1_admission", 0.0)),
                        top10=float(budget_stats.get("exact_top10_admission_recall", 0.0)),
                        p50=float(latency.get("p50_ms", 0.0)),
                        p95=float(latency.get("p95_ms", 0.0)),
                        docs_p50=float(docs_scored.get("p50", 0.0)),
                        edges_p50=float(graph_edges.get("p50", 0.0)),
                        rerank_p50=float(exact_rerank_docs.get("p50", 0.0)),
                        pairs_saved_p50=float(exact_rerank_pairs_saved.get("p50", 0.0)),
                        runs=int(latency.get("runs", 0)),
                    )
                )
        lines.extend([
            "",
            "Admission debug compares exact document top-K with the candidate set "
            "before exact rerank. Improvements here mean better admission; unchanged "
            "admission with different final metrics should be treated as reranking or "
            "metric variance until proven otherwise.",
        ])

    admission_grid = report.get("document_node_admission_grid")
    if isinstance(admission_grid, dict):
        pooling_grid_text = ",".join(
            "{mode}:{ratio}".format(mode=item.get("mode"), ratio=item.get("ratio"))
            for item in admission_grid.get("pooling_grid", [])
            if isinstance(item, dict)
        )
        lines.extend([
            "",
            "### Document-Node Admission Grid",
            "",
            f"- Rebuilds index: `{admission_grid.get('rebuilds_index', False)}`",
            f"- Budget sweep: `{','.join(str(item) for item in admission_grid.get('budget_sweep', []))}`",
            f"- Storage grid: `{','.join(str(item) for item in admission_grid.get('storage_grid', []))}`",
            f"- Pooling grid: `{pooling_grid_text}`",
            f"- EF grid: `{','.join(str(item) for item in admission_grid.get('ef_grid', []))}`",
            f"- Oversampling grid: `{','.join(str(item) for item in admission_grid.get('oversampling_grid', []))}`",
            f"- Index graph build: `m={admission_grid.get('index_graph_m', 0)}, ef_construction={admission_grid.get('index_graph_ef_construction', 0)}, ef_search={admission_grid.get('index_graph_ef_search', 0)}, native_segments={admission_grid.get('index_native_segments', 0)}`",
            "",
            "| mode | graph | storage | pooling | ratio | ef | oversampling | budget | top1 admission | top10 admission recall | recall@10 | ndcg@10 | mrr@10 | p50 ms | p95 ms | docs scored p50 | edges p50 | exact rerank p50 | native exact bytes p50 |",
            "|---|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|",
        ])
        grid_results = admission_grid.get("results", [])
        if isinstance(grid_results, list):
            for item in grid_results:
                if not isinstance(item, dict):
                    continue
                budget = item.get("largest_budget")
                admission_by_budget = item.get("admission_by_budget", {})
                budget_stats = {}
                if isinstance(admission_by_budget, dict) and budget is not None:
                    budget_stats = admission_by_budget.get(str(budget), {})
                    if not isinstance(budget_stats, dict):
                        budget_stats = {}
                latency = budget_stats.get("latency", {}) if isinstance(budget_stats, dict) else {}
                docs_scored = budget_stats.get("docs_scored", {}) if isinstance(budget_stats, dict) else {}
                graph_edges = budget_stats.get("graph_edges_visited", {}) if isinstance(budget_stats, dict) else {}
                exact_rerank_docs = budget_stats.get("exact_rerank_docs", {}) if isinstance(budget_stats, dict) else {}
                native_cache_exact = budget_stats.get("native_cache_exact_bytes", {}) if isinstance(budget_stats, dict) else {}
                metrics = item.get("metrics", {})
                if not isinstance(latency, dict):
                    latency = {}
                if not isinstance(docs_scored, dict):
                    docs_scored = {}
                if not isinstance(graph_edges, dict):
                    graph_edges = {}
                if not isinstance(exact_rerank_docs, dict):
                    exact_rerank_docs = {}
                if not isinstance(native_cache_exact, dict):
                    native_cache_exact = {}
                if not isinstance(metrics, dict):
                    metrics = {}
                lines.append(
                    "| {mode} | {graph} | {storage} | {pooling} | {ratio:.2f} | {ef} | {oversampling} | {budget} | {top1:.6f} | {top10:.6f} | {recall:.6f} | {ndcg:.6f} | {mrr:.6f} | {p50:.3f} | {p95:.3f} | {docs:.3f} | {edges:.3f} | {rerank:.3f} | {native_exact:.3f} |".format(
                        mode=item.get("mode", ""),
                        graph=item.get("graph_mode", ""),
                        storage=item.get("storage_kind", ""),
                        pooling=item.get("token_pooling", ""),
                        ratio=float(item.get("token_pooling_target_ratio", 1.0) or 1.0),
                        ef=int(item.get("doc_graph_search_ef", 0) or 0),
                        oversampling=int(item.get("doc_graph_oversampling", 0) or 0),
                        budget=budget or "",
                        top1=float(item.get("exact_top1_admission_rate", 0.0)),
                        top10=float(item.get("exact_top10_admission_recall", 0.0)),
                        recall=float(metrics.get("recall@10", 0.0)),
                        ndcg=float(metrics.get("ndcg@10", 0.0)),
                        mrr=float(metrics.get("mrr@10", 0.0)),
                        p50=float(latency.get("p50_ms", 0.0)),
                        p95=float(latency.get("p95_ms", 0.0)),
                        docs=float(docs_scored.get("p50", 0.0)),
                        edges=float(graph_edges.get("p50", 0.0)),
                        rerank=float(exact_rerank_docs.get("p50", 0.0)),
                        native_exact=float(native_cache_exact.get("p50", 0.0)),
                    )
                )
        lines.extend([
            "",
            "The grid rebuilds token-node and document-node index layouts so the "
            "report can compare token baselines with document-node admission. "
            "Document-sidecar page/cache counters are emitted when the engine "
            "exposes them; until then the table includes native cache exact-byte "
            "counters as the available storage footprint signal.",
        ])

    build_only = report.get("document_node_serving_build_only")
    if isinstance(build_only, dict):
        rows = build_only.get("results", [])
        if isinstance(rows, list):
            sorted_rows = sorted(
                [item for item in rows if isinstance(item, dict)],
                key=lambda item: (
                    float(item.get("index_build_elapsed_ms", 0.0) or 0.0),
                    str(item.get("profile", "")),
                ),
                reverse=True,
            )
        else:
            sorted_rows = []
        lines.extend([
            "",
            "### Document-node serving build-only",
            "",
            f"- Retrieval skipped: `{bool(build_only.get('retrieval_skipped', False))}`",
            f"- Admission skipped: `{bool(build_only.get('admission_skipped', False))}`",
            f"- Total elapsed: `{float(build_only.get('total_elapsed_ms', 0.0) or 0.0):.3f} ms`",
            f"- Index build elapsed: `{float(build_only.get('index_build_elapsed_ms_total', 0.0) or 0.0):.3f} ms` across `{int(build_only.get('index_builds', 0) or 0)}` builds",
            f"- Index build groups: `{int(build_only.get('index_build_group_count', 0) or 0)}`; reuses: `{int(build_only.get('index_reuse_count', 0) or 0)}`",
            f"- Effective profiles: `{','.join(str(item) for item in build_only.get('effective_profiles', []))}`",
            "",
            "#### Build acceptance summary",
            "",
        ])
        build_acceptance = build_only.get("build_acceptance_summary", {})
        if not isinstance(build_acceptance, dict):
            build_acceptance = {}
        warning_counts = build_acceptance.get("build_slow_warning_counts", {})
        if not isinstance(warning_counts, dict):
            warning_counts = {}
        dominant_counts = build_acceptance.get("dominant_build_phase_counts", {})
        if not isinstance(dominant_counts, dict):
            dominant_counts = {}
        unique_profiles = build_acceptance.get("profiles_requiring_unique_index", [])
